/* 10 điểm ngữ pháp nâng cao (B2 và C1), gắn vào GRAMMAR, GRAMMAR_BANK, GRAMMAR_THEORY, GRAMMAR_GX và vào các chặng tương ứng. Nạp sau content-grammar2.js. */
(function () {
  const NEW = [{"id":"adjective-gradability","lvl":"B2","title":"Gradable and ungradable adjectives, adjective order, intensifiers","vi":"Tính từ gradable/ungradable, thứ tự tính từ, từ nhấn mạnh","exams":["CEFR","VSTEP","IELTS"],"form":"very/extremely/rather + tính từ gradable (cold, tired).\nabsolutely/completely/totally + tính từ ungradable (freezing, exhausted).\nThứ tự: ý kiến – kích cỡ – tuổi – hình dạng – màu – xuất xứ – chất liệu – mục đích + danh từ.","use":"Dùng để chọn đúng từ nhấn mạnh cho từng loại tính từ và sắp xếp nhiều tính từ trước danh từ theo thứ tự tự nhiên. Cũng giúp phân biệt tính từ -ing và -ed.","ex":[["The lecture was extremely boring, but the discussion afterwards was absolutely fascinating.","Bài giảng cực kỳ chán, nhưng buổi thảo luận sau đó thì hoàn toàn cuốn hút."],["She was completely exhausted after the night shift.","Cô ấy hoàn toàn kiệt sức sau ca trực đêm."],["The clinic is in a lovely old brick building.","Phòng khám nằm trong một toà nhà gạch cũ rất đẹp."],["I was rather disappointed with the results.","Tôi khá thất vọng với kết quả."]],"err":[["The water was absolutely cold.","The water was very cold. / The water was absolutely freezing.","“Cold” là tính từ gradable nên đi với “very”; “absolutely” chỉ đi với tính từ ungradable như “freezing”."],["She bought a black big leather bag.","She bought a big black leather bag.","Kích cỡ đứng trước màu sắc, và chất liệu đứng gần danh từ nhất."],["The film was very bored.","The film was very boring.","Tính từ -ing mô tả thứ gây ra cảm giác; -ed mô tả người cảm thấy."]],"quiz":[["After the double shift, the nurses were ___ exhausted.",["very","fairly","absolutely","rather"],2,"“Exhausted” là tính từ ungradable (đã mang nghĩa cực mệt) nên đi với “absolutely”; cụm “double shift” cho thấy mức kiệt sức tuyệt đối.",{"very":"“Very” dùng cho tính từ gradable như “tired”, không đi với “exhausted” vốn đã ở mức cực đại.","fairly":"“Fairly” chỉ mức vừa phải, mâu thuẫn với nghĩa kiệt sức hoàn toàn của “exhausted”.","rather":"“Rather” là từ chỉ mức khá cho tính từ gradable, không hợp với “exhausted”."}],["I'd say the exam was ___ difficult, but not impossible.",["absolutely","completely","totally","fairly"],3,"“Difficult” là tính từ gradable nên dùng “fairly”; vế sau “but not impossible” cho thấy mức độ chưa tuyệt đối.",{"absolutely":"“Absolutely” chỉ đi với tính từ ungradable, còn “difficult” có thể mạnh yếu khác nhau.","completely":"“Completely” mang nghĩa hoàn toàn nên không hợp với tính từ gradable “difficult” trong câu này.","totally":"“Totally” là từ nhấn mạnh cho tính từ ungradable, không đứng trước “difficult”."}],["It was ___ impossible to park near the hospital on Monday.",["very","extremely","fairly","completely"],3,"“Impossible” là tính từ ungradable nên cần “completely”; “very”, “extremely” và “fairly” dành cho tính từ gradable.",{"very":"“Very” không đi với “impossible” vì việc đã là không thể thì không có mức độ.","extremely":"“Extremely” là từ nhấn mạnh cho tính từ gradable, không hợp với “impossible”.","fairly":"“Fairly” chỉ mức vừa phải, không thể nói việc gì đó “khá không thể”."}],["She was carrying a ___ bag.",["leather brown small","small brown leather","brown small leather","leather small brown"],1,"Thứ tự là kích cỡ, màu sắc, chất liệu rồi mới đến danh từ: small (size) – brown (colour) – leather (material).",{"leather brown small":"Chất liệu “leather” phải đứng gần danh từ nhất, không được đứng đầu chuỗi tính từ.","brown small leather":"Kích cỡ “small” phải đứng trước màu “brown”, nên “brown small” sai thứ tự.","leather small brown":"Chất liệu “leather” đứng đầu là sai, và kích cỡ cũng phải đứng trước màu."}]]},{"id":"adverbial-clauses","lvl":"C1","title":"Adverbial clauses of purpose, result, reason and concession (advanced)","vi":"Mệnh đề trạng ngữ nâng cao: mục đích, kết quả, lý do, nhượng bộ","exams":["CEFR","VSTEP","IELTS"],"form":"Mục đích: so that / in order that + S + can/will/would; so as (not) to + V; lest + S + (should) V.\nKết quả: so + adj/adv + that; such + (a) + adj + N + that.\nNhượng bộ: Adj + as/though + S + V; whatever/however + adj + S + V.","use":"Dùng để nối ý chính xác và trang trọng trong bài viết học thuật, báo cáo hoặc bài nói: nêu mục đích, mức độ dẫn đến kết quả, lý do đã biết và sự nhượng bộ.","ex":[["The clinic opened early so that shift workers could attend appointments.","Phòng khám mở cửa sớm để những người làm ca có thể đến khám."],["The data were so incomplete that no firm conclusion could be drawn.","Dữ liệu thiếu đến mức không thể rút ra kết luận chắc chắn nào."],["Given that funding is limited, the trial will recruit only fifty patients.","Do kinh phí có hạn, thử nghiệm sẽ chỉ tuyển năm mươi bệnh nhân."],["Much as I admire her research, I cannot accept her conclusion.","Dù rất ngưỡng mộ nghiên cứu của cô ấy, tôi không thể chấp nhận kết luận đó."]],"err":[["She spoke quietly so as not disturb the patients.","She spoke quietly so as not to disturb the patients.","Sau “so as not” phải có “to” + V nguyên mẫu: “so as not to disturb”."],["It was so cold weather that we cancelled the trip.","It was such cold weather that we cancelled the trip.","Trước danh từ (dù có tính từ) dùng “such”: “such cold weather”. “So” chỉ đứng trước tính từ/trạng từ đứng một mình."],["Although the results were promising, but we remain cautious.","Although the results were promising, we remain cautious.","Không dùng “but” cùng “although” trong một câu; một mệnh đề nhượng bộ đã đủ nối ý."]],"quiz":[["The ward keeps a night light on ___ patients can find the bathroom safely.",["so that","so as to","in order to","lest"],0,"Hai vế có chủ ngữ khác nhau (ward/patients) và có “can”, nên cần “so that” để nêu mục đích bằng một mệnh đề đầy đủ.",{"so as to":"“So as to” cần động từ nguyên mẫu ngay sau, trong khi ở đây có chủ ngữ riêng “patients” và động từ “can find”.","in order to":"“In order to” chỉ đi với V nguyên mẫu, không đứng trước mệnh đề có chủ ngữ “patients”.","lest":"“Lest” diễn tả điều muốn tránh; ở đây mục đích là điều tích cực nên không hợp nghĩa."}],["She repeated the instructions slowly so as ___ confuse the new volunteers.",["to not","not to","not","that not"],1,"Cùng chủ ngữ (she) nên dùng “so as not to + V” để nêu mục đích phủ định; “not” phải đứng trước “to”.",{"to not":"Dạng “so as to not” bị coi là kém chuẩn trong văn viết trang trọng; phủ định phải đặt “not” trước “to”.","not":"Thiếu “to”: sau “so as not” bắt buộc có “to” + V nguyên mẫu.","that not":"Không có cấu trúc “so as that not”; “so that” mới đi với mệnh đề."}],["The report was ___ badly written that the committee asked for a full revision.",["such","very","so","too"],2,"“So + trạng từ/tính từ + that” chỉ mức độ dẫn đến kết quả; “badly” là trạng từ và vế sau “that the committee asked …” là kết quả.",{"such":"“Such” đi với danh từ; ở đây “badly” là trạng từ nên không dùng “such”.","very":"“Very” không dẫn vào mệnh đề kết quả “that …”, nên câu thiếu liên kết nghĩa.","too":"“Too” cần “to + V”, không tạo mệnh đề kết quả với “that” ở đây."}],["It was ___ a persuasive argument that even the critics were won over.",["so","too","very","such"],3,"Sau chỗ trống là “a persuasive argument” (a + adj + N), nên dùng “such a … that” để nêu kết quả.",{"so":"“So” không đứng trực tiếp trước “a + tính từ + danh từ”; phải đổi thành “so persuasive an argument”.","too":"“Too” không dùng với “that” để nêu kết quả và không hợp trước “a persuasive argument”.","very":"“Very” không thể đứng trước “a”; ngoài ra nó không dẫn vào mệnh đề kết quả."}]]},{"id":"articles-advanced","lvl":"B2","title":"Articles in depth: generic reference and fixed uses","vi":"Mạo từ nâng cao: nghĩa chung và cách dùng cố định","exams":["CEFR","VSTEP","IELTS"],"form":"Nghĩa chung: The + N số ít / Ø + N số nhiều / a + N số ít.\nThe + tính từ = nhóm người (the elderly). Ø: bữa ăn, bệnh, phương tiện, in hospital.","use":"Dùng để nói về cả một loài hay nhóm (The tiger is…, Tigers are…), và để nhớ các cụm cố định không có mạo từ (at university, by bus, have flu) hoặc có the (the Nile, the Alps).","ex":[["The tiger is an endangered species.","Hổ là một loài có nguy cơ tuyệt chủng."],["The elderly need better access to health care.","Người cao tuổi cần được tiếp cận chăm sóc sức khoẻ tốt hơn."],["My brother is in hospital with pneumonia.","Anh tôi đang nằm viện vì viêm phổi."],["The Danube flows through several countries.","Sông Danube chảy qua nhiều quốc gia."]],"err":[["The life is full of surprises.","Life is full of surprises.","Danh từ trừu tượng nói chung không dùng “the”."],["She goes to the university by the bus.","She goes to university by bus.","Nơi chốn mang chức năng (university) và phương tiện (by bus) không có mạo từ."],["The poor needs more support.","The poor need more support.","“The + tính từ” chỉ nhóm người, nghĩa số nhiều nên động từ số nhiều."]],"quiz":[["___ is the longest river in Africa.",["Nile","The Nile","A Nile","Nile River the"],1,"Tên sông luôn dùng the: the Nile. Dấu hiệu là cụm so sánh nhất “the longest river” chỉ một con sông duy nhất.",{"Nile":"“Nile” không có mạo từ không hợp vì tên sông luôn đi với the trong câu này.","A Nile":"“A Nile” coi nó như một con sông bất kỳ, trong khi đây là con sông duy nhất, xác định.","Nile River the":"Trật tự từ sai; phải là “the Nile” hoặc “the River Nile”, không đảo the ra sau."}],["Doctors say that ___ often suffer from loneliness.",["the elderly","elderly","the elderlies","an elderly"],0,"“The + tính từ” chỉ cả nhóm người và đi với động từ số nhiều. Động từ “suffer” không có -s là gợi ý chủ ngữ số nhiều.",{"elderly":"“elderly” đứng một mình không làm chủ ngữ chỉ nhóm người; cần the đứng trước.","the elderlies":"Tính từ không thêm -s khi dùng như “the + tính từ”, nên “elderlies” sai.","an elderly":"“an elderly” chỉ một người, nhưng động từ “suffer” là số nhiều."}],["My sister has been in ___ since Monday because of appendicitis.",["the hospital","a hospital","hospital","hospitals"],2,"Khi nói ai đó là bệnh nhân nằm viện, ta dùng “in hospital” không mạo từ (Anh-Anh). Cụm “because of appendicitis” xác nhận đây là điều trị.",{"the hospital":"Thêm the gợi ý toà nhà cụ thể, trong khi ở đây cô ấy là bệnh nhân điều trị.","a hospital":"“a hospital” cho biết một bệnh viện bất kỳ, không hợp khi nói về việc nằm viện.","hospitals":"Dạng số nhiều không hợp vì chỉ có một người đang nằm viện, và cụm cố định không dùng số nhiều."}],["We usually travel to the coast ___ because it is cheaper than driving.",["by the train","with train","in a train","by train"],3,"Phương tiện nói chung dùng “by + danh từ” không mạo từ. Ý “cheaper than driving” cho thấy đang so sánh cách di chuyển.",{"by the train":"Sau “by” chỉ phương tiện nói chung thì không dùng the.","with train":"Giới từ “with” không dùng để chỉ phương tiện đi lại trong cụm cố định này.","in a train":"“in a train” chỉ vị trí ở trong một toa cụ thể, không diễn tả cách di chuyển nói chung."}]]},{"id":"comparison-advanced","lvl":"B2","title":"Advanced comparison","vi":"So sánh nâng cao","exams":["CEFR","VSTEP","IELTS"],"form":"The + so sánh hơn …, the + so sánh hơn …\nSo sánh hơn + and + so sánh hơn (more and more).\nmuch/far/slightly + so sánh hơn; twice as … as; by far the + so sánh nhất; not nearly as … as.","use":"Dùng để diễn tả sự thay đổi song song, thay đổi dần dần, mức chênh lệch lớn hay nhỏ, và các phép so sánh bội số. Rất hữu ích khi mô tả số liệu và xu hướng trong bài viết học thuật.","ex":[["The more patients we see, the more tired we become.","Chúng tôi khám càng nhiều bệnh nhân thì càng mệt."],["Online courses are becoming more and more popular.","Các khoá học trực tuyến ngày càng phổ biến."],["The new ward is considerably larger than the old one.","Khoa mới rộng hơn đáng kể so với khoa cũ."],["This laptop is by far the lightest in the shop.","Chiếc laptop này nhẹ nhất cửa hàng với khoảng cách rất xa."]],"err":[["The more you practise, you will speak better.","The more you practise, the better you will speak.","Hai vế “the more …, the …” phải đối xứng: vế sau cũng cần “the + so sánh hơn”."],["The bus is very faster than the train.","The bus is much faster than the train.","Không dùng “very” trước so sánh hơn; dùng much/far/a lot/considerably."],["Her flat is more expensive from mine.","Her flat is more expensive than mine.","So sánh hơn đi với “than”, không đi với “from”."]],"quiz":[["The ___ you practise speaking, the more fluent you will become.",["hardest","much","most","harder"],3,"Cấu trúc “the + so sánh hơn, the + so sánh hơn”; vế đầu cần trạng từ so sánh hơn “harder”, dấu hiệu là “the” và vế sau “the more fluent”.",{"hardest":"“hardest” là dạng so sánh nhất, không dùng trong cấu trúc “the … the …” vốn cần hai so sánh hơn.","much":"“much” không phải dạng so sánh hơn nên không mở được vế đầu của cấu trúc này.","most":"“most” là dạng so sánh nhất và không bổ nghĩa cho động từ practise theo cách tự nhiên ở đây."}],["Wages in the region are rising, and living costs are getting ___.",["high and high","more high","higher and higher","the higher"],2,"Thay đổi dần dần dùng “so sánh hơn + and + so sánh hơn”; tính từ ngắn high thành “higher and higher”, dấu hiệu là “are getting”.",{"high and high":"“high and high” không phải dạng so sánh hơn nên không diễn tả được sự tăng dần trong câu này.","more high":"“more high” sai vì tính từ ngắn high tạo so sánh hơn bằng -er, không dùng more.","the higher":"“the higher” cần có vế thứ hai kiểu “the … the …”, còn câu này mô tả thay đổi liên tục."}],["The new treatment is ___ more effective than the old one, according to the trial.",["very","far","most","so"],1,"Trước so sánh hơn dùng much/far/a great deal để nhấn mạnh; “far more effective than” khớp với “than the old one”.",{"very":"“very” không đứng trước so sánh hơn nên “very more effective” sai trong câu này.","most":"“most” là dạng so sánh nhất và không thể đi cùng “more … than” trong câu so sánh hai đối tượng.","so":"“so more effective than” không tạo thành cách nói đúng; “so” không bổ nghĩa cho so sánh hơn."}],["This flat is ___ as the one we saw yesterday, so it isn't worth the price.",["not nearly as spacious","not nearly more spacious","nearly not as spacious","not as nearly spacious"],0,"“Not nearly as + adj + as” nhấn mạnh sự kém xa; cụm cố định và cuối câu có “as the one we saw”.",{"not nearly more spacious":"“more spacious” bị kết hợp với “as … as” khiến cấu trúc sai, trong khi vế sau là “as the one”.","nearly not as spacious":"Trật tự “nearly not” không tự nhiên; “not nearly” mới là cụm đứng trước as.","not as nearly spacious":"“not as nearly” đảo vị trí của nearly nên không thành cấu trúc quen thuộc."}]]},{"id":"discourse-markers","lvl":"C1","title":"Discourse markers for speaking and writing","vi":"Từ nối diễn ngôn khi nói và viết","exams":["CEFR","IELTS","VSTEP"],"form":"Marker + , + mệnh đề. Ví dụ: Moreover, / On the other hand, / In other words, / All in all,\nMệnh đề 1. Marker, mệnh đề 2 (dấu chấm hoặc chấm phẩy trước marker, dấu phẩy sau marker).\nLời nói: actually, mind you, to be fair, anyway... đứng đầu hoặc cuối câu.","use":"Dùng để sắp xếp ý, báo hiệu quan hệ giữa các ý (thêm, đối lập, giải thích, kết luận) và thể hiện thái độ của người nói, khiến bài nói và bài viết mạch lạc, đúng văn phong.","ex":[["To begin with, we need to define what we mean by stress.","Trước hết, chúng ta cần định nghĩa xem stress nghĩa là gì."],["The drug is cheap. Moreover, it has very few side effects.","Loại thuốc này rẻ. Hơn nữa, nó có rất ít tác dụng phụ."],["The plan is risky; nevertheless, it may be worth trying.","Kế hoạch này nhiều rủi ro; tuy nhiên, có thể nó đáng thử."],["It wasn't a great film. Mind you, the acting was good.","Đó không phải bộ phim hay. Nhưng công bằng mà nói, diễn xuất khá tốt."]],"err":[["Moreover, the rent is high, but the flat is spacious.","The rent is high. On the other hand, the flat is spacious.","“Moreover” dùng để thêm ý cùng hướng; muốn nêu ý đối lập phải dùng “on the other hand” hoặc “however”, và không cần thêm “but”."],["The results were clear, in the contrary, the sample was small.","The results were clear; on the contrary, ... / The results were clear. However, the sample was small.","“On the contrary” (không phải “in the contrary”) phủ định ý trước; ở đây chỉ nêu thêm hạn chế nên dùng “however”."],["In conclusion of the essay, I think costs matter more.","To sum up, I think costs matter more.","Marker kết luận là “in conclusion”, “to sum up”, “all in all”; không có “in conclusion of”."]],"quiz":[["The tutor praised my argument. ___, she said the evidence was thin.",["Moreover","That said","In other words","All in all"],1,"“That said” báo hiệu sự nhượng bộ hoặc đối lập nhẹ; manh mối là lời khen ở câu trước và nhận xét tiêu cực ở câu sau.",{"Moreover":"“Moreover” thêm ý cùng hướng, trong khi lời nhận xét về bằng chứng yếu đi ngược lại lời khen.","In other words":"“In other words” diễn đạt lại ý trước, còn câu sau lại nêu một ý mới đối lập với lời khen.","All in all":"“All in all” dùng để kết luận cuối bài, không hợp khi mới chuyển sang một nhận xét trái chiều."}],["The flat is cheap and close to the station. ___, it has a small garden.",["Nevertheless","On the other hand","What is more","In other words"],2,"“What is more” thêm một ý mạnh cùng hướng; manh mối là hai ưu điểm đã nêu (cheap, close) và vườn nhỏ là ưu điểm thứ ba.",{"Nevertheless":"“Nevertheless” báo hiệu đối lập, nhưng khu vườn nhỏ là thêm một ưu điểm nữa chứ không trái ngược.","On the other hand":"“On the other hand” đưa ra mặt đối lập, trong khi câu này tiếp tục liệt kê ưu điểm của căn hộ.","In other words":"“In other words” chỉ dùng để nói lại ý trước; vườn là thông tin mới, không phải cách diễn đạt khác."}],["Our budget has been cut by half; ___, we can only run one clinic instead of two.",["in other words","on the other hand","mind you","to begin with"],0,"“In other words” nói lại ý vừa nêu cho rõ hơn; ở đây vế sau diễn giải cụ thể hậu quả của việc cắt ngân sách một nửa.",{"on the other hand":"“On the other hand” mở ra ý đối lập, còn vế sau chỉ là hệ quả cụ thể, diễn giải lại của việc cắt ngân sách.","mind you":"“Mind you” là lời nhượng bộ thân mật, không dùng để giải thích rõ hơn ý ở vế trước.","to begin with":"“To begin with” chỉ mở đầu một chuỗi ý, không có chức năng giải thích lại sau dấu chấm phẩy."}],["There are good arguments on both sides. ___, I think the benefits just outweigh the risks.",["By the way","Firstly","For example","On balance"],3,"“On balance” chốt kết luận sau khi cân nhắc hai phía; manh mối là “both sides” và động từ “outweigh”.",{"By the way":"“By the way” chuyển sang chuyện phụ, trong khi câu này đang đưa ra kết luận sau khi cân nhắc.","Firstly":"“Firstly” mở đầu danh sách các ý, không hợp với câu mang tính kết luận sau khi đã nêu hai phía.","For example":"“For example” đưa ví dụ minh hoạ, nhưng vế sau là phán đoán tổng hợp, không phải ví dụ."}]]},{"id":"ellipsis-substitution","lvl":"C1","title":"Ellipsis and substitution","vi":"Lược bỏ và thay thế từ","exams":["CEFR","VSTEP","IELTS"],"form":"Thay thế: one/ones, do so, so/not, do/does/did.\nLược bỏ: She cooked and (she) served. I'd love to (come).","use":"Dùng để tránh lặp từ đã rõ nghĩa, giúp câu gọn và tự nhiên hơn. Chỉ lược khi người nghe vẫn hiểu chắc chắn phần bị bỏ.","ex":[["The red folders are mine; the blue ones belong to Dr Hale.","Những tập hồ sơ đỏ là của tôi; những tập xanh thuộc về bác sĩ Hale."],["Will the results be ready by Friday? I hope so.","Kết quả có xong trước thứ Sáu không? Tôi hy vọng là có."],["Mira checked the samples and labelled them.","Mira kiểm tra các mẫu và dán nhãn chúng."],["Nobody asked him to attend, but he did.","Không ai yêu cầu anh ấy tham dự, nhưng anh ấy vẫn đến."]],"err":[["I need a pen, so can you lend me one pen?","I need a pen, so can you lend me one?","Dùng “one” thay cho danh từ đếm được số ít đã nhắc, không lặp lại danh từ."],["Will it rain? I hope not it.","Will it rain? I hope not.","“I hope not” là cụm cố định; không thêm đại từ phía sau."],["She said she would call, but she did not to.","She said she would call, but she did not.","Sau trợ động từ không dùng “to”; chỉ bỏ to khi rút gọn bằng “didn't”."]],"quiz":[["I lost my umbrella, so I bought a new ___ yesterday.",["it","ones","one","that"],2,"“one” thay cho danh từ đếm được số ít chưa xác định; dấu hiệu là “a new” và việc mua một chiếc mới thay chiếc đã mất.",{"it":"“it” chỉ chính chiếc ô đã mất, trong khi người nói mua một chiếc khác nên không hợp nghĩa.","ones":"“ones” là số nhiều, không khớp với mạo từ “a” đứng trước “new”.","that":"“that” không thay cho danh từ sau tính từ “new” theo cách tự nhiên trong câu này."}],["The older tablets work well, but the newer ___ keep crashing.",["one","ones","that","them"],1,"Danh từ bị lược là “tablets” số nhiều nên dùng “ones”; động từ “keep” và “the newer” là các dấu hiệu.",{"one":"“one” là số ít, không khớp với động từ số nhiều “keep” và danh từ “tablets”.","that":"“that” không đứng sau “the newer” để thay danh từ số nhiều đếm được.","them":"“them” là đại từ tân ngữ nên không thể làm chủ ngữ của “keep crashing”."}],["Will the funding be cut? I hope ___.",["not","no","it not","not so"],0,"Sau hope dùng “not” để thay cả mệnh đề phủ định; câu hỏi “Will … be cut?” cho thấy mệnh đề bị lược là “it won't be cut”.",{"no":"“I hope no” không tự nhiên vì “no” không thay được mệnh đề sau hope.","it not":"Thêm “it” trước “not” làm cụm cố định “I hope not” bị sai trật tự.","not so":"“not so” không phải cách rút gọn chuẩn; ta chỉ nói “I hope so” hoặc “I hope not”."}],["Are all the beds taken? I'm afraid ___.",["it so","that","so","yes"],2,"“I'm afraid so” là cụm cố định để xác nhận tin xấu; “so” thay cho mệnh đề “all the beds are taken”.",{"it so":"“it so” thêm đại từ thừa, vì “so” đã thay thế cả mệnh đề rồi.","that":"“that” không đứng sau “I'm afraid” theo kiểu rút gọn trả lời như vậy.","yes":"“yes” không kết hợp trực tiếp sau “I'm afraid” để tạo câu trả lời tự nhiên."}]]},{"id":"hedging-modality","lvl":"C1","title":"Hedging and tentative language","vi":"Ngôn ngữ rào đón và nói giảm","exams":["CEFR","IELTS","VSTEP"],"form":"S + seem/appear/tend/be likely + to V. Dạng: It would seem/appear that + mệnh đề.\nmay well / could possibly + V. Trạng từ rào: generally, mainly, to some extent, by and large.\nĐộng từ thận trọng: suggest/indicate/imply (không dùng prove khi chưa chắc).","use":"Dùng khi muốn nói thận trọng, lịch sự hoặc tránh khẳng định tuyệt đối, nhất là trong bài viết học thuật, báo cáo y tế và những lời đề nghị tế nhị trong giao tiếp.","ex":[["The results seem to support the original hypothesis.","Kết quả dường như ủng hộ giả thuyết ban đầu."],["It would appear that the new drug reduces recovery time.","Có vẻ như loại thuốc mới rút ngắn thời gian hồi phục."],["Younger patients tend to respond more quickly to treatment.","Bệnh nhân trẻ tuổi thường có xu hướng đáp ứng điều trị nhanh hơn."],["I was wondering if you could possibly look at my draft.","Tôi đang tự hỏi liệu bạn có thể xem giúp bản nháp của tôi không."]],"err":[["The data prove that the policy failed.","The data suggest that the policy may have failed.","Khi bằng chứng chưa đủ chắc, dùng “suggest/indicate” và “may” thay vì “prove”, vì “prove” là khẳng định tuyệt đối."],["It seems that the treatment to work well.","It seems that the treatment works well. / The treatment seems to work well.","Sau “seem” dùng “that + mệnh đề” hoặc “to V”; không trộn hai cấu trúc."],["Students are tend to forget new words.","Students tend to forget new words.","“Tend” là động từ thường, không đi với “be”; cấu trúc là tend + to V."]],"quiz":[["The early results ___ to support our theory.",["seem","seems","are seem","seem that"],0,"“Seem + to V” là cấu trúc rào đón và chia theo chủ ngữ. Chủ ngữ “the early results” số nhiều nên dùng “seem”.",{"seems":"“Results” là danh từ số nhiều nên động từ phải là “seem”, không thêm -s.","are seem":"“Seem” là động từ thường, không đi sau “are”; không có dạng bị động hay ghép be.","seem that":"“Seem that” cần một mệnh đề theo sau, còn ở đây phía sau là “to support” nên phải dùng “seem to V”."}],["Patients with this condition ___ to recover more slowly in winter.",["tends","tend","are tend","tending"],1,"“Tend to V” diễn tả xu hướng chung, không phải quy luật tuyệt đối. Chủ ngữ “patients” số nhiều nên giữ nguyên “tend”.",{"tends":"Chủ ngữ “patients” số nhiều, nên “tends” có -s là sai hòa hợp.","are tend":"“Tend” là động từ thường, không đi cùng “be”; người học hay nhầm theo “be likely”.","tending":"Dạng V-ing đứng một mình không làm động từ chính của câu ở đây."}],["___ that the new timetable has reduced waiting times.",["It would seem to","There would seem","It would seem","They would seem"],2,"“It would seem that + mệnh đề” là cách nói giảm trang trọng. Dấu hiệu là “that the new timetable has…” theo sau chủ ngữ giả “it”.",{"It would seem to":"Sau “It would seem” là mệnh đề với that, không nối “to” vì không có động từ nguyên mẫu nào theo sau.","There would seem":"“There would seem” cần danh từ hoặc “to be” sau đó, không đi với mệnh đề “that…” trong câu này.","They would seem":"“They” không có nghĩa gì rõ ràng ở đây; cấu trúc rào đón dùng chủ ngữ giả “it”."}],["The drug may ___ reduce the risk, although more trials are needed.",["very","much","quite","well"],3,"“May well + V” nghĩa là rất có thể, vẫn là cách rào đón. Vế sau “more trials are needed” cho thấy chưa chắc chắn hoàn toàn.",{"very":"“May very reduce” sai vì “very” không đứng giữa trợ động từ và động từ để tăng khả năng.","much":"“May much reduce” không tồn tại; “much” cần đi với so sánh hoặc “very much” trước động từ.","quite":"“May quite reduce” không tự nhiên; “quite” không kết hợp với “may” để tăng khả năng."}]]},{"id":"nominalisation","lvl":"C1","title":"Nominalisation and formal written style","vi":"Danh từ hoá và văn phong viết trang trọng","exams":["CEFR","IELTS","VSTEP"],"form":"V/Adj → Noun: decide → decision, fail → failure, different → difference.\nMệnh đề → cụm danh từ: Because prices rose → The rise in prices.\nMẫu hay gặp: the + noun + of, a growing number of, a lack of.","use":"Dùng để viết trang trọng, súc tích trong bài học thuật, báo cáo và văn bản y tế, khi muốn nén cả mệnh đề thành một cụm danh từ. Tránh lạm dụng khi câu trở nên nặng và khó hiểu.","ex":[["The decision to close the clinic surprised many residents.","Quyết định đóng cửa phòng khám khiến nhiều cư dân bất ngờ."],["The rise in prices led to a fall in demand.","Việc giá tăng dẫn đến nhu cầu giảm."],["A growing number of students struggle with anxiety.","Ngày càng nhiều sinh viên gặp khó khăn với chứng lo âu."],["Lack of sleep can reduce concentration.","Thiếu ngủ có thể làm giảm khả năng tập trung."]],"err":[["The fail of the experiment surprised us.","The failure of the experiment surprised us.","“Fail” là động từ; danh từ là “failure”. Sau “the” cần danh từ."],["The increase of the unemployment worried the government.","The increase in unemployment worried the government.","Với số liệu tăng giảm, dùng “increase/rise/fall in”, và “unemployment” không đi với “the” khi nói chung."],["There was a lack of the evidence.","There was a lack of evidence.","Sau “a lack of” là danh từ không đếm được nói chung, không dùng “the”."]],"quiz":[["The ___ to close the ward was taken after months of discussion.",["decision","decide","decisive","deciding"],0,"Sau mạo từ “The” và trước “to close” cần danh từ; danh từ của “decide” là “decision”, và “was taken” đi với “decision”.",{"decide":"“Decide” là động từ, mà sau “The” cần một danh từ làm chủ ngữ.","decisive":"“Decisive” là tính từ nghĩa là quyết đoán, không đứng một mình sau “the” trước “to close”.","deciding":"Dạng -ing có thể làm danh động từ nhưng không đi với “the ... to close the ward” trong câu này."}],["Doctors were concerned about the ___ of antibiotics in farming.",["overusing","overuse","overused","overuses"],1,"Sau “the” và trước “of antibiotics” cần danh từ; “overuse” vừa là danh từ không đếm được, vừa hợp với giới từ “of”.",{"overusing":"Dạng động từ -ing không hợp sau “the ... of” khi cần danh từ chỉ hiện tượng.","overused":"Dạng quá khứ phân từ là tính từ, không làm danh từ sau “the”.","overuses":"Dạng ngôi thứ ba của động từ, không đứng sau “the” làm danh từ ở đây."}],["There has been a sharp ___ in the number of road accidents.",["declining","declined","decline","decrease of"],2,"Sau “a sharp” cần danh từ đếm được số ít; “a decline in the number of” là mẫu chuẩn chỉ sự giảm.",{"declining":"Dạng -ing là tính từ hay phân từ, không đi với “a sharp ... in the number” như danh từ.","declined":"Đây là động từ quá khứ; sau “a sharp” cần danh từ đếm được.","decrease of":"Thừa giới từ “of” và sai giới từ vì mẫu chuẩn là “a decline in”, nên không ghép được với “in” phía sau."}],["The company's ___ to deliver on time cost it several contracts.",["fail","failed","failing to","failure"],3,"Sau sở hữu cách “company's” cần danh từ; “failure to + V” là mẫu cố định, và “failure” là danh từ của “fail”.",{"fail":"“Fail” là động từ nguyên mẫu, không đứng sau sở hữu cách làm chủ ngữ.","failed":"Dạng quá khứ của động từ, không làm danh từ sau “company's”.","failing to":"Thừa “to” và cấu trúc bị trùng với “to deliver” đứng sau nó."}]]},{"id":"past-perfect-continuous","lvl":"B2","title":"Past perfect continuous and narrative tenses","vi":"Quá khứ hoàn thành tiếp diễn và các thì kể chuyện","exams":["CEFR","VSTEP","IELTS"],"form":"S + had been + V-ing. Phủ định: hadn't been + V-ing. Nghi vấn: Had + S + been + V-ing?\nHow long had + S + been + V-ing …? for/since + mốc trước thời điểm quá khứ.","use":"Dùng để nói một hành động đã diễn ra liên tục trước một thời điểm trong quá khứ, hoặc là nguyên nhân của một tình huống lúc đó. Khi kể chuyện, kết hợp với quá khứ đơn và quá khứ tiếp diễn để sắp xếp trình tự sự kiện.","ex":[["She had been revising for hours when the power went out.","Cô ấy đã ôn bài liền mấy tiếng thì mất điện."],["His eyes were red because he had been working on the report all night.","Mắt anh ấy đỏ vì anh đã làm báo cáo suốt đêm."],["How long had they been waiting before the doctor arrived?","Họ đã chờ bao lâu trước khi bác sĩ đến?"],["I had been living in Hue for six years before I moved to Hanoi.","Tôi đã sống ở Huế sáu năm trước khi chuyển ra Hà Nội."]],"err":[["She was tired because she has been studying all day.","She was tired because she had been studying all day.","Câu kể ở quá khứ nên nguyên nhân phải lùi về “had been studying”, không dùng “has been”."],["I had been knowing him for ten years when he moved away.","I had known him for ten years when he moved away.","“know” là động từ chỉ trạng thái, không dùng ở dạng tiếp diễn; dùng “had known”."],["They had been building the bridge since three years.","They had been building the bridge for three years.","“for” đi với khoảng thời gian (three years); “since” đi với mốc thời gian."]],"quiz":[["When I met Lan, she was exhausted because she ___ for twelve hours.",["had been working","has been working","worked","is working"],0,"Quá trình kéo dài (for twelve hours) là nguyên nhân của trạng thái ở một mốc quá khứ nên dùng had been working.",{"has been working":"Mốc “when I met Lan” nằm trong quá khứ nên không thể dùng thì hiện tại hoàn thành tiếp diễn.","worked":"Quá khứ đơn không nối được quá trình kéo dài với trạng thái kiệt sức lúc gặp; thiếu quan hệ nguyên nhân.","is working":"Thì hiện tại không hợp với cả câu kể ở quá khứ (was exhausted, met)."}],["By the time the ambulance arrived, the patient ___ on the floor for nearly an hour.",["has been lying","had been lying","lay","was lying"],1,"By the time + quá khứ đơn cùng for + khoảng thời gian báo hiệu quá trình kéo dài trước mốc đó: had been lying.",{"has been lying":"“By the time … arrived” là mốc quá khứ nên hiện tại hoàn thành tiếp diễn không phù hợp.","lay":"Quá khứ đơn không đi với “for nearly an hour” để chỉ quá trình kéo dài trước một mốc khác.","was lying":"Quá khứ tiếp diễn không dùng với “for nearly an hour” khi nhấn khoảng thời gian trước mốc kia."}],["How long ___ before the lecture began?",["have the students been waiting","were the students waiting","had the students been waiting","are the students waiting"],2,"How long + had + S + been + V-ing hỏi thời lượng diễn ra trước một mốc quá khứ, ở đây là lúc bài giảng bắt đầu.",{"have the students been waiting":"Mốc “the lecture began” ở quá khứ nên không dùng have been waiting.","were the students waiting":"Quá khứ tiếp diễn không hỏi được khoảng thời gian chờ tính đến trước mốc quá khứ.","are the students waiting":"Thì hiện tại mâu thuẫn với “began” ở quá khứ trong cùng câu."}],["He ___ in the lab since eight o'clock when the fire alarm sounded.",["has worked","was working","worked","had been working"],3,"Since + mốc và when + quá khứ đơn cần had been working để nói về quá trình kéo dài trước lúc chuông reo.",{"has worked":"Hiện tại hoàn thành không hợp với mốc quá khứ “sounded” trong mệnh đề when.","was working":"Quá khứ tiếp diễn không đi với “since eight o'clock”; since cần thì hoàn thành.","worked":"Quá khứ đơn không diễn đạt quá trình kéo dài từ mốc “since eight” đến lúc báo động."}]]},{"id":"reporting-verbs","lvl":"B2","title":"Reporting verbs and their patterns","vi":"Động từ tường thuật và cấu trúc đi kèm","exams":["CEFR","VSTEP","IELTS"],"form":"admit/deny/suggest + V-ing hoặc that-clause; promise/offer/refuse + to V\nadvise/warn/remind + O + to V; accuse/blame/congratulate + O + giới từ + V-ing","use":"Dùng để thuật lại lời người khác một cách chính xác hơn “say”: mỗi động từ mang sắc thái riêng (thừa nhận, đề nghị, cảnh báo, buộc tội) và đòi hỏi một cấu trúc ngữ pháp cố định.","ex":[["She admitted taking the files home without permission.","Cô ấy thừa nhận đã mang tài liệu về nhà mà không được phép."],["The nurse advised him to rest for a week.","Y tá khuyên anh ấy nghỉ ngơi một tuần."],["They accused the manager of ignoring the safety rules.","Họ buộc tội người quản lý đã phớt lờ các quy tắc an toàn."],["He explained that the machine needed servicing.","Anh ấy giải thích rằng chiếc máy cần được bảo dưỡng."]],"err":[["She suggested me to take a break.","She suggested (that) I take a break. / She suggested taking a break.","“suggest” không đi với “O + to V”. Dùng “suggest + V-ing” hoặc “suggest (that) + mệnh đề”."],["He told that the lab was closed.","He said that the lab was closed. / He told us that the lab was closed.","“tell” luôn cần người nghe ngay sau nó; không có người nghe thì dùng “say”."],["They apologised me for the delay.","They apologised to me for the delay.","“apologise” đi với “to + người” và “for + lý do”, không có tân ngữ trực tiếp."]],"quiz":[["The surgeon denied ___ the wrong form to the patient.",["giving","to give","give","that give"],0,"“deny” đi với V-ing để phủ nhận một việc đã làm; dấu hiệu là hành động “giving the wrong form” đã xảy ra trong quá khứ.",{"to give":"“deny” không đi với to V; nó đi với V-ing khi nói về việc đã xảy ra như ở câu này.","give":"Sau “deny” cần dạng V-ing hoặc mệnh đề that, không dùng động từ nguyên mẫu trần.","that give":"“that” phải có một mệnh đề đầy đủ có chủ ngữ, còn “give” chỉ là động từ đơn lẻ."}],["The tenant refused ___ the rent until the heating was repaired.",["paying","to pay","to paying","that pay"],1,"“refuse + to V” diễn tả sự từ chối làm điều gì; trong câu, người thuê nhà từ chối trả tiền thuê nên cần “to pay”.",{"paying":"“refuse” thuộc nhóm đi với to V, nên V-ing ở đây làm sai cấu trúc của động từ.","to paying":"Sau “to” trong cấu trúc này phải là động từ nguyên mẫu, không phải dạng V-ing.","that pay":"“refuse that” không tự nhiên khi có cùng chủ ngữ; câu cần một động từ nguyên mẫu có to."}],["The coach advised the players ___ too much before the final.",["not eating","don't eat","not to eat","to not eating"],2,"“advise + O + (not) to V”; tân ngữ “the players” đã có sẵn nên chỗ trống phải là “not to eat”.",{"not eating":"“advise” cần tân ngữ rồi đến to V; dạng V-ing phủ định không đi với “the players” ở đây.","don't eat":"Câu tường thuật không giữ nguyên dạng mệnh lệnh phủ định “don't”; phải dùng “not to V”.","to not eating":"Sau “to” phải là động từ nguyên mẫu, và “eating” làm cấu trúc bị sai hoàn toàn."}],["Her colleagues congratulated her ___ the research grant.",["for winning","of winning","to win","on winning"],3,"Mẫu cố định là “congratulate O on + V-ing”; sau “her” cần giới từ “on” chứ không phải for hay of.",{"for winning":"“congratulate” đi với giới từ “on”, không dùng “for” để chúc mừng ai về điều gì.","of winning":"“of” dùng với accuse, không dùng với congratulate; câu này cần giới từ khác.","to win":"Sau “congratulate O” cần giới từ cộng V-ing, không dùng trực tiếp to V."}]]}];
  const BANK = {"adjective-gradability":"c|After the double shift, the nurses were ___ exhausted.|very / fairly / absolutely / rather|2|“Exhausted” là tính từ ungradable (đã mang nghĩa cực mệt) nên đi với “absolutely”; cụm “double shift” cho thấy mức kiệt sức tuyệt đối.|very=>“Very” dùng cho tính từ gradable như “tired”, không đi với “exhausted” vốn đã ở mức cực đại.;;fairly=>“Fairly” chỉ mức vừa phải, mâu thuẫn với nghĩa kiệt sức hoàn toàn của “exhausted”.;;rather=>“Rather” là từ chỉ mức khá cho tính từ gradable, không hợp với “exhausted”.\nc|I'd say the exam was ___ difficult, but not impossible.|absolutely / completely / totally / fairly|3|“Difficult” là tính từ gradable nên dùng “fairly”; vế sau “but not impossible” cho thấy mức độ chưa tuyệt đối.|absolutely=>“Absolutely” chỉ đi với tính từ ungradable, còn “difficult” có thể mạnh yếu khác nhau.;;completely=>“Completely” mang nghĩa hoàn toàn nên không hợp với tính từ gradable “difficult” trong câu này.;;totally=>“Totally” là từ nhấn mạnh cho tính từ ungradable, không đứng trước “difficult”.\nc|It was ___ impossible to park near the hospital on Monday.|very / extremely / fairly / completely|3|“Impossible” là tính từ ungradable nên cần “completely”; “very”, “extremely” và “fairly” dành cho tính từ gradable.|very=>“Very” không đi với “impossible” vì việc đã là không thể thì không có mức độ.;;extremely=>“Extremely” là từ nhấn mạnh cho tính từ gradable, không hợp với “impossible”.;;fairly=>“Fairly” chỉ mức vừa phải, không thể nói việc gì đó “khá không thể”.\nc|She was carrying a ___ bag.|leather brown small / small brown leather / brown small leather / leather small brown|1|Thứ tự là kích cỡ, màu sắc, chất liệu rồi mới đến danh từ: small (size) – brown (colour) – leather (material).|leather brown small=>Chất liệu “leather” phải đứng gần danh từ nhất, không được đứng đầu chuỗi tính từ.;;brown small leather=>Kích cỡ “small” phải đứng trước màu “brown”, nên “brown small” sai thứ tự.;;leather small brown=>Chất liệu “leather” đứng đầu là sai, và kích cỡ cũng phải đứng trước màu.\nc|They live in a ___ house near the river.|lovely old stone / old lovely stone / stone old lovely / lovely stone old|0|Ý kiến (lovely) đứng trước tuổi (old), rồi đến chất liệu (stone) sát danh từ; thứ tự đúng là opinion – age – material.|old lovely stone=>Tính từ ý kiến “lovely” phải đứng trước tính từ tuổi “old”, không đảo lại.;;stone old lovely=>Chất liệu “stone” phải đứng gần danh từ nhất, không đứng đầu chuỗi.;;lovely stone old=>Tuổi “old” phải đứng trước chất liệu “stone”, nên “stone old” sai.\nc|The patients were ___ by the long delay at reception.|annoying / annoyed / annoy / to annoy|1|Người cảm thấy bực dùng tính từ -ed; chủ ngữ “the patients” là người chịu cảm giác và có “by the long delay” chỉ nguyên nhân.|annoying=>“Annoying” mô tả thứ gây khó chịu, mà bệnh nhân là người bị bực nên không dùng.;;annoy=>Dạng nguyên mẫu “annoy” là động từ, không thể đứng sau “were” làm tính từ.;;to annoy=>“To annoy” là động từ nguyên mẫu, không đứng sau “were … by” trong câu bị động này.\nc|The new schedule is quite ___; nobody understands it.|confusion / confused / confuse / confusing|3|Chủ ngữ là vật gây ra sự bối rối (“schedule”) nên dùng -ing; “nobody understands it” cho thấy lịch trình là nguyên nhân.|confusion=>“Confusion” là danh từ, không đứng sau “quite” để bổ nghĩa cho chủ ngữ là vật.;;confused=>“Confused” tả người cảm thấy bối rối, còn “schedule” là thứ gây ra sự bối rối.;;confuse=>“Confuse” là động từ nguyên mẫu, không thể làm vị ngữ tính từ sau “is quite”.\nc|The results were ___ perfect, so we did not repeat the test.|quite / a bit / fairly / rather|0|Với tính từ ungradable như “perfect”, “quite” nghĩa là hoàn toàn; vế sau cho thấy kết quả không cần làm lại.|a bit=>“A bit” chỉ mức nhẹ và không đi với tính từ ungradable như “perfect”.;;fairly=>“Fairly” nghĩa là khá và không kết hợp được với “perfect”, vì hoàn hảo không có mức độ.;;rather=>“Rather” chỉ mức khá, không hợp với “perfect” vốn đã tuyệt đối.\nx|Chọn câu đúng về nước hồ|The water in the lake was absolutely cold. / The water in the lake was very freezing. / The water in the lake was absolutely freezing. / The water in the lake was fairly freezing.|2|“Freezing” là tính từ ungradable nên đi với “absolutely”; “cold” là gradable và phải đi với “very”.|The water in the lake was absolutely cold.=>“Absolutely” không đi với “cold” vì “cold” là tính từ gradable có nhiều mức độ.;;The water in the lake was very freezing.=>“Very” không đi với “freezing” vì từ này đã mang nghĩa lạnh cực độ.;;The water in the lake was fairly freezing.=>“Fairly” chỉ mức vừa phải nên mâu thuẫn với nghĩa cực lạnh của “freezing”.\nx|Chọn câu đúng về chiếc đồng hồ|He bought a silver small Japanese watch. / He bought a Japanese small silver watch. / He bought a small Japanese silver watch. / He bought a small silver Japanese watch.|3|Thứ tự đúng là kích cỡ, màu, xuất xứ rồi danh từ: small (size) – silver (colour) – Japanese (origin).|He bought a silver small Japanese watch.=>Kích cỡ “small” phải đứng trước màu “silver”, không đảo ngược.;;He bought a Japanese small silver watch.=>Xuất xứ “Japanese” phải đứng sau kích cỡ và màu, không đứng đầu chuỗi.;;He bought a small Japanese silver watch.=>Màu “silver” phải đứng trước xuất xứ “Japanese”, nên “Japanese silver” sai thứ tự.\nt|The task was ___ impossible without a map. (absolutely / very)|absolutely;completely;totally|“Impossible” là tính từ ungradable nên dùng “absolutely”, không dùng “very”.\nt|I was really ___ (bore) by the repetitive training video.|bored|Người cảm thấy chán dùng tính từ -ed: “bored”.\nf|She was very exhausted after the marathon.|very|completely|“Exhausted” là tính từ ungradable nên dùng “completely” hoặc “absolutely”, không dùng “very”.\nc|The first question was ___ easy, but the second one was impossible.|absolutely / completely / totally / pretty|3|“Easy” là tính từ gradable; trong các lựa chọn chỉ “pretty” đi được với tính từ gradable, còn ba từ kia dành cho ungradable.|absolutely=>“Absolutely” không đi với “easy” vì dễ hay khó đều có nhiều mức độ.;;completely=>“Completely” dùng cho tính từ ungradable, không hợp với “easy” trong câu này.;;totally=>“Totally” là từ nhấn mạnh cho tính từ ungradable nên không đứng trước “easy”.\nc|The ending of the novel was ___ surprising; nobody had guessed it.|absolutely / extremely / completely / totally|1|“Surprising” là tính từ gradable nên đi với “extremely”; “absolutely”, “completely”, “totally” chỉ đi với tính từ ungradable.|absolutely=>“Absolutely” không kết hợp được với “surprising” vì tính từ này có thể mạnh hay yếu.;;completely=>“Completely” đòi hỏi tính từ ungradable, nhưng “surprising” là gradable.;;totally=>“Totally” chỉ hợp với tính từ ungradable nên không đứng trước “surprising”.\nc|The coffee is ___ good, but I have had better.|absolutely / completely / totally / quite|3|“Good” là tính từ gradable nên “quite” nghĩa là khá; vế “I have had better” xác nhận mức độ chỉ vừa phải.|absolutely=>“Absolutely” chỉ đi với tính từ ungradable, còn “good” là gradable.;;completely=>“Completely good” không tự nhiên và mâu thuẫn với vế sau cho rằng từng uống ngon hơn.;;totally=>“Totally” nhấn mạnh tuyệt đối, trái với ý “I have had better” ở vế sau.\nc|He packed his things into a ___ bag.|blue big canvas travel / big canvas blue travel / big blue canvas travel / travel big blue canvas|2|Thứ tự đúng là kích cỡ, màu, chất liệu, mục đích rồi danh từ: big – blue – canvas – travel bag.|blue big canvas travel=>Kích cỡ “big” phải đứng trước màu “blue” nên “blue big” sai thứ tự.;;big canvas blue travel=>Màu “blue” phải đứng trước chất liệu “canvas”, không đứng sau.;;travel big blue canvas=>Từ chỉ mục đích “travel” phải đứng sát danh từ, không đứng đầu chuỗi.\nc|She wore a ___ pendant.|round small gold / gold small round / small gold round / small round gold|3|Thứ tự đúng là kích cỡ, hình dạng, rồi màu hoặc chất liệu: small – round – gold.|round small gold=>Kích cỡ “small” phải đứng trước hình dạng “round”, nên “round small” sai thứ tự.;;gold small round=>“Gold” phải đứng gần danh từ nhất, không đứng đầu chuỗi tính từ.;;small gold round=>Hình dạng “round” phải đứng trước “gold”, không đứng sau cùng.\nc|I'm not ___ in politics, but my brother follows it closely.|interested / interesting / interest / interestedly|0|Người cảm thấy hứng thú dùng tính từ -ed; “I'm not … in politics” nói về cảm giác của người nói và đi với giới từ “in”.|interesting=>“Interesting” mô tả thứ gây hứng thú, còn người nói là người cảm thấy nên không dùng.;;interest=>“Interest” là danh từ hoặc động từ, không đứng sau “I'm not” làm tính từ.;;interestedly=>“Interestedly” là trạng từ, không đứng sau “be” và trước “in politics” trong cấu trúc này.\nx|Chọn câu đúng về kỳ thi|The exam was absolutely easy, and the result was extremely perfect. / The exam was extremely easy, and the result was absolutely perfect. / The exam was extremely easy, and the result was very perfect. / The exam was absolutely easy, and the result was very perfect.|1|“Easy” là gradable nên đi với “extremely”, còn “perfect” là ungradable nên đi với “absolutely”.|The exam was absolutely easy, and the result was extremely perfect.=>“Absolutely easy” sai vì “easy” là gradable, và “extremely perfect” sai vì “perfect” là ungradable.;;The exam was extremely easy, and the result was very perfect.=>“Very perfect” sai vì “perfect” đã tuyệt đối nên không thể mạnh yếu.;;The exam was absolutely easy, and the result was very perfect.=>Cả “absolutely easy” và “very perfect” đều ghép sai loại tính từ với từ nhấn mạnh.\nt|The weather was ___ cold, but it was not yet freezing. (very)|very;fairly;rather;quite;extremely;really;pretty;so|“Cold” là tính từ gradable nên đi với “very”; “freezing” mới là mức cực lạnh.\nt|The lecture was so ___ (tire) that I nearly fell asleep.|tiring|Vật gây ra cảm giác mệt dùng tính từ -ing: “tiring”.\nt|The news about the hospital closure was ___ (shock).|shocking|Tin tức là thứ gây ra cú sốc nên dùng tính từ -ing: “shocking”.\nf|The hotel room was absolutely small, so we asked for another one.|absolutely|very|“Small” là tính từ gradable nên đi với “very”, còn “absolutely” chỉ đi với tính từ ungradable.\nf|The students were boring because the lesson was far too long.|boring|bored|Học sinh là người cảm thấy chán nên dùng tính từ -ed “bored”.\no|She wore a lovely long black silk dress.|Thứ tự tính từ: ý kiến, kích cỡ, màu, chất liệu rồi đến danh từ.","adverbial-clauses":"c|The ward keeps a night light on ___ patients can find the bathroom safely.|so that / so as to / in order to / lest|0|Hai vế có chủ ngữ khác nhau (ward/patients) và có “can”, nên cần “so that” để nêu mục đích bằng một mệnh đề đầy đủ.|so as to=>“So as to” cần động từ nguyên mẫu ngay sau, trong khi ở đây có chủ ngữ riêng “patients” và động từ “can find”.;;in order to=>“In order to” chỉ đi với V nguyên mẫu, không đứng trước mệnh đề có chủ ngữ “patients”.;;lest=>“Lest” diễn tả điều muốn tránh; ở đây mục đích là điều tích cực nên không hợp nghĩa.\nc|She repeated the instructions slowly so as ___ confuse the new volunteers.|to not / not to / not / that not|1|Cùng chủ ngữ (she) nên dùng “so as not to + V” để nêu mục đích phủ định; “not” phải đứng trước “to”.|to not=>Dạng “so as to not” bị coi là kém chuẩn trong văn viết trang trọng; phủ định phải đặt “not” trước “to”.;;not=>Thiếu “to”: sau “so as not” bắt buộc có “to” + V nguyên mẫu.;;that not=>Không có cấu trúc “so as that not”; “so that” mới đi với mệnh đề.\nc|The report was ___ badly written that the committee asked for a full revision.|such / very / so / too|2|“So + trạng từ/tính từ + that” chỉ mức độ dẫn đến kết quả; “badly” là trạng từ và vế sau “that the committee asked …” là kết quả.|such=>“Such” đi với danh từ; ở đây “badly” là trạng từ nên không dùng “such”.;;very=>“Very” không dẫn vào mệnh đề kết quả “that …”, nên câu thiếu liên kết nghĩa.;;too=>“Too” cần “to + V”, không tạo mệnh đề kết quả với “that” ở đây.\nc|It was ___ a persuasive argument that even the critics were won over.|so / too / very / such|3|Sau chỗ trống là “a persuasive argument” (a + adj + N), nên dùng “such a … that” để nêu kết quả.|so=>“So” không đứng trực tiếp trước “a + tính từ + danh từ”; phải đổi thành “so persuasive an argument”.;;too=>“Too” không dùng với “that” để nêu kết quả và không hợp trước “a persuasive argument”.;;very=>“Very” không thể đứng trước “a”; ngoài ra nó không dẫn vào mệnh đề kết quả.\nc|___ that the vaccine is already approved, the clinic can begin booking appointments.|Given / Although / Lest / Whereas|0|Việc vaccine đã được duyệt là lý do hiển nhiên dẫn tới hành động ở vế sau, nên dùng “Given that”.|Although=>“Although” nhượng bộ, nhưng ở đây việc vaccine được duyệt là lý do chứ không đối lập với việc đặt lịch.;;Lest=>“Lest” chỉ điều đáng sợ cần tránh, không dùng để nêu lý do đã biết.;;Whereas=>“Whereas” đối lập hai sự việc; câu này không có sự tương phản nào.\nc|Some students prefer lectures, ___ others learn better through group projects.|lest / whereas / seeing that / so that|1|Hai nhóm sinh viên được đối lập (some … others), nên dùng “whereas” để nêu sự tương phản.|lest=>“Lest” nghĩa là vì sợ rằng, không nối hai nhóm sinh viên có sở thích khác nhau.;;seeing that=>“Seeing that” nêu lý do; hai vế ở đây chỉ đối lập chứ không có quan hệ nhân quả.;;so that=>“So that” nêu mục đích, không hợp khi so sánh sở thích của hai nhóm.\nc|The proposal, ___ somewhat vague, received strong support from the board.|whereas / lest / albeit / so that|2|“Albeit” (dù là) đứng trước tính từ hoặc cụm từ ngắn, không cần chủ ngữ hay động từ, nên hợp với “somewhat vague”.|whereas=>“Whereas” cần một mệnh đề đầy đủ có chủ ngữ và động từ, mà ở đây chỉ có tính từ “somewhat vague”.;;lest=>“Lest” cần mệnh đề với should hoặc động từ nguyên mẫu, không đi trước tính từ.;;so that=>“So that” nêu mục đích và cần mệnh đề đầy đủ, không đi trước một tính từ.\nc|___ I respect her experience, I think the new protocol is safer.|So as / Lest / Seeing as / Much as|3|“Much as” nghĩa là “dù rất”, dùng để nhượng bộ trước khi nêu quan điểm trái ngược ở vế sau.|So as=>“So as” đi với “to” để nêu mục đích, không mang nghĩa nhượng bộ ở đây.;;Lest=>“Lest” nêu điều muốn tránh, không dẫn vào ý nhượng bộ như “dù rất tôn trọng”.;;Seeing as=>“Seeing as” nêu lý do, nhưng câu này nói ngược: tôn trọng nhưng vẫn không đồng ý.\nc|___ difficult the exam may seem, you can pass it with careful preparation.|However / Whatever / Whoever / Whereas|0|Cấu trúc “however + adj + S + V” nghĩa là “dù … đến đâu”; sau chỗ trống là tính từ “difficult”.|Whatever=>“Whatever” đi với danh từ hoặc động từ, không đứng trực tiếp trước tính từ “difficult”.;;Whoever=>“Whoever” chỉ người, không hợp để nhượng bộ về mức độ khó của kỳ thi.;;Whereas=>“Whereas” đối lập hai sự việc và không đi trước cấu trúc tính từ + chủ ngữ.\nc|The nurses worked quickly ___ the equipment would be ready for the morning round.|lest / so that / whereas / albeit|1|Làm nhanh để thiết bị sẵn sàng là mục đích với chủ ngữ mới (the equipment), nên cần “so that” + would.|lest=>“Lest” cần mệnh đề phủ định về nghĩa (sợ rằng), trong khi câu này nêu mục đích tích cực.;;whereas=>“Whereas” chỉ sự đối lập, không có sự tương phản trong câu.;;albeit=>“Albeit” không đứng trước một mệnh đề đầy đủ có “would be ready”.\nc|Hospitals were told to prepare for the surge ___ they be caught unready.|so that / whereas / lest / as long as|2|“Lest + S + (should) + V” nghĩa là “kẻo/vì sợ rằng”; dạng nguyên mẫu “be” sau chủ ngữ “they” cho thấy cấu trúc này.|so that=>“So that” đòi hỏi nghĩa tích cực; ở đây “be caught unready” là điều cần tránh nên ghép sẽ ngược nghĩa.;;whereas=>“Whereas” chỉ sự tương phản và không đi với dạng động từ nguyên mẫu “be”.;;as long as=>“As long as” nêu điều kiện, không phù hợp để diễn tả sự lo ngại tránh một điều xấu.\nc|Prices rose to such an extent ___ many families could no longer afford basic food.|which / as / what / that|3|“To such an extent that” nêu kết quả của mức độ; vế sau là kết quả (gia đình không đủ tiền mua thức ăn).|which=>“Which” không dẫn mệnh đề kết quả sau “to such an extent”; cụm này cần “that”.;;as=>“As” dùng trong “such … as” nghĩa khác (kiểu như), không nêu kết quả.;;what=>“What” không đóng vai liên từ kết quả sau “such an extent”.\nx|Chọn câu đúng về kết quả|The lecture was so dull that half the audience fell asleep. / The lecture was such dull that half the audience fell asleep. / The lecture was so dull as half the audience fell asleep. / The lecture was so a dull that half the audience fell asleep.|0|“So + adj + that” nêu kết quả; “dull” là tính từ nên dùng “so”, và vế sau dùng “that”.|The lecture was such dull that half the audience fell asleep.=>“Such” cần đi với danh từ; “dull” là tính từ đứng một mình nên phải dùng “so”.;;The lecture was so dull as half the audience fell asleep.=>“So … as” không nêu kết quả; liên từ đúng sau “so + adj” là “that”.;;The lecture was so a dull that half the audience fell asleep.=>Không đặt “a” sau “so” trước tính từ như vậy; phải là “so dull” hoặc “such a dull lecture”.\nx|Chọn câu đúng về mục đích phủ định|She sat near the door so that not to disturb the speaker. / She sat near the door so as not to disturb the speaker. / She sat near the door lest to disturb the speaker. / She sat near the door so as to not disturb the speaker.|1|Cùng chủ ngữ nên dùng “so as not to + V”, và “not” đứng ngay trước “to”.|She sat near the door so that not to disturb the speaker.=>“So that” cần mệnh đề có chủ ngữ, không đi với “not to + V”.;;She sat near the door lest to disturb the speaker.=>“Lest” đi với mệnh đề (should/V nguyên mẫu), không đi với “to + V”.;;She sat near the door so as to not disturb the speaker.=>Dạng “to not” bị coi là kém trang trọng; câu chuẩn viết “so as not to” với “not” trước “to”.\nx|Chọn câu đúng về nhượng bộ|However the outcome of the trial, the data will be published. / Whoever the outcome of the trial, the data will be published. / Whatever the outcome of the trial, the data will be published. / No matter the outcome of the trial is, the data will be published.|2|“Whatever + danh từ” nhượng bộ vô điều kiện cho sự vật; “outcome” là danh từ nên dùng “whatever”.|However the outcome of the trial, the data will be published.=>“However” cần đi với tính từ hoặc trạng từ (however good), không đứng trước danh từ “outcome”.;;Whoever the outcome of the trial, the data will be published.=>“Whoever” chỉ người, không dùng cho một kết quả.;;No matter the outcome of the trial is, the data will be published.=>Sau “no matter” cần từ nghi vấn (what/how), không dùng thẳng “the outcome … is” như vậy.\nx|Chọn câu đúng về đảo tính từ|Tired although she was, Mai finished the audit before leaving. / As tired she was, Mai finished the audit before leaving. / Tired but she was, Mai finished the audit before leaving. / Tired as she was, Mai finished the audit before leaving.|3|Cấu trúc “adj + as + S + V” nghĩa là “dù … đến đâu”, với tính từ đứng trước “as”.|Tired although she was, Mai finished the audit before leaving.=>Không đảo tính từ lên trước “although”; đảo trước chỉ dùng với “as” hoặc “though”.;;As tired she was, Mai finished the audit before leaving.=>Trong cấu trúc nhượng bộ này tính từ phải đứng trước “as”, không phải sau.;;Tired but she was, Mai finished the audit before leaving.=>“But” không dùng để mở cấu trúc nhượng bộ đảo tính từ.\nt|The cleaners come at dawn ___ (so/that) the offices are ready by eight.|so that|“So that” nối mục đích với một mệnh đề có chủ ngữ riêng (the offices are ready).\nt|It was ___ (such/so) a heavy workload that two interns resigned.|such|Trước “a + adj + N” dùng “such”; vế sau “that two interns resigned” là kết quả.\nt|She locked the cabinet ___ (lest/so) anyone should take the records.|lest|“Lest … should” nghĩa là “kẻo”, diễn tả điều muốn tránh: người lạ lấy hồ sơ.\nt|The results were ___ (so/such) inconsistent that we repeated the experiment.|so|“Inconsistent” là tính từ đứng một mình nên dùng “so … that” để nêu kết quả.\nt|___ (Seeing/Given) that the deadline has passed, we should plan a new schedule.|seeing;given|Cả “Seeing that” và “Given that” đều nêu lý do đã biết dẫn tới đề xuất ở vế sau.\nt|The plan is cheap, ___ (albeit/although) risky.|albeit|Chỗ trống đứng trước tính từ “risky”, không có chủ ngữ và động từ, nên chỉ dùng “albeit”.\nf|The nurse spoke softly so that not to wake the other patients.|that|as|Với “not to + V” phải dùng “so as not to”; “so that” cần mệnh đề đầy đủ.\nf|It was so a difficult decision that the board postponed the vote.|so|such|Trước “a + adj + N” phải dùng “such a”, không dùng “so a”.\nf|Whoever the problem is, we must act quickly to solve it.|Whoever|Whatever|“Problem” là sự vật nên dùng “whatever”; “whoever” chỉ người.\nf|Much although I would like to help, I have no time today.|although|as|“Much as” (dù rất) là cụm nhượng bộ cố định; “although” không đi sau “much” theo cách này.\no|The nurses stayed late so that the new system would be ready.|Mệnh đề mục đích “so that + S + would + V” đứng sau mệnh đề chính.\no|However tired he was, he checked every chart carefully.|“However + adj + S + V” đứng đầu câu, sau đó là dấu phẩy và mệnh đề chính.","articles-advanced":"c|___ is the longest river in Africa.|Nile / The Nile / A Nile / Nile River the|1|Tên sông luôn dùng the: the Nile. Dấu hiệu là cụm so sánh nhất “the longest river” chỉ một con sông duy nhất.|Nile=>“Nile” không có mạo từ không hợp vì tên sông luôn đi với the trong câu này.;;A Nile=>“A Nile” coi nó như một con sông bất kỳ, trong khi đây là con sông duy nhất, xác định.;;Nile River the=>Trật tự từ sai; phải là “the Nile” hoặc “the River Nile”, không đảo the ra sau.\nc|Doctors say that ___ often suffer from loneliness.|the elderly / elderly / the elderlies / an elderly|0|“The + tính từ” chỉ cả nhóm người và đi với động từ số nhiều. Động từ “suffer” không có -s là gợi ý chủ ngữ số nhiều.|elderly=>“elderly” đứng một mình không làm chủ ngữ chỉ nhóm người; cần the đứng trước.;;the elderlies=>Tính từ không thêm -s khi dùng như “the + tính từ”, nên “elderlies” sai.;;an elderly=>“an elderly” chỉ một người, nhưng động từ “suffer” là số nhiều.\nc|My sister has been in ___ since Monday because of appendicitis.|the hospital / a hospital / hospital / hospitals|2|Khi nói ai đó là bệnh nhân nằm viện, ta dùng “in hospital” không mạo từ (Anh-Anh). Cụm “because of appendicitis” xác nhận đây là điều trị.|the hospital=>Thêm the gợi ý toà nhà cụ thể, trong khi ở đây cô ấy là bệnh nhân điều trị.;;a hospital=>“a hospital” cho biết một bệnh viện bất kỳ, không hợp khi nói về việc nằm viện.;;hospitals=>Dạng số nhiều không hợp vì chỉ có một người đang nằm viện, và cụm cố định không dùng số nhiều.\nc|We usually travel to the coast ___ because it is cheaper than driving.|by the train / with train / in a train / by train|3|Phương tiện nói chung dùng “by + danh từ” không mạo từ. Ý “cheaper than driving” cho thấy đang so sánh cách di chuyển.|by the train=>Sau “by” chỉ phương tiện nói chung thì không dùng the.;;with train=>Giới từ “with” không dùng để chỉ phương tiện đi lại trong cụm cố định này.;;in a train=>“in a train” chỉ vị trí ở trong một toa cụ thể, không diễn tả cách di chuyển nói chung.\nc|After ___ yesterday, I felt much better.|lunch / the lunch / a lunch / lunches|0|Tên bữa ăn dùng không mạo từ khi nói bình thường: after lunch. Câu không mô tả bữa ăn đặc biệt nên không cần a hay the.|the lunch=>The lunch dùng khi bữa ăn cụ thể được nhắc đến; ở đây chỉ bữa ăn thông thường.;;a lunch=>“a lunch” cần tính từ mô tả như “a heavy lunch”; câu này không có.;;lunches=>Số nhiều không hợp vì “yesterday” nói về một bữa duy nhất.\nc|I need to see ___ doctor about this cough; I hope she has time today.|a / the / an / some|0|Nhắc đến lần đầu, chưa xác định nên dùng “a doctor”. Chỉ sau đó “she” mới là bác sĩ đã biết.|the=>“the” cho thấy bác sĩ đã xác định, mà người nói chỉ nhắc lần đầu.;;an=>“an” dùng trước nguyên âm; “doctor” bắt đầu bằng phụ âm /d/.;;some=>“some” không đi với danh từ số ít đếm được trong câu này.\nc|___ is not always the answer, but many people still believe it solves every problem.|The money / Money / A money / Moneys|1|Danh từ không đếm được mang nghĩa chung dùng không mạo từ. “Many people still believe” cho thấy ý niệm chung về tiền.|The money=>“The money” chỉ một khoản tiền cụ thể, trong khi câu nói về tiền nói chung.;;A money=>“money” không đếm được nên không đi với a.;;Moneys=>Tiền nói chung không có dạng số nhiều trong cách dùng này.\nc|Everest is the highest peak in ___ Himalayas.|the / a / an / no article|0|Dãy núi dùng the: the Himalayas, the Alps. Còn từng đỉnh như Everest thì không có mạo từ.|a=>“a” không dùng với tên dãy núi vì đây là địa danh xác định.;;an=>“an” không hợp, vì “Himalayas” là địa danh duy nhất.;;no article=>Tên dãy núi số nhiều luôn cần the; bỏ the là sai.\nc|Scientists believe that ___ will become extinct within fifty years.|giant panda / a giant panda / the giant pandas / the giant panda|3|Nói về cả loài với danh từ số ít thì dùng the: the giant panda. Động từ “will become extinct” nói về loài, không phải một cá thể.|giant panda=>Danh từ đếm được số ít không thể đứng trơ trọi không mạo từ ở nghĩa chung.;;a giant panda=>“a giant panda” chỉ một con, nhưng “scientists believe” nói về cả loài.;;the giant pandas=>“the + số nhiều” chỉ một nhóm cụ thể, không chỉ cả loài.\nc|The nurse took ___ temperature and recorded it on the chart.|a patient's / patient's / the patient's / some patient's|2|Bệnh nhân đang nằm trong tình huống đã biết, nên dùng the. Chỗ trống cần cụm xác định trước “temperature” và “recorded it”.|a patient's=>“a patient’s” chỉ một bệnh nhân bất kỳ, không hợp với bệnh nhân đang được chăm sóc.;;patient's=>Sở hữu cách không có mạo từ ở đây khiến cụm “patient’s temperature” thiếu xác định.;;some patient's=>“some” không đi với danh từ số ít để chỉ người đang được nhắc tới cụ thể.\nc|She studied ___ at university but now works as a translator.|the law / law / a law / laws|1|Tên môn học dùng không mạo từ: study law, study medicine. Cụm “studied … at university” cho thấy đây là môn học, không phải luật cụ thể.|the law=>“the law” chỉ luật pháp cụ thể của một nước, không phải ngành học.;;a law=>“a law” là một đạo luật cụ thể, không phải môn học.;;laws=>“laws” là các đạo luật; ngành học dùng dạng không đếm được.\nc|It is ___ most reliable method we have tested so far.|the / a / an / no article|0|So sánh nhất luôn đi với the. “So far” cho thấy chỉ có một phương pháp đáng tin cậy nhất trong số đã thử.|a=>“a” không dùng trước so sánh nhất “most reliable” vì ý nghĩa là duy nhất.;;an=>“an” không hợp trước “most” và phá nghĩa so sánh nhất.;;no article=>Thiếu mạo từ, so sánh nhất “most reliable method” cần the.\nc|Is ___ United Kingdom a member of the European Union nowadays?|a / Ø / the / an|2|Tên nước có Kingdom/Republic/States dùng the: the United Kingdom, the Czech Republic. Dạng số nhiều như the Netherlands cũng vậy.|a=>“a” không dùng với tên nước chứa “Kingdom”; đây là một thực thể duy nhất.;;Ø=>Tên nước có Kingdom, Republic hay States cần the; bỏ the là sai.;;an=>“an” không hợp vì danh từ riêng này xác định duy nhất.\nc|Children who eat ___ breakfast tend to concentrate better at school.|a healthy / healthy / the healthy / healthies|0|Khi bữa ăn có tính từ mô tả, ta dùng a/an: a healthy breakfast. “Eat breakfast” thì không mạo từ, nhưng ở đây có “healthy”.|healthy=>Bữa sáng có tính từ mô tả “healthy” thì cần a trước tính từ.;;the healthy=>“the healthy” chỉ nhóm người khoẻ mạnh, không hợp trước “breakfast”.;;healthies=>“healthies” không phải dạng đúng; tính từ không thêm -s.\nx|Chọn câu đúng về người cao tuổi|The poors are often the last to receive medical help. / The poor are often the last to receive medical help. / The poor is often the last to receive medical help. / Poor are often the last to receive medical help.|1|The + tính từ chỉ nhóm người nên chia động từ số nhiều và không thêm -s: the poor are. Đáp án duy nhất đủ the và “are”.|The poors are often the last to receive medical help.=>“poors” sai vì “the + tính từ” không thêm -s dù mang nghĩa số nhiều.;;The poor is often the last to receive medical help.=>Động từ “is” sai vì nhóm “the poor” phải đi với động từ số nhiều.;;Poor are often the last to receive medical help.=>Thiếu the trước “poor” nên không biến thành danh từ chỉ nhóm người.\nx|Chọn câu đúng về loài hổ|Tigers are in danger because their habitat is shrinking. / The tigers are in danger because their habitat is shrinking. / A tigers are in danger because their habitat is shrinking. / Tiger are in danger because their habitat is shrinking.|0|Nói chung về cả loài với số nhiều thì không dùng mạo từ: Tigers are. Các lựa chọn khác sai về the hoặc số.|The tigers are in danger because their habitat is shrinking.=>“The tigers” chỉ một nhóm hổ cụ thể, không phải cả loài nói chung.;;A tigers are in danger because their habitat is shrinking.=>“A” không đi với danh từ số nhiều “tigers”.;;Tiger are in danger because their habitat is shrinking.=>“Tiger” số ít không có mạo từ và không hợp với động từ “are”.\nx|Chọn câu đúng về bệnh cúm|My father caught the flu last winter and stayed in bed for a week. / My father caught flu last winter and stayed in the bed for a week. / My father caught a flu last winter and stayed in bed for a week. / My father caught the flu last winter and stayed in the bed for a week.|0|“Catch the flu” là cách nói chuẩn và “in bed” là cụm cố định chỉ việc nằm nghỉ. Chỉ câu này đúng cả hai chỗ.|My father caught flu last winter and stayed in the bed for a week.=>“the bed” sai vì nằm nghỉ ốm nói chung dùng “in bed” không mạo từ.;;My father caught a flu last winter and stayed in bed for a week.=>“a flu” không tự nhiên; bệnh này dùng “the flu” hoặc “flu”, không dùng a.;;My father caught the flu last winter and stayed in the bed for a week.=>“in the bed” chỉ chiếc giường cụ thể, trong khi ý nói chung là nằm nghỉ.\nx|Chọn câu đúng về địa danh|The Mount Fuji is in Japan, but the Andes are in South America. / Mount Fuji is in the Japan, but the Andes are in South America. / Mount Fuji is in Japan, but Andes are in South America. / Mount Fuji is in Japan, but the Andes are in South America.|3|Đỉnh núi và nước đơn lẻ không dùng the, còn dãy núi thì có the: the Andes. Chỉ một câu thoả cả ba điều này.|The Mount Fuji is in Japan, but the Andes are in South America.=>Đỉnh núi riêng lẻ như Mount Fuji không dùng the.;;Mount Fuji is in the Japan, but the Andes are in South America.=>Tên nước Japan không dùng the vì không có Republic hay Kingdom.;;Mount Fuji is in Japan, but Andes are in South America.=>Dãy núi số nhiều the Andes bắt buộc có the.\nt|Mrs Lee works as ___ engineer at a hospital. (a / an / the)|an|Nghề nghiệp dùng a/an trước danh từ đếm được số ít, và “engineer” bắt đầu bằng nguyên âm nên dùng an.\nt|The old man was taken to ___ hospital where his daughter works. (a / the / no article = x)|the|“where his daughter works” xác định bệnh viện cụ thể, nên cần the thay vì cách nói cố định.\nt|Tigers are strong, but ___ blue whale is far larger. (a / the / no article = x)|the|Loài duy nhất nói chung với danh từ số ít dùng the: the blue whale, nghĩa là cả loài cá voi xanh.\nt|She left ___ school at four o'clock to catch the bus. (a / the / no article = x)|x|Với nghĩa chức năng (đi học) trong “left school at four”, ta không dùng mạo từ.\nf|The unemployed needs more support from the government.|needs|need|“The unemployed” chỉ nhóm người, nghĩa số nhiều nên động từ phải là need, không có -s.\nf|She travels to work with bus every morning.|with|by|Phương tiện đi lại dùng “by + danh từ”, và danh từ “bus” đứng không mạo từ: by bus.\nf|Life of a student can be very stressful in the first year.|Life|The life|Có giới hạn “of a student” nên danh từ trừu tượng cần the: The life of a student.\no|The elderly in this town rely on the volunteers.|Chủ ngữ “the elderly” là nhóm người, theo sau là động từ số nhiều “rely” rồi cụm giới từ.","comparison-advanced":"c|The ___ you practise speaking, the more fluent you will become.|hardest / much / most / harder|3|Cấu trúc “the + so sánh hơn, the + so sánh hơn”; vế đầu cần trạng từ so sánh hơn “harder”, dấu hiệu là “the” và vế sau “the more fluent”.|hardest=>“hardest” là dạng so sánh nhất, không dùng trong cấu trúc “the … the …” vốn cần hai so sánh hơn.;;much=>“much” không phải dạng so sánh hơn nên không mở được vế đầu của cấu trúc này.;;most=>“most” là dạng so sánh nhất và không bổ nghĩa cho động từ practise theo cách tự nhiên ở đây.\nc|Wages in the region are rising, and living costs are getting ___.|high and high / more high / higher and higher / the higher|2|Thay đổi dần dần dùng “so sánh hơn + and + so sánh hơn”; tính từ ngắn high thành “higher and higher”, dấu hiệu là “are getting”.|high and high=>“high and high” không phải dạng so sánh hơn nên không diễn tả được sự tăng dần trong câu này.;;more high=>“more high” sai vì tính từ ngắn high tạo so sánh hơn bằng -er, không dùng more.;;the higher=>“the higher” cần có vế thứ hai kiểu “the … the …”, còn câu này mô tả thay đổi liên tục.\nc|The new treatment is ___ more effective than the old one, according to the trial.|very / far / most / so|1|Trước so sánh hơn dùng much/far/a great deal để nhấn mạnh; “far more effective than” khớp với “than the old one”.|very=>“very” không đứng trước so sánh hơn nên “very more effective” sai trong câu này.;;most=>“most” là dạng so sánh nhất và không thể đi cùng “more … than” trong câu so sánh hai đối tượng.;;so=>“so more effective than” không tạo thành cách nói đúng; “so” không bổ nghĩa cho so sánh hơn.\nc|This flat is ___ as the one we saw yesterday, so it isn't worth the price.|not nearly as spacious / not nearly more spacious / nearly not as spacious / not as nearly spacious|0|“Not nearly as + adj + as” nhấn mạnh sự kém xa; cụm cố định và cuối câu có “as the one we saw”.|not nearly more spacious=>“more spacious” bị kết hợp với “as … as” khiến cấu trúc sai, trong khi vế sau là “as the one”.;;nearly not as spacious=>Trật tự “nearly not” không tự nhiên; “not nearly” mới là cụm đứng trước as.;;not as nearly spacious=>“not as nearly” đảo vị trí của nearly nên không thành cấu trúc quen thuộc.\nc|Of the two candidates, Mai is ___ and has the stronger references.|the more experienced / the most experienced / most experienced / more experienced one|0|Khi chỉ có hai đối tượng (“Of the two”) dùng “the + so sánh hơn”; vế sau cũng dùng “the stronger” cho hai người.|the most experienced=>“the most experienced” là so sánh nhất, dùng cho từ ba đối tượng trở lên, trong khi câu nói “Of the two”.;;most experienced=>“most experienced” thiếu “the” và là dạng so sánh nhất nên không hợp với hai ứng viên.;;more experienced one=>“more experienced one” thiếu “the” và thừa “one”, không phù hợp với cách nói của vế còn lại.\nc|There were ___ complaints this year than last year, which pleased the manager.|less / fewer / little / the fewest|1|“Complaints” là danh từ đếm được số nhiều nên dùng “fewer”; cụm “than last year” cho thấy cần so sánh hơn.|less=>“less” dùng với danh từ không đếm được, mà “complaints” là danh từ đếm được số nhiều.;;little=>“little” không phải dạng so sánh hơn nên không đi với “than last year”.;;the fewest=>“the fewest” là so sánh nhất, không hợp với cấu trúc “than last year”.\nx|Chọn câu đúng: thay đổi song song|The more we waited, the more nervous we got. / The more we waited, we got more nervous. / More we waited, the more nervous we got. / The more we waited, more nervous we got.|0|Cả hai vế phải bắt đầu bằng “the + so sánh hơn”.|The more we waited, we got more nervous.=>Vế sau thiếu “the” đứng đầu nên hai vế không đối xứng.;;More we waited, the more nervous we got.=>Vế đầu thiếu “The” mở đầu nên cấu trúc không hoàn chỉnh.;;The more we waited, more nervous we got.=>Vế sau thiếu “the” trước “more nervous” nên không đúng cấu trúc.\nx|Chọn câu đúng: nhấn mạnh so sánh hơn|Her results are very better than last term's. / Her results are much better than last term's. / Her results are much more better than last term's. / Her results are most better than last term's.|1|Trước so sánh hơn dùng much, không dùng very/most; “better” đã là so sánh hơn.|Her results are very better than last term's.=>“very” không đứng trước so sánh hơn nên câu này sai.;;Her results are much more better than last term's.=>“more better” là so sánh kép vì better đã là dạng so sánh hơn.;;Her results are most better than last term's.=>“most better” trộn so sánh nhất với so sánh hơn nên không đúng.\nt|The population of the town is ___ (twice / large) as it was in 1990.|twice as large|Bội số dùng “twice as + tính từ + as”, ở đây “as it was” là vế sau.\nt|The ___ (old) he got, the wiser he became.|older|Vế đầu của cấu trúc “the … the …” cần so sánh hơn của old, ở đây là older.\nf|The more you read, the best your vocabulary becomes.|best|better|Vế sau của “the … the …” cần so sánh hơn better, không dùng so sánh nhất best.\no|The more data we collect, the clearer the pattern becomes.|Cấu trúc “the + so sánh hơn + S + V” ở cả hai vế, so sánh hơn đứng ngay sau the.\nc|Of all the students in the group, Hoa is ___ the most hard-working.|more / by far / very / even more|1|“By far” đứng trước so sánh nhất để nhấn mạnh sự vượt trội; cụm “of all” và “the most” là dấu hiệu.|more=>“more” là dạng so sánh hơn và không đứng trước “the most” trong cùng một cụm so sánh nhất.;;very=>“very” không đứng trước “the most” để nhấn mạnh khi nói về nhóm nhiều người.;;even more=>“even more the most” trộn hai kiểu so sánh nên không thành câu đúng.\nc|Our new software is only half as fast ___ the old system, so we are going back to it.|than / as / like / from|1|Cấu trúc bội số “half as … as” cần từ “as” thứ hai; vế “the old system” là đối tượng so sánh.|than=>“than” đi với dạng so sánh hơn, không đi với “as fast” trong cấu trúc “half as … as”.;;like=>“like” không dùng để nối hai vế của so sánh sau “as fast” trong câu này.;;from=>“from” dùng cho khác biệt như “different from”, không dùng sau “as fast”.\nc|The more she thought about the offer, ___ she liked it.|less / the less / the least / the lesser|1|Vế sau của “the more …, the …” cần “the + so sánh hơn”; “the less” diễn tả thay đổi ngược chiều.|less=>“less” thiếu “the” mở đầu nên vế sau không đối xứng với “The more”.;;the least=>“the least” là so sánh nhất, không dùng trong cấu trúc hai vế này.;;the lesser=>“the lesser” nghĩa là nhỏ hơn trong hai thứ, không phải so sánh hơn của little.\nc|Costs have been climbing ___ over the past decade, and many families cannot cope.|more steady / steady and steady / more and more steadily / steadily and steadily more|2|Thay đổi dần dùng “more and more + trạng từ” bổ nghĩa cho động từ climbing; steadily là trạng từ nên cần more and more.|more steady=>“more steady” là dạng tính từ và thiếu “and more” nên không diễn tả thay đổi dần dần.;;steady and steady=>“steady and steady” là tính từ lặp lại, không bổ nghĩa cho động từ climbing.;;steadily and steadily more=>“steadily and steadily more” sai trật tự, “more and more” phải đứng trước trạng từ.\nc|She earns three times ___ she did in her previous job.|more than / as much as / much as / as many as|1|Bội số + “as much as” dùng với tiền lương (không đếm được); cụm “as she did” cho thấy vế so sánh “as … as”.|more than=>“three times more than she did” thường gây mơ hồ về nghĩa và không khớp với cách nói chuẩn “three times as much as”.;;much as=>“much as” thiếu “as” đầu tiên nên không đúng cấu trúc.;;as many as=>“as many as” dùng với danh từ đếm được số nhiều, mà tiền lương là không đếm được.\nc|The patient's condition is ___ worse than it was on admission, so we have changed the plan.|very / a great deal / much of / the|1|“A great deal” đứng trước so sánh hơn để nhấn mạnh chênh lệch lớn; “worse” là so sánh hơn nên không đi với “very”.|very=>“very” không đứng trước so sánh hơn như “worse”.;;much of=>“much of” không phải cách nói đúng trước so sánh hơn.;;the=>“the worse than” không hợp vì “the” chỉ dùng khi có cấu trúc “the … the …”.\nx|Chọn câu đúng: bội số|The queue was twice longer than yesterday. / The queue was twice as long as yesterday. / The queue was as twice long as yesterday. / The queue was twice so long as yesterday.|1|Bội số dùng cấu trúc “twice as + tính từ + as”.|The queue was twice longer than yesterday.=>“twice longer than” không phải cấu trúc chuẩn cho bội số trong tiếng Anh viết.;;The queue was as twice long as yesterday.=>“twice” bị đặt giữa hai từ as nên sai trật tự.;;The queue was twice so long as yesterday.=>“so long as” thay cho “as long as” nên sai cấu trúc.\nx|Chọn câu đúng: chênh lệch nhỏ|The second test was slightly more easy than the first. / The second test was slightly easier than the first. / The second test was slight easier than the first. / The second test was slightly the easier than the first.|1|Trạng từ slightly bổ nghĩa cho so sánh hơn; easy là tính từ ngắn nên dùng easier.|The second test was slightly more easy than the first.=>easy là tính từ ngắn nên so sánh hơn là easier, không dùng “more easy”.;;The second test was slight easier than the first.=>“slight” là tính từ, không thể bổ nghĩa cho so sánh hơn easier.;;The second test was slightly the easier than the first.=>“the easier than” sai vì “the” và “than” không đi cùng nhau trong câu so sánh hơn này.\nt|There have been ___ (few) accidents on this road since the new limit was introduced.|fewer|Danh từ đếm được accidents đi với fewer, dạng so sánh hơn của few.\nt|The report was ___ (slight) more detailed than the first draft.|slightly|Trước so sánh hơn dùng trạng từ slightly để chỉ chênh lệch nhỏ.\nf|This course is far much more demanding than I expected.|much|(xoá)|Chỉ dùng một từ nhấn mạnh như far hoặc much trước so sánh hơn, không dùng cả hai.\no|She is by far the most reliable member of the team.|By far đứng trước the most để nhấn mạnh so sánh nhất.\nc|Neither of the two proposals is perfect, but the second is ___ of the two.|better / best / the better / the best|2|Khi chỉ có hai đối tượng dùng “the + so sánh hơn”; cụm “of the two” là dấu hiệu rõ ràng.|better=>thiếu mạo từ “the” trước better nên không đúng với cấu trúc “is … of the two”.;;best=>“best” là so sánh nhất, không dùng khi chỉ có hai đối tượng.;;the best=>“the best” là so sánh nhất, dùng cho ba đối tượng trở lên, mà ở đây chỉ có hai.","discourse-markers":"c|The tutor praised my argument. ___, she said the evidence was thin.|Moreover / That said / In other words / All in all|1|“That said” báo hiệu sự nhượng bộ hoặc đối lập nhẹ; manh mối là lời khen ở câu trước và nhận xét tiêu cực ở câu sau.|Moreover=>“Moreover” thêm ý cùng hướng, trong khi lời nhận xét về bằng chứng yếu đi ngược lại lời khen.;;In other words=>“In other words” diễn đạt lại ý trước, còn câu sau lại nêu một ý mới đối lập với lời khen.;;All in all=>“All in all” dùng để kết luận cuối bài, không hợp khi mới chuyển sang một nhận xét trái chiều.\nc|The flat is cheap and close to the station. ___, it has a small garden.|Nevertheless / On the other hand / What is more / In other words|2|“What is more” thêm một ý mạnh cùng hướng; manh mối là hai ưu điểm đã nêu (cheap, close) và vườn nhỏ là ưu điểm thứ ba.|Nevertheless=>“Nevertheless” báo hiệu đối lập, nhưng khu vườn nhỏ là thêm một ưu điểm nữa chứ không trái ngược.;;On the other hand=>“On the other hand” đưa ra mặt đối lập, trong khi câu này tiếp tục liệt kê ưu điểm của căn hộ.;;In other words=>“In other words” chỉ dùng để nói lại ý trước; vườn là thông tin mới, không phải cách diễn đạt khác.\nc|Our budget has been cut by half; ___, we can only run one clinic instead of two.|in other words / on the other hand / mind you / to begin with|0|“In other words” nói lại ý vừa nêu cho rõ hơn; ở đây vế sau diễn giải cụ thể hậu quả của việc cắt ngân sách một nửa.|on the other hand=>“On the other hand” mở ra ý đối lập, còn vế sau chỉ là hệ quả cụ thể, diễn giải lại của việc cắt ngân sách.;;mind you=>“Mind you” là lời nhượng bộ thân mật, không dùng để giải thích rõ hơn ý ở vế trước.;;to begin with=>“To begin with” chỉ mở đầu một chuỗi ý, không có chức năng giải thích lại sau dấu chấm phẩy.\nc|There are good arguments on both sides. ___, I think the benefits just outweigh the risks.|By the way / Firstly / For example / On balance|3|“On balance” chốt kết luận sau khi cân nhắc hai phía; manh mối là “both sides” và động từ “outweigh”.|By the way=>“By the way” chuyển sang chuyện phụ, trong khi câu này đang đưa ra kết luận sau khi cân nhắc.;;Firstly=>“Firstly” mở đầu danh sách các ý, không hợp với câu mang tính kết luận sau khi đã nêu hai phía.;;For example=>“For example” đưa ví dụ minh hoạ, nhưng vế sau là phán đoán tổng hợp, không phải ví dụ.\nc|A: What did you think of the conference? B: It was fine. ___, I only attended two talks, so I can't say much.|Moreover / To be fair / Finally / In conclusion|1|“To be fair” dùng để nhượng bộ hoặc giới hạn nhận xét vừa nói; manh mối là vế sau “I can't say much”.|Moreover=>“Moreover” thêm ý cùng hướng, trong khi người nói đang tự hạn chế giá trị nhận xét của mình.;;Finally=>“Finally” báo hiệu điểm cuối trong một chuỗi ý, mà ở đây chưa có chuỗi nào.;;In conclusion=>“In conclusion” dùng cho phần kết của bài; trong hội thoại ngắn này nó nghe cứng và lạc chỗ.\nc|The company has expanded rapidly. ___, its profits have fallen.|Furthermore / In other words / Firstly / Nevertheless|3|“Nevertheless” là marker đối lập trang trọng, hợp với văn viết; manh mối là sự tương phản giữa mở rộng nhanh và lợi nhuận giảm.|Furthermore=>“Furthermore” thêm ý cùng hướng, nhưng lợi nhuận giảm lại mâu thuẫn với sự mở rộng nhanh.;;In other words=>“In other words” diễn đạt lại, mà lợi nhuận giảm không phải cách nói khác của việc mở rộng.;;Firstly=>“Firstly” mở đầu một chuỗi ý có thứ tự, nhưng câu sau không phải điểm thứ nhất của danh sách nào.\nc|___, we need to decide the budget. Secondly, we need to choose a venue.|To begin with / Finally / All in all / On balance|0|“To begin with” mở đầu chuỗi ý; manh mối là “Secondly” ở câu sau, nên câu đầu phải là điểm thứ nhất.|Finally=>“Finally” đánh dấu ý cuối cùng, nhưng câu tiếp theo đã dùng “Secondly” nên đây phải là ý đầu tiên.;;All in all=>“All in all” dùng để tóm tắt kết luận, không dùng để mở một danh sách các việc.;;On balance=>“On balance” dùng sau khi cân nhắc ưu nhược điểm, không phù hợp với việc liệt kê công việc cần làm.\nx|Chọn câu đúng (however)|The trial was small. In the other hand, the results were promising. / The trial was small. But however, the results were promising. / The trial was small. However, the results were promising. / The trial was small. However to this, the results were promising.|2|Marker như “however” đứng giữa hai câu độc lập cần dấu chấm hoặc chấm phẩy ở trước và dấu phẩy ở sau.|The trial was small. But however, the results were promising.=>“But” và “however” cùng báo hiệu đối lập nên dùng cả hai là thừa, chỉ cần một trong hai.;;The trial was small. In the other hand, the results were promising.=>Cụm cố định là “on the other hand”, giới từ “in” trước “the other hand” là sai.;;The trial was small. However to this, the results were promising.=>“However” không đi với “to this”; marker đối lập đứng riêng và có dấu phẩy sau nó.\nx|Chọn câu đúng (on the contrary)|I expected the exam to be easy. In the contrary, it was the hardest I have ever taken. / I expected the exam to be easy. On the contrary, it was the hardest I have ever taken. / I expected the exam to be easy. At the contrary, it was the hardest I have ever taken. / I expected the exam to be easy. On contrary, it was the hardest I have ever taken.|1|“On the contrary” là cụm cố định, dùng để phủ nhận trực tiếp điều vừa nêu hoặc điều người ta có thể nghĩ.|I expected the exam to be easy. In the contrary, it was the hardest I have ever taken.=>Cụm cố định là “on the contrary”, không phải “in the contrary”.;;I expected the exam to be easy. At the contrary, it was the hardest I have ever taken.=>“At the contrary” không tồn tại trong tiếng Anh; cụm đúng dùng giới từ “on”.;;I expected the exam to be easy. On contrary, it was the hardest I have ever taken.=>Cụm này thiếu mạo từ “the” nên không đúng; phải là “on the contrary”.\nt|All ___ all, the course was well worth the money. (one word)|in|Cụm kết luận cố định là “all in all”, nghĩa là nhìn chung, dùng để chốt lại ý.\nt|The first option is cheaper. On the ___ hand, the second is much faster. (one word)|other|Cụm đối lập cố định là “on the other hand”, dùng để nêu mặt khác của vấn đề.\nf|The treatment is cheap. On top from that, it works quickly.|from|of|Cụm cố định là “on top of that” (thêm vào đó), giới từ đi sau “top” là “of”, không phải “from”.\no|Even so, the results were not statistically significant.|Marker “even so” đứng đầu câu và tách khỏi mệnh đề chính bằng dấu phẩy.\nc|A: So you live in Hanoi? B: ___, I'm from Hue, but I work in Hanoi.|Moreover / Finally / Actually / To sum up|2|“Actually” dùng để chỉnh lại hoặc làm rõ điều người kia hiểu chưa đúng; manh mối là câu hỏi “So you live in Hanoi?”.|Moreover=>“Moreover” thêm ý cùng hướng, trong khi B đang chỉnh lại điều A vừa đoán.;;Finally=>“Finally” đánh dấu ý cuối trong một chuỗi, không dùng để sửa lại một giả định trong hội thoại.;;To sum up=>“To sum up” dùng để tóm tắt sau một đoạn dài, không hợp để mở lời đính chính ngắn.\nc|I'll send the report on Monday. ___, did you book the room for the meeting?|In other words / All in all / On the contrary / By the way|3|“By the way” báo hiệu chuyển sang một chủ đề phụ ngoài mạch chính; manh mối là câu hỏi mới không liên quan đến báo cáo.|In other words=>“In other words” diễn đạt lại ý trước, trong khi câu hỏi về phòng họp là một chủ đề khác.;;All in all=>“All in all” dùng để kết luận, nhưng ở đây người nói chỉ chuyển sang chuyện phụ.;;On the contrary=>“On the contrary” phủ nhận ý vừa nêu, không phải cách để thêm câu hỏi ngoài lề.\nc|We've been talking for an hour. ___, we should get back to the agenda.|Moreover / Secondly / For instance / Anyway|3|“Anyway” dùng để kết thúc phần lan man và quay lại chủ đề chính; manh mối là “talking for an hour” và “get back”.|Moreover=>“Moreover” thêm ý cùng hướng, trong khi người nói muốn kết thúc đoạn nói chuyện lan man.;;Secondly=>“Secondly” cần có “firstly” trước đó, mà ở đây không có chuỗi ý nào được đánh số.;;For instance=>“For instance” mở ra một ví dụ, nhưng vế sau là lời đề nghị quay lại chương trình.\nc|Some people love working from home. ___, others miss the office.|Moreover / On the other hand / In other words / Finally|1|“On the other hand” nêu mặt đối lập; manh mối là “some people love” đối với “others miss”.|Moreover=>“Moreover” thêm ý cùng hướng, trong khi “others miss the office” nêu quan điểm trái ngược.;;In other words=>“In other words” nói lại cùng một ý, nhưng hai nhóm người ở đây có cảm nhận khác nhau.;;Finally=>“Finally” chỉ ý cuối của một chuỗi, không có chức năng đối lập hai nhóm người.\nc|Studying abroad is expensive. ___, many students still go, thanks to scholarships.|In other words / All in all / Even so / To begin with|2|“Even so” nghĩa là bất chấp điều vừa nói; manh mối là “expensive” đối lập với “many students still go”.|In other words=>“In other words” chỉ diễn đạt lại ý trước, không giải thích được việc nhiều sinh viên vẫn đi.;;All in all=>“All in all” là marker kết luận, không dùng để nêu một sự việc diễn ra bất chấp chi phí cao.;;To begin with=>“To begin with” chỉ mở đầu chuỗi ý, trong khi ở đây cần một marker đối lập.\nc|The service is slow and the food is average. ___, I wouldn't recommend the café.|By the way / All in all / On the other hand / To begin with|1|“All in all” tóm tắt các nhận xét trước thành một kết luận; manh mối là hai điểm xấu và lời khuyên “wouldn't recommend”.|By the way=>“By the way” báo hiệu chuyển chủ đề phụ, trong khi đây là lời kết luận từ hai nhận xét trước.;;On the other hand=>“On the other hand” mở ra ý đối lập, nhưng câu này tiếp tục theo hướng tiêu cực.;;To begin with=>“To begin with” dùng ở đầu chuỗi ý, không phù hợp với câu chốt lại sau hai nhận xét.\nc|The film was far too long. ___, the acting was superb.|Moreover / In conclusion / Firstly / Mind you|3|“Mind you” thêm một điểm nhượng bộ trong lời nói thân mật; manh mối là sự tương phản giữa “too long” và “superb”.|Moreover=>“Moreover” thêm ý cùng hướng, nhưng diễn xuất tuyệt vời là điểm cộng đối lập với phim quá dài.;;In conclusion=>“In conclusion” chỉ dùng ở phần kết của bài, không hợp để thêm một nhận xét nhượng bộ.;;Firstly=>“Firstly” mở đầu một chuỗi có thứ tự, trong khi ở đây không có danh sách nào.\nx|Chọn câu đúng (firstly, secondly)|Firstly, we should check the data. In second, we should repeat the test. / At the first, we should check the data. Secondly, we should repeat the test. / Firstly of all, we should check the data. Secondly, we should repeat the test. / Firstly, we should check the data. Secondly, we should repeat the test.|3|Các marker thứ tự dùng dấu phẩy sau marker và dấu chấm giữa hai câu độc lập.|At the first, we should check the data. Secondly, we should repeat the test.=>“At the first” không phải marker mở đầu; cụm đúng là “firstly” hoặc “to begin with”.;;Firstly of all, we should check the data. Secondly, we should repeat the test.=>Cụm đúng là “first of all”, còn “firstly of all” là sự pha trộn hai cách nói.;;Firstly, we should check the data. In second, we should repeat the test.=>Marker thứ hai cần là “secondly” hoặc “second”, còn “in second” không phải cách nói tự nhiên.\nx|Chọn câu đúng (in other words)|The patient is not following the plan; in another words, she is non-compliant. / The patient is not following the plan; with other words, she is non-compliant. / The patient is not following the plan; in other words, she is non-compliant. / The patient is not following the plan, in others words, she is non-compliant.|2|“In other words” là cụm cố định, đi sau dấu chấm phẩy hoặc dấu chấm và có dấu phẩy sau nó.|The patient is not following the plan; in another words, she is non-compliant.=>Cụm cố định là “in other words”, không dùng “another” trước danh từ số nhiều “words”.;;The patient is not following the plan; with other words, she is non-compliant.=>Giới từ trong cụm cố định là “in”, không phải “with”.;;The patient is not following the plan, in others words, she is non-compliant.=>“Others” không dùng làm tính từ; cụm đúng là “other words”, và dấu phẩy ở đây tạo ra comma splice.\nt|The hotel was noisy. ___ you, it was very cheap. (one word)|mind|Marker nhượng bộ thân mật trong lời nói là “mind you”, dùng để thêm một điểm trái chiều.\nt|I'll finish the report tonight. By the ___, did you get my email? (one word)|way|Cụm chuyển chủ đề cố định là “by the way”, dùng để nói thêm điều ngoài mạch chính.\nf|To sum on, the new system saves both time and money.|on|up|Cụm kết luận cố định là “to sum up”; động từ “sum” đi với tiểu từ “up”, không phải “on”.\nf|To be frank, I think the idea is poor. As a matter for fact, I told them last week.|for|of|Cụm cố định là “as a matter of fact”, giới từ đúng là “of”, không phải “for”.","ellipsis-substitution":"c|I lost my umbrella, so I bought a new ___ yesterday.|it / ones / one / that|2|“one” thay cho danh từ đếm được số ít chưa xác định; dấu hiệu là “a new” và việc mua một chiếc mới thay chiếc đã mất.|it=>“it” chỉ chính chiếc ô đã mất, trong khi người nói mua một chiếc khác nên không hợp nghĩa.;;ones=>“ones” là số nhiều, không khớp với mạo từ “a” đứng trước “new”.;;that=>“that” không thay cho danh từ sau tính từ “new” theo cách tự nhiên trong câu này.\nc|The older tablets work well, but the newer ___ keep crashing.|one / ones / that / them|1|Danh từ bị lược là “tablets” số nhiều nên dùng “ones”; động từ “keep” và “the newer” là các dấu hiệu.|one=>“one” là số ít, không khớp với động từ số nhiều “keep” và danh từ “tablets”.;;that=>“that” không đứng sau “the newer” để thay danh từ số nhiều đếm được.;;them=>“them” là đại từ tân ngữ nên không thể làm chủ ngữ của “keep crashing”.\nc|Will the funding be cut? I hope ___.|not / no / it not / not so|0|Sau hope dùng “not” để thay cả mệnh đề phủ định; câu hỏi “Will … be cut?” cho thấy mệnh đề bị lược là “it won't be cut”.|no=>“I hope no” không tự nhiên vì “no” không thay được mệnh đề sau hope.;;it not=>Thêm “it” trước “not” làm cụm cố định “I hope not” bị sai trật tự.;;not so=>“not so” không phải cách rút gọn chuẩn; ta chỉ nói “I hope so” hoặc “I hope not”.\nc|Are all the beds taken? I'm afraid ___.|it so / that / so / yes|2|“I'm afraid so” là cụm cố định để xác nhận tin xấu; “so” thay cho mệnh đề “all the beds are taken”.|it so=>“it so” thêm đại từ thừa, vì “so” đã thay thế cả mệnh đề rồi.;;that=>“that” không đứng sau “I'm afraid” theo kiểu rút gọn trả lời như vậy.;;yes=>“yes” không kết hợp trực tiếp sau “I'm afraid” để tạo câu trả lời tự nhiên.\nc|Dr Rao said staff should wash their hands, and most of them ___.|are / make / have / do|3|Trợ từ thay thế “do” đại diện cho cụm “wash their hands”; chủ ngữ “most of them” và thì hiện tại đơn quyết định.|are=>“are” cần một tính từ hoặc V-ing phía sau, không thay được động từ thường “wash”.;;make=>“make” không thay cho cụm “wash their hands” vì nghĩa không khớp.;;have=>“have” đòi hỏi vế trước dùng thì hoàn thành, nhưng câu trước chỉ dùng “should wash”.\nc|Employees may request leave, but few ___ in their first month.|do so / do it so / make so / so do|0|“do so” thay cho cụm động từ “request leave” trong văn phong khá trang trọng; chủ ngữ “few” đi với “do”.|do it so=>“do it so” là sự pha trộn sai giữa “do it” và “do so”.;;make so=>“make so” không phải cách thay thế cụm động từ trong tiếng Anh.;;so do=>“so do” dùng để đồng tình với câu khẳng định, và nó đảo ngữ, không hợp với “but few”.\nc|Would you like to come to dinner? I'd love ___, but I have a deadline.|it / to / going / so|1|Sau “would love” có thể bỏ động từ và giữ “to”; dấu hiệu là câu mời “Would you like to come…?”.|it=>“I'd love it” nghĩa là thích một sự vật, không đáp lại lời mời đi ăn ở đây.;;going=>Dạng “going” không theo sau “I'd love” trong cách rút gọn câu mời này.;;so=>“so” chỉ dùng sau think, hope, suppose, không dùng sau “I'd love”.\nc|Neither of us wanted to leave early, but we had ___.|leave / it / to / to leave it|2|Sau “had” có thể lược động từ nguyên mẫu và giữ lại “to”; “had to” thay cho “had to leave early”.|leave=>“had leave” không thành cụm đúng và làm mất “to” cần thiết sau “had” mang nghĩa bắt buộc.;;it=>“had it” mang nghĩa sở hữu hoặc trải nghiệm, không còn là “buộc phải ra về”.;;to leave it=>“to leave it” thêm tân ngữ “it” mà động từ leave ở đây không cần, và lặp lại phần đã rõ.\nx|Chọn câu đúng: thay danh từ bằng one|I like the green folder more than the yellow one. / I like the green folder more than the yellow. / I like the green folder more than yellow one. / I like the green folder more than the yellow ones.|0|“one” thay danh từ số ít “folder” sau tính từ “yellow”, và “the yellow one” song song với “the green folder”.|I like the green folder more than the yellow.=>Thiếu “one”: tính từ “yellow” đứng một mình không thay được danh từ đếm được.;;I like the green folder more than yellow one.=>Thiếu “the” trước “yellow one”, trong khi vế trước dùng “the green folder”.;;I like the green folder more than the yellow ones.=>“ones” là số nhiều, không khớp với “folder” số ít.\nx|Chọn câu đúng: trả lời với so|Is the lab open on Sunday? I think not it. / Is the lab open on Sunday? I think so it. / Is the lab open on Sunday? I don't think so. / Is the lab open on Sunday? I don't think not.|2|Để trả lời phủ định sau think dùng “I don't think so”; “so” đã thay cả mệnh đề nên không thêm “it”.|Is the lab open on Sunday? I think not it.=>Thêm “it” sau “not” là thừa vì “not” đã thay cả mệnh đề.;;Is the lab open on Sunday? I think so it.=>Thêm “it” sau “so” là thừa, và nghĩa còn thành khẳng định.;;Is the lab open on Sunday? I don't think not.=>“I don't think not” là phủ định kép, không phải cách trả lời đúng.\nt|Can you review the draft tonight? I'd love ___, but I'm on shift.|to|Sau “would love” có thể bỏ động từ nhưng phải giữ “to” thay cho “to review it”.\nt|Will the trial be cancelled? I hope ___ (so/not): the funding is essential.|not|Người nói mong trial không bị hủy nên dùng “not” thay cho mệnh đề phủ định.\nc|Which candidate impressed you? The tall ___ with the glasses.|ones / it / persons / one|3|“one” thay danh từ số ít “candidate”; dấu hiệu là “the tall” và cụm bổ nghĩa “with the glasses” đi sau.|ones=>“ones” là số nhiều, trong khi câu hỏi nói về một ứng viên.;;it=>“it” không đứng sau tính từ “tall” để thay cho một người.;;persons=>“persons” là lặp danh từ ở dạng số nhiều và không phù hợp với “candidate” số ít.\nc|Do you think the trial will be extended? I don't think ___.|it / so / not / that so|1|Để phủ nhận quan điểm dùng “I don't think so”; với think, dạng “I think not” trang trọng, còn “I don't think not” là sai.|it=>“it” thay cho cả mệnh đề không đúng; ta cần “so”, không phải đại từ.;;not=>“not” sau “don't think” tạo phủ định kép nên sai nghĩa.;;that so=>“that so” không phải cụm rút gọn chuẩn sau “don't think”.\nc|Mia says she will attend the workshop if she ___.|can to / can / can it / is can|1|Sau trợ động từ khuyết thiếu có thể lược cả động từ chính; “if she can” thay cho “if she can attend”.|can to=>Sau “can” không dùng “to”, vì can không đi với to V.;;can it=>“can it” thêm tân ngữ “it” không có trong câu gốc, nghĩa bị lệch.;;is can=>“is can” ghép hai động từ không thể đứng cạnh nhau.\nc|The first draft was weak, but the second ___ was much better.|it / draft one / one / ones|2|Cần “one” thay “draft” số ít sau “the second”; “was” xác nhận chủ ngữ là số ít.|it=>“it” không đi sau “the second”, vì đã có mạo từ và số thứ tự.;;draft one=>“draft one” lặp danh từ và thêm “one” nên thừa, và nghĩa thành “bản nháp số một”.;;ones=>“ones” là số nhiều, không khớp với động từ số ít “was”.\nc|Did anyone fix the printer? Yes, Kai ___.|is / does / fixed it did / did|3|Câu hỏi dùng “Did … fix”, nên câu trả lời ngắn dùng trợ động từ “did” thay cho “fixed the printer”.|is=>“is” cần một tính từ hoặc V-ing, và thì hiện tại không hợp với “Did”.;;does=>“does” là hiện tại đơn, lệch với câu hỏi quá khứ.;;fixed it did=>“fixed it did” trộn hai động từ nên vô nghĩa.\nc|She wanted to resign, but her manager persuaded her not ___.|so / it / to / to resign it|2|Sau “persuade + O + not” giữ lại “to” để thay cho “to resign”; đây là dạng to-infinitive bị lược.|so=>“so” chỉ dùng sau think, hope, suppose, không dùng sau “not” trong cấu trúc này.;;it=>“it” không thay được “to resign”, nên thiếu “to” bắt buộc.;;to resign it=>“to resign it” thêm tân ngữ “it” sai vì resign không đi với it ở đây.\nx|Chọn câu đúng: do so|Visitors may park here, but few of them do so. / Visitors may park here, but few of them do so it. / Visitors may park here, but few of them are so. / Visitors may park here, but few of them so do.|0|“do so” thay cho cụm “park here”; “few of them do so” giữ trật tự chủ ngữ rồi động từ.|Visitors may park here, but few of them do so it.=>“do so it” có hai tân ngữ thay thế cùng lúc nên thừa.;;Visitors may park here, but few of them are so.=>“are so” không thay được một cụm động từ hành động.;;Visitors may park here, but few of them so do.=>“so do” đảo ngữ chỉ dùng để đồng tình, không dùng với “but few”.\nx|Chọn câu đúng: lược sau to|You can stay if you want so. / You can stay if you want to it. / You can stay if you want that to. / You can stay if you want to.|3|Có thể bỏ động từ sau “want” và giữ “to”; “if you want to” thay cho “if you want to stay”.|You can stay if you want so.=>“want so” sai vì “so” chỉ đi với think, hope, suppose, expect, không đi với want.;;You can stay if you want to it.=>“to it” thêm tân ngữ làm “to” không còn đứng cuối cụm như cách lược chuẩn.;;You can stay if you want that to.=>“want that to” thiếu động từ và “that” không có vai trò ngữ pháp rõ ràng.\nt|She doesn't smoke, but her brother ___ (do).|does|“does” thay cho động từ “smoke” đã được nhắc ở vế trước, chia theo chủ ngữ số ít.\nt|I've lost my keys, so I need to buy new ___ (one/ones).|ones|“keys” là số nhiều đếm được nên thay bằng “ones” sau tính từ “new”.\nf|I like both bags, but I'll take the larger ones.|ones|one|Chọn một trong hai túi nên dùng “one” số ít sau “the larger”.\nf|She asked me to stay, but I didn't want so.|so|to|Sau “want” giữ “to” thay cho “to stay”; “so” chỉ dùng sau think, hope, suppose.\nf|Is the pharmacy still open? I'm afraid it.|it|so|Câu trả lời cố định là “I'm afraid so/not”; “it” không thay được mệnh đề.\no|Few of the staff do so voluntarily.|Chủ ngữ “few of the staff” đứng trước, rồi “do so” thay động từ, cuối cùng là trạng từ.","hedging-modality":"c|The early results ___ to support our theory.|seem / seems / are seem / seem that|0|“Seem + to V” là cấu trúc rào đón và chia theo chủ ngữ. Chủ ngữ “the early results” số nhiều nên dùng “seem”.|seems=>“Results” là danh từ số nhiều nên động từ phải là “seem”, không thêm -s.;;are seem=>“Seem” là động từ thường, không đi sau “are”; không có dạng bị động hay ghép be.;;seem that=>“Seem that” cần một mệnh đề theo sau, còn ở đây phía sau là “to support” nên phải dùng “seem to V”.\nc|Patients with this condition ___ to recover more slowly in winter.|tends / tend / are tend / tending|1|“Tend to V” diễn tả xu hướng chung, không phải quy luật tuyệt đối. Chủ ngữ “patients” số nhiều nên giữ nguyên “tend”.|tends=>Chủ ngữ “patients” số nhiều, nên “tends” có -s là sai hòa hợp.;;are tend=>“Tend” là động từ thường, không đi cùng “be”; người học hay nhầm theo “be likely”.;;tending=>Dạng V-ing đứng một mình không làm động từ chính của câu ở đây.\nc|___ that the new timetable has reduced waiting times.|It would seem to / There would seem / It would seem / They would seem|2|“It would seem that + mệnh đề” là cách nói giảm trang trọng. Dấu hiệu là “that the new timetable has…” theo sau chủ ngữ giả “it”.|It would seem to=>Sau “It would seem” là mệnh đề với that, không nối “to” vì không có động từ nguyên mẫu nào theo sau.;;There would seem=>“There would seem” cần danh từ hoặc “to be” sau đó, không đi với mệnh đề “that…” trong câu này.;;They would seem=>“They” không có nghĩa gì rõ ràng ở đây; cấu trúc rào đón dùng chủ ngữ giả “it”.\nc|The drug may ___ reduce the risk, although more trials are needed.|very / much / quite / well|3|“May well + V” nghĩa là rất có thể, vẫn là cách rào đón. Vế sau “more trials are needed” cho thấy chưa chắc chắn hoàn toàn.|very=>“May very reduce” sai vì “very” không đứng giữa trợ động từ và động từ để tăng khả năng.;;much=>“May much reduce” không tồn tại; “much” cần đi với so sánh hoặc “very much” trước động từ.;;quite=>“May quite reduce” không tự nhiên; “quite” không kết hợp với “may” để tăng khả năng.\nc|The data ___ a link between screen time and poor sleep, though the sample was too small to be certain.|prove / confirm / indicate / guarantee|2|Khi dữ liệu chưa chắc, dùng “indicate/suggest” thay vì “prove”. Cụm “too small to be certain” là manh mối chọn động từ yếu.|prove=>“Prove” là khẳng định chắc chắn, mâu thuẫn với “too small to be certain” ở vế sau.;;confirm=>“Confirm” nghĩa là xác nhận điều đã nghi ngờ, quá mạnh khi mẫu quá nhỏ để chắc chắn.;;guarantee=>“Guarantee” là bảo đảm tuyệt đối và không dùng với dữ liệu nghiên cứu như vậy.\nc|I was wondering ___ you could send me the report by Friday.|that / if / to / for|1|“I was wondering if…” là câu nhờ vả lịch sự, “if” mở đầu mệnh đề gián tiếp. Mệnh đề “you could send…” đã đủ chủ ngữ và động từ.|that=>“That” dùng sau động từ báo cáo chắc chắn, còn lời nhờ vả cần “if” như một câu hỏi gián tiếp.;;to=>“Wondering to you could” sai ngữ pháp; sau “you could” đã có mệnh đề nên không dùng “to”.;;for=>“For” không nối được với mệnh đề “you could send”; cần liên từ “if”.\nc|The surgery is ___ to cause some temporary swelling.|liable / probable / possibly / probably|0|“Be liable/likely + to V” chỉ khả năng xảy ra. “Probable” và các trạng từ không dùng được trong khuôn “is ___ to V”.|probable=>“Probable to cause” sai cấu trúc; “probable” không đi với “to V”, phải nói “it is probable that”.;;possibly=>Trạng từ “possibly” không đứng sau “is” trước “to V”; cấu trúc cần tính từ như “likely/liable”.;;probably=>“Probably” là trạng từ và “is probably to cause” không đúng; phải dùng “is likely to”.\nc|It ___ that the sample size may limit the conclusions.|appears / is appeared / appears to / appearing|0|“It appears that + mệnh đề” là cách nói thận trọng. Chủ ngữ giả “it” cần động từ chia, và sau đó là mệnh đề với “that”.|is appeared=>“Appear” là động từ nội động, không có dạng bị động “is appeared”.;;appears to=>Sau “to” phải có động từ nguyên mẫu, nhưng ở đây liền sau là “that the sample…”.;;appearing=>“Appearing” không phải động từ chia sau chủ ngữ giả “it” trong câu này.\nx|Chọn câu đúng|It would seem to that the programme works. / It would seem that the programme works. / It would seems that the programme works. / It would seem the programme to work.|1|Sau “It would seem” dùng “that + mệnh đề” và động từ would giữ nguyên dạng gốc “seem”, không thêm “to” hay -s.|It would seem to that the programme works.=>Không thể đặt “to” ngay trước “that”; “seem to” chỉ đi với động từ nguyên mẫu.;;It would seems that the programme works.=>Sau trợ động từ would, động từ chính phải ở dạng gốc nên không thêm -s vào “seem”.;;It would seem the programme to work.=>Chủ ngữ giả “it” không đi với cấu trúc object + to V sau “seem”; phải dùng mệnh đề với that.\nx|Chọn câu đúng (seem)|Young drivers tend to take more risks. / Young drivers are tending take more risks. / Young drivers tends to take more risks. / Young drivers tend taking more risks.|0|“Tend” là động từ thường đi với “to V” và chia số nhiều theo chủ ngữ “young drivers”, nên “tend to take” là đúng.|Young drivers are tending take more risks.=>“Tend” ít dùng ở tiếp diễn và thiếu “to” trước “take”, nên cả cấu trúc đều sai.;;Young drivers tends to take more risks.=>Chủ ngữ “young drivers” số nhiều nên “tends” có -s là sai hòa hợp.;;Young drivers tend taking more risks.=>Sau “tend” phải là “to V”, không phải V-ing, nên “taking” không đúng.\nt|The new method ___ (appear) to reduce errors in the lab.|appears|Chủ ngữ “the new method” số ít ở hiện tại đơn nên “appear” thêm -s thành “appears”.\nt|Older adults ___ (tend) to sleep less deeply than teenagers.|tend|Chủ ngữ “older adults” là số nhiều ở hiện tại đơn nên giữ “tend”, không thêm -s.\nc|I'm ___ worried about the result, to be honest.|a bit / sort / kind / a little of|0|“A bit + tính từ” làm nhẹ mức độ cảm xúc trong lời nói. “Worried” là tính từ nên không dùng “a little of” trước nó.|sort=>“Sort” phải đi với “of” (sort of worried); đứng một mình trước tính từ là sai.;;kind=>“Kind” cần có “of” (kind of worried); thiếu “of” nên không tự nhiên.;;a little of=>“A little of” đi với danh từ, không đứng trước tính từ “worried”.\nc|The treatment works in ___ cases, but not for everyone.|the most / mostly / almost / most|3|“In most cases” là cụm rào đón nghĩa là trong phần lớn trường hợp. Vế “but not for everyone” xác nhận có ngoại lệ.|the most=>“In the most cases” sai vì “most” nghĩa là phần lớn không cần mạo từ “the”.;;mostly=>“Mostly” là trạng từ, không đứng trước danh từ “cases”.;;almost=>“Almost cases” sai vì “almost” không bổ nghĩa trực tiếp cho danh từ.\nc|The company ___ well miss its targets this year.|is / has / may / will|2|“May well + V” nghĩa là rất có thể, dùng trợ động từ khuyết thiếu. “Well” chỉ đi cùng may/might/could trong khuôn này.|is=>“Is well miss” sai vì sau “is” không đi với động từ nguyên mẫu trần.;;has=>“Has well miss” sai vì “has” cần quá khứ phân từ, không phải “miss”.;;will=>“Will well miss” không phải cách nói rào đón; khuôn cố định là “may well”.\nc|The study ___ that stress might affect immunity, but it does not prove it.|proves / suggests / establishes / demonstrates|1|Dùng “suggest” khi bằng chứng chỉ gợi ý. Cụm “might affect” và “does not prove it” cho thấy kết luận chưa chắc.|proves=>“Proves” mâu thuẫn trực tiếp với “does not prove it” ở vế sau.;;establishes=>“Establishes” là khẳng định chắc chắn, trái với “might” và “does not prove”.;;demonstrates=>“Demonstrates” nghĩa là chứng minh rõ ràng, trái với ý chưa chứng minh được.\nc|The two groups differ ___, but not dramatically.|at some extent / in some extents / to some extent / to some extents|2|“To some extent” nghĩa là ở một mức độ nào đó và dùng số ít. “But not dramatically” cho thấy sự khác biệt có giới hạn.|at some extent=>Giới từ sai: cụm cố định là “to some extent”, không dùng “at”.;;in some extents=>“Extent” không đếm được ở nghĩa này, và giới từ “in” không đúng.;;to some extents=>“Extent” không thêm -s trong cụm cố định “to some extent”.\nc|I was ___ that we might start a little earlier tomorrow.|think / thought / thinks / thinking|3|“I was thinking (that)…” là cách đề xuất mềm mại, dùng quá khứ tiếp diễn. Thì quá khứ này làm lời gợi ý bớt thẳng.|think=>Sau “was” cần V-ing để tạo thì quá khứ tiếp diễn, không dùng nguyên mẫu “think”.;;thought=>“Was thought” là dạng bị động và đổi nghĩa; câu muốn nói người nói đã nghĩ.;;thinks=>“Was thinks” không đúng; trợ động từ “was” phải đi với dạng V-ing.\nc|This could ___ explain why some patients do not improve.|possibly / possible / be possibly / to possibly|0|“Could possibly + V” làm câu nhẹ và tentative. Trạng từ “possibly” bổ nghĩa cho động từ “explain”, đứng sau “could”.|possible=>“Possible” là tính từ nên không bổ nghĩa trực tiếp cho động từ “explain”.;;be possibly=>“Could be possibly explain” sai vì sau “could be” không đi với động từ nguyên mẫu.;;to possibly=>“Could to possibly” sai vì sau “could” không có “to”.\nx|Chọn câu đúng (suggest)|The figures suggests that prices may rise. / The figures suggest that prices may to rise. / The figures suggest that prices may rises. / The figures suggest that prices may rise slightly.|3|Chủ ngữ số nhiều dùng “suggest”, và sau “may” là động từ nguyên mẫu không “to”, nên chỉ câu cuối đúng.|The figures suggests that prices may rise.=>“Figures” số nhiều nên “suggests” có -s là sai hòa hợp chủ vị.;;The figures suggest that prices may to rise.=>Sau trợ động từ “may” không có “to” trước động từ nguyên mẫu.;;The figures suggest that prices may rises.=>Sau “may” động từ ở dạng gốc, nên “rises” có -s là sai.\nx|Chọn câu đúng (appear)|He appears being unwell today. / He appears that he is unwell today. / He appears to be unwell today. / He is appear to be unwell today.|2|“Appear + to V” dùng với chủ ngữ thật, còn “that + mệnh đề” chỉ đi với chủ ngữ giả “it”.|He appears being unwell today.=>Sau “appear” không dùng V-ing; cấu trúc đúng là “appear to be”.;;He appears that he is unwell today.=>“That + mệnh đề” chỉ đi với “It appears that”, không đi với chủ ngữ “he”.;;He is appear to be unwell today.=>“Appear” là động từ thường, không ghép với “is” như tính từ.\nt|It ___ (seem) that the clinic has changed its opening hours.|seems;would seem|Chủ ngữ giả “it” ở hiện tại đơn là ngôi thứ ba số ít nên dùng “seems”, hoặc “would seem” để nói giảm.\nt|She was ___ (wonder) whether the appointment could be moved.|wondering|Sau “was” dùng V-ing để tạo quá khứ tiếp diễn, đây là cách hỏi lịch sự và tentative.\nf|The findings suggests that the method may be reliable.|suggests|suggest|Chủ ngữ “the findings” số nhiều nên động từ “suggest” không thêm -s.\nf|The new drug is likely reducing the risk of relapse.|reducing|to reduce|“Be likely” đi với “to V”, nên phải là “likely to reduce”, không dùng V-ing.\nf|I was wondering that you could help me with this form.|that|if|Lời nhờ vả “I was wondering” đi với “if” hoặc “whether”, không dùng “that”.\no|It would seem that the results are not conclusive.|Cấu trúc nói giảm: It + would seem + that + mệnh đề, với chủ ngữ giả “it” đứng đầu.\no|By and large, the new approach seems to have worked.|Cụm rào đón “by and large” đứng đầu câu, sau đó là chủ ngữ + seems to have + quá khứ phân từ.","nominalisation":"c|The ___ to close the ward was taken after months of discussion.|decision / decide / decisive / deciding|0|Sau mạo từ “The” và trước “to close” cần danh từ; danh từ của “decide” là “decision”, và “was taken” đi với “decision”.|decide=>“Decide” là động từ, mà sau “The” cần một danh từ làm chủ ngữ.;;decisive=>“Decisive” là tính từ nghĩa là quyết đoán, không đứng một mình sau “the” trước “to close”.;;deciding=>Dạng -ing có thể làm danh động từ nhưng không đi với “the ... to close the ward” trong câu này.\nc|Doctors were concerned about the ___ of antibiotics in farming.|overusing / overuse / overused / overuses|1|Sau “the” và trước “of antibiotics” cần danh từ; “overuse” vừa là danh từ không đếm được, vừa hợp với giới từ “of”.|overusing=>Dạng động từ -ing không hợp sau “the ... of” khi cần danh từ chỉ hiện tượng.;;overused=>Dạng quá khứ phân từ là tính từ, không làm danh từ sau “the”.;;overuses=>Dạng ngôi thứ ba của động từ, không đứng sau “the” làm danh từ ở đây.\nc|There has been a sharp ___ in the number of road accidents.|declining / declined / decline / decrease of|2|Sau “a sharp” cần danh từ đếm được số ít; “a decline in the number of” là mẫu chuẩn chỉ sự giảm.|declining=>Dạng -ing là tính từ hay phân từ, không đi với “a sharp ... in the number” như danh từ.;;declined=>Đây là động từ quá khứ; sau “a sharp” cần danh từ đếm được.;;decrease of=>Thừa giới từ “of” và sai giới từ vì mẫu chuẩn là “a decline in”, nên không ghép được với “in” phía sau.\nc|The company's ___ to deliver on time cost it several contracts.|fail / failed / failing to / failure|3|Sau sở hữu cách “company's” cần danh từ; “failure to + V” là mẫu cố định, và “failure” là danh từ của “fail”.|fail=>“Fail” là động từ nguyên mẫu, không đứng sau sở hữu cách làm chủ ngữ.;;failed=>Dạng quá khứ của động từ, không làm danh từ sau “company's”.;;failing to=>Thừa “to” và cấu trúc bị trùng với “to deliver” đứng sau nó.\nc|___ of sleep over several weeks can seriously affect memory.|Lack / Lacking / Lacked / Lacks|0|Chủ ngữ cần danh từ; “lack of + danh từ” nghĩa là thiếu, và “can seriously affect” xác nhận chủ ngữ là một danh từ không đếm được.|Lacking=>Dạng -ing là phân từ, trong khi chủ ngữ cần danh từ đi với “of sleep”.;;Lacked=>Là dạng quá khứ của động từ, không thể bắt đầu câu làm chủ ngữ như thế.;;Lacks=>Là động từ chia ngôi thứ ba; không đủ làm chủ ngữ khi sau nó có “of sleep”.\nc|Because the population grew rapidly, the city needed more schools. → The rapid ___ in population meant that the city needed more schools.|grow / growth / grew / growing|1|Sau tính từ “rapid” cần danh từ; danh từ của “grow” là “growth”, và “growth in population” là mẫu đúng.|grow=>Đây là động từ nguyên mẫu, không đứng sau “The rapid” làm danh từ.;;grew=>Dạng quá khứ của động từ, không đi sau tính từ “rapid”.;;growing=>Có thể làm tính từ nhưng sau “The rapid” và trước “in population” cần danh từ chính.\nc|The ___ between the two treatments was small but significant.|different / differently / difference / differ|2|Sau “The” cần danh từ; danh từ của tính từ “different” là “difference”, và “between ... and” đi với “difference”.|different=>Là tính từ, không thể là chủ ngữ sau “The” trước “between”.;;differently=>Là trạng từ, không đứng sau “The” làm danh từ.;;differ=>Là động từ nguyên mẫu, không đi với “The ... between” như danh từ.\nx|Chọn câu đúng|The introduction of free screening has improved early diagnosis. / The introduce of free screening has improved early diagnosis. / The introducing free screening has improved early diagnosis. / The introduction free screening has improved early diagnosis.|0|Danh từ “introduction” cần giới từ “of” để nối với đối tượng; “The introduction of ...” là mẫu danh từ hoá chuẩn.|The introduce of free screening has improved early diagnosis.=>Dùng động từ “introduce” sau “The”; cần danh từ “introduction”.;;The introducing free screening has improved early diagnosis.=>Cấu trúc “The introducing” không tự nhiên và thiếu “of”; cần danh từ “introduction of”.;;The introduction free screening has improved early diagnosis.=>Thiếu giới từ “of” giữa danh từ “introduction” và cụm danh từ phía sau.\nx|Chọn câu đúng|Due to prices rose, many flights were cancelled. / Due to the rise in fuel prices, many flights were cancelled. / Due to the rise at fuel prices, many flights were cancelled. / Due to the rising in fuel prices, many flights were cancelled.|1|“Due to” cần cụm danh từ; “the rise in fuel prices” là mẫu chuẩn thay cho mệnh đề “because fuel prices rose”.|Due to prices rose, many flights were cancelled.=>“Due to” là giới từ, phải đi với cụm danh từ chứ không phải mệnh đề “prices rose”.;;Due to the rise at fuel prices, many flights were cancelled.=>Giới từ đi sau “rise” khi nói về giá cả là “in”, không phải “at”.;;Due to the rising in fuel prices, many flights were cancelled.=>“Rising” là dạng -ing, không dùng trước “in” theo mẫu danh từ; cần danh từ “rise”.\nt|Many experts have criticised the ___ (fail) of the scheme.|failure|Sau “the” cần danh từ; danh từ của “fail” là “failure”, đi với “of the scheme”.\nt|She was impressed by the ___ (able) of the nurses to stay calm.|ability|Danh từ của tính từ “able” là “ability”; sau “the” cần danh từ đi với “of the nurses”.\nf|Lack in funding forced the clinic to close last spring.|in|of|Danh từ “lack” đi với giới từ “of”: “lack of funding”, không dùng “in”.\nc|A growing ___ of young adults are choosing to rent rather than buy.|amount / quantity / deal / number|3|“A growing number of + danh từ đếm được số nhiều” là mẫu chuẩn; “young adults” đếm được nên cần “number”.|amount=>“Amount” đi với danh từ không đếm được, trong khi “young adults” là danh từ đếm được số nhiều.;;quantity=>“Quantity” trang trọng nhưng không đi với “a growing ... of” cho người đếm được.;;deal=>“A great deal of” đi với danh từ không đếm được, và không kết hợp với “growing” như vậy.\nc|The ___ of the new software has reduced waiting times at reception.|installation / install / installed / installing|0|Chủ ngữ “The ... of the new software” cần danh từ; “installation” là danh từ của “install”, và “has reduced” chia theo chủ ngữ số ít.|install=>Động từ nguyên mẫu, không đứng sau “The” làm chủ ngữ.;;installed=>Là dạng quá khứ phân từ, không làm danh từ sau “The” và trước “of”.;;installing=>Dạng -ing không đi với “The ... of the new software” theo mẫu danh từ hoá.\nc|There is a clear ___ for more training in palliative care.|needing / need / needs / needed|1|Mạo từ “a clear” cần danh từ số ít; “a need for + danh từ” là mẫu cố định nghĩa là nhu cầu về điều gì.|needing=>Dạng -ing không đi với “a clear ... for” làm danh từ trong câu này.;;needs=>Sau “a clear” cần danh từ số ít, nhưng “needs” là số nhiều nên không hợp với mạo từ “a”.;;needed=>Là quá khứ phân từ, không thể làm danh từ sau “a clear”.\nc|The council's ___ of the old library angered local residents.|demolish / demolished / demolition / demolishing the|2|Sau sở hữu cách “council's” và trước “of” cần danh từ; “demolition” là danh từ của “demolish”.|demolish=>“Demolish” là động từ nguyên mẫu, không đứng sau sở hữu cách làm danh từ.;;demolished=>Là dạng quá khứ của động từ, không phải danh từ sau “council's”.;;demolishing the=>Dạng -ing cộng “the” tạo ra cấu trúc thừa vì “of the old library” theo sau.\nc|Seeing that the experiment was unreliable, the team questioned its ___.|valid / validly / validate / validity|3|Sau từ sở hữu “its” cần danh từ; danh từ của “valid” là “validity”, và ngữ cảnh “unreliable” khớp với việc nghi ngờ độ tin cậy.|valid=>“Valid” là tính từ, sau “its” cần danh từ.;;validly=>“Validly” là trạng từ, không đứng sau từ sở hữu “its”.;;validate=>“Validate” là động từ, không làm tân ngữ sau “questioned its”.\nc|Nobody expected the ___ of the bridge to take so long.|complete / completely / completing / completion|3|Mẫu “the + danh từ + of the bridge” cần danh từ; “completion” là danh từ của “complete”, đi với “to take so long”.|complete=>Tính từ hoặc động từ nguyên mẫu, không đứng sau “the” làm danh từ ở đây.;;completely=>Là trạng từ, không thể làm chủ ngữ sau “the”.;;completing=>Dạng -ing cộng “the ... of” không tự nhiên; cần danh từ “completion”.\nc|Heavy rain caused the ___ of several villages.|flooding / flood of / flooded / floods|0|“The flooding of several villages” là danh từ chỉ hành động bị ngập; sau “the” cần danh từ, và có “caused” ở trước.|flood of=>“Flood of” thừa “of”, vì “of several villages” đã có sẵn sau chỗ trống.;;flooded=>Dạng quá khứ của động từ, không đứng sau “the” làm danh từ.;;floods=>Số nhiều “floods” không đi với “the ... of several villages” theo nghĩa việc bị ngập.\nx|Chọn câu đúng|The lack of qualified teachers is a serious problem in rural areas. / The lack qualified teachers is a serious problem in rural areas. / The lacking of qualified teachers is a serious problem in rural areas. / The lack of qualified teachers are a serious problem in rural areas.|0|“The lack of + danh từ” là chủ ngữ số ít nên đi với “is”; câu đúng đủ cả “of” lẫn động từ chia số ít.|The lack qualified teachers is a serious problem in rural areas.=>Thiếu giới từ “of” giữa danh từ “lack” và cụm danh từ “qualified teachers”.;;The lacking of qualified teachers is a serious problem in rural areas.=>“Lacking” là phân từ, không dùng làm danh từ; cần danh từ “lack”.;;The lack of qualified teachers are a serious problem in rural areas.=>Chủ ngữ chính là “lack” số ít nên động từ phải là “is”, không phải “are”.\nx|Chọn câu đúng|Failure comply with safety rules may result in dismissal. / Failure to comply with safety rules may result in dismissal. / Fail to comply with safety rules may result in dismissal. / The failed to comply with safety rules may result in dismissal.|1|“Failure to + V” là mẫu danh từ hoá chuẩn làm chủ ngữ; danh từ “failure” khác động từ “fail”.|Failure comply with safety rules may result in dismissal.=>Thiếu “to” sau danh từ “failure”; mẫu cố định là “failure to + động từ nguyên mẫu”.;;Fail to comply with safety rules may result in dismissal.=>Dùng nguyên mẫu “Fail” làm chủ ngữ là sai; cần danh từ “failure”.;;The failed to comply with safety rules may result in dismissal.=>“Failed” là quá khứ của động từ, không đi sau “The” làm danh từ.\nt|The ___ (arrive) of the ambulance reassured the family.|arrival|Sau “The” cần danh từ; danh từ của “arrive” là “arrival”, đi với “of the ambulance”.\nt|Students noticed a sharp ___ (increase) in tuition fees last year. (Dạng danh từ)|increase|Sau “a sharp” cần danh từ số ít; “increase” vừa là động từ vừa là danh từ, đi với “in tuition fees”.\nf|The explain of the results took the professor almost an hour.|explain|explanation|Sau “The” cần danh từ; danh từ của “explain” là “explanation”.\nf|There was a growing concern among parents about the safe of the playground.|safe|safety|Sau “the” cần danh từ; danh từ của tính từ “safe” là “safety”.\no|The rise in unemployment has led to a fall in spending.|Mẫu danh từ hoá: the + danh từ + in + danh từ, rồi “has led to” và “a fall in ...”.","past-perfect-continuous":"c|When I met Lan, she was exhausted because she ___ for twelve hours.|had been working / has been working / worked / is working|0|Quá trình kéo dài (for twelve hours) là nguyên nhân của trạng thái ở một mốc quá khứ nên dùng had been working.|has been working=>Mốc “when I met Lan” nằm trong quá khứ nên không thể dùng thì hiện tại hoàn thành tiếp diễn.;;worked=>Quá khứ đơn không nối được quá trình kéo dài với trạng thái kiệt sức lúc gặp; thiếu quan hệ nguyên nhân.;;is working=>Thì hiện tại không hợp với cả câu kể ở quá khứ (was exhausted, met).\nc|By the time the ambulance arrived, the patient ___ on the floor for nearly an hour.|has been lying / had been lying / lay / was lying|1|By the time + quá khứ đơn cùng for + khoảng thời gian báo hiệu quá trình kéo dài trước mốc đó: had been lying.|has been lying=>“By the time … arrived” là mốc quá khứ nên hiện tại hoàn thành tiếp diễn không phù hợp.;;lay=>Quá khứ đơn không đi với “for nearly an hour” để chỉ quá trình kéo dài trước một mốc khác.;;was lying=>Quá khứ tiếp diễn không dùng với “for nearly an hour” khi nhấn khoảng thời gian trước mốc kia.\nc|How long ___ before the lecture began?|have the students been waiting / were the students waiting / had the students been waiting / are the students waiting|2|How long + had + S + been + V-ing hỏi thời lượng diễn ra trước một mốc quá khứ, ở đây là lúc bài giảng bắt đầu.|have the students been waiting=>Mốc “the lecture began” ở quá khứ nên không dùng have been waiting.;;were the students waiting=>Quá khứ tiếp diễn không hỏi được khoảng thời gian chờ tính đến trước mốc quá khứ.;;are the students waiting=>Thì hiện tại mâu thuẫn với “began” ở quá khứ trong cùng câu.\nc|He ___ in the lab since eight o'clock when the fire alarm sounded.|has worked / was working / worked / had been working|3|Since + mốc và when + quá khứ đơn cần had been working để nói về quá trình kéo dài trước lúc chuông reo.|has worked=>Hiện tại hoàn thành không hợp với mốc quá khứ “sounded” trong mệnh đề when.;;was working=>Quá khứ tiếp diễn không đi với “since eight o'clock”; since cần thì hoàn thành.;;worked=>Quá khứ đơn không diễn đạt quá trình kéo dài từ mốc “since eight” đến lúc báo động.\nc|By then, she ___ the family for ten years, so she knew every habit.|had been knowing / had known / has known / was knowing|1|Động từ trạng thái như know dùng quá khứ hoàn thành đơn: had known, nhất là khi có for ten years và mốc by then.|had been knowing=>“know” là động từ chỉ trạng thái, không chia ở dạng tiếp diễn kể cả had been.;;has known=>Mốc “by then” và “knew” ở quá khứ nên hiện tại hoàn thành không hợp.;;was knowing=>Động từ trạng thái không dùng tiếp diễn, và quá khứ tiếp diễn không đi với “for ten years”.\nc|She ___ the whole report by Friday, so she finally took a day off.|had been writing / was writing / had written / has written|2|“The whole report” nhấn kết quả hoàn tất trước một mốc quá khứ, nên dùng quá khứ hoàn thành đơn had written.|had been writing=>Dạng tiếp diễn nhấn quá trình, trong khi “the whole report” cho biết việc đã hoàn tất.;;was writing=>Quá khứ tiếp diễn không cho thấy báo cáo đã xong trước khi cô nghỉ.;;has written=>Mốc “by Friday” đã qua nên hiện tại hoàn thành không phù hợp.\nc|My hands were covered in flour; I ___ bread all morning.|had been baking / have been baking / had been baked / am baking|0|Bột dính trên tay là kết quả nhìn thấy, còn all morning cho thấy quá trình kéo dài trước đó: had been baking.|have been baking=>Câu kể ở quá khứ (were covered) nên hiện tại hoàn thành tiếp diễn lệch thì.;;had been baked=>Dạng bị động sai nghĩa vì chủ ngữ I là người nướng, không phải bị nướng.;;am baking=>Thì hiện tại không khớp với câu kể ở quá khứ và cụm all morning.\nc|The roads were icy because it ___ below zero for three days.|had been staying / has been staying / stayed / had stay|0|Nguyên nhân kéo dài (for three days) dẫn đến kết quả ở quá khứ, nên dùng had been staying.|has been staying=>Câu kể ở quá khứ (were icy) nên không dùng hiện tại hoàn thành tiếp diễn.;;stayed=>Quá khứ đơn chỉ nêu sự việc, không nhấn quá trình ba ngày kéo dài đến lúc đường đóng băng.;;had stay=>Sau had cần quá khứ phân từ hoặc been + V-ing; “had stay” sai hình thức động từ.\nx|Chọn câu đúng|When the inspector arrived, the staff has been cleaning the ward for two hours. / When the inspector arrived, the staff had been cleaning the ward since two hours. / When the inspector arrived, the staff had been cleaning the ward for two hours. / When the inspector arrived, the staff had been clean the ward for two hours.|2|Mốc quá khứ cần had been + V-ing, và for đi với khoảng thời gian two hours.|When the inspector arrived, the staff has been cleaning the ward for two hours.=>“has been” là thì hiện tại, không hợp với mệnh đề when ở quá khứ.;;When the inspector arrived, the staff had been cleaning the ward since two hours.=>“since” phải đi với mốc thời gian, còn two hours là khoảng thời gian nên cần for.;;When the inspector arrived, the staff had been clean the ward for two hours.=>Sau had been phải là V-ing (cleaning), không phải động từ nguyên mẫu “clean”.\nx|Chọn câu đúng|She had been owning the flat for years before she sold it. / She had owned the flat for years before she sold it. / She has owned the flat for years before she sold it. / She had been own the flat for years before she sold it.|1|Own là động từ chỉ trạng thái nên dùng quá khứ hoàn thành đơn, không dùng had been owning.|She had been owning the flat for years before she sold it.=>“own” là động từ trạng thái nên không chia ở dạng tiếp diễn ngay cả với had been.;;She has owned the flat for years before she sold it.=>“has owned” là hiện tại hoàn thành, mâu thuẫn với “before she sold it” ở quá khứ.;;She had been own the flat for years before she sold it.=>Sau been cần V-ing nhưng “own” không dùng tiếp diễn, nên cấu trúc này sai hình thức.\nt|They ___ (argue) for an hour before the manager stepped in.|had been arguing|Hành động kéo dài (for an hour) diễn ra trước mốc quá khứ nên dùng had been + V-ing.\nt|Why was she so out of breath? She ___ (run) up the stairs.|had been running|Hành động vừa diễn ra liên tục là nguyên nhân của trạng thái lúc đó nên dùng had been running.\nf|I had been waiting for the results since three weeks when the email finally arrived.|since|for|Since đi với mốc thời gian, còn three weeks là khoảng thời gian nên phải dùng for.\nc|While Mai ___ dinner, her brother arrived with a surprise.|cooks / has cooked / had been cooking / was cooking|3|While nêu hành động nền đang diễn ra thì sự kiện chính (arrived) xen vào nên dùng quá khứ tiếp diễn was cooking.|cooks=>Thì hiện tại không hợp với câu kể ở quá khứ (arrived).;;has cooked=>Hiện tại hoàn thành không dùng được cho bối cảnh quá khứ của câu kể.;;had been cooking=>Had been cooking đặt hành động lùi về trước mốc, trong khi While nói hai việc song song.\nc|He stood up, ___ his coat and left the room.|grabbed / had been grabbing / has grabbed / would be grabbing|0|Chuỗi hành động nối tiếp trong truyện dùng quá khứ đơn song song: stood up, grabbed, left.|had been grabbing=>Dạng này nhấn quá trình lùi về trước, không hợp với chuỗi hành động nối tiếp.;;has grabbed=>Hiện tại hoàn thành lệch thì so với stood up và left ở quá khứ.;;would be grabbing=>Dạng tương lai trong quá khứ không dùng để kể chuỗi hành động liên tiếp.\nc|By midnight, the volunteers ___ over two hundred meals.|had been serving / had served / were serving / have served|1|Có số lượng two hundred meals và mốc by midnight, nên dùng quá khứ hoàn thành đơn để nhấn kết quả.|had been serving=>Số lượng cụ thể (two hundred meals) nhấn kết quả nên dùng quá khứ hoàn thành đơn.;;were serving=>Quá khứ tiếp diễn không nói được việc đã hoàn tất số bữa ăn trước nửa đêm.;;have served=>Mốc by midnight là quá khứ nên hiện tại hoàn thành không phù hợp.\nc|Her voice was hoarse. She ___ since early morning.|has been shouting / shouted / had been shouting / was shouted|2|Giọng khản là kết quả của quá trình kéo dài (since early morning) trước đó, nên dùng had been shouting.|has been shouting=>Câu mô tả ở quá khứ (was hoarse) nên hiện tại hoàn thành tiếp diễn lệch thì.;;shouted=>Quá khứ đơn không đi với since early morning để chỉ quá trình kéo dài.;;was shouted=>Dạng bị động sai nghĩa vì chủ ngữ She là người hét.\nc|She ___ English for two years before she moved to Dublin.|would study / studies / has been studying / had been studying|3|For two years đi cùng mốc quá khứ moved to Dublin, nên dùng had been studying cho quá trình trước đó.|would study=>Would study chỉ thói quen hoặc tương lai trong quá khứ, không nêu khoảng thời gian trước mốc.;;studies=>Thì hiện tại không hợp với câu kể ở quá khứ (moved).;;has been studying=>Hiện tại hoàn thành tiếp diễn không dùng được khi có mốc quá khứ before she moved.\nc|When I arrived at the stadium, the match ___ for twenty minutes.|has been going on / had been going on / would go on / goes on|1|For twenty minutes tính đến lúc tôi đến (mốc quá khứ) nên dùng had been going on.|has been going on=>Mốc “when I arrived” là quá khứ nên hiện tại hoàn thành tiếp diễn không hợp.;;would go on=>Would go on không nói được khoảng thời gian đã diễn ra trước lúc đến.;;goes on=>Thì hiện tại mâu thuẫn với mệnh đề when ở quá khứ.\nx|Chọn câu đúng|By the time she retired, she had been teaching for thirty years. / By the time she retired, she has been teaching for thirty years. / By the time she retired, she had been teach for thirty years. / By the time she retired, she had been taught for thirty years.|0|By the time + quá khứ đơn cần had been + V-ing để nói về quá trình ba mươi năm trước đó.|By the time she retired, she has been teaching for thirty years.=>“has been” là hiện tại, mâu thuẫn với mốc “retired” ở quá khứ.;;By the time she retired, she had been teach for thirty years.=>Sau had been phải là V-ing (teaching), không dùng động từ nguyên mẫu.;;By the time she retired, she had been taught for thirty years.=>“had been taught” là bị động, nghĩa thành cô ấy được dạy, sai với ý cô ấy dạy học.\nx|Chọn câu đúng|How long have you been waiting when the doctor called you in? / How long you had been waiting when the doctor called you in? / How long had you waiting when the doctor called you in? / How long had you been waiting when the doctor called you in?|3|Câu hỏi thời lượng trước mốc quá khứ dùng How long + had + S + been + V-ing.|How long have you been waiting when the doctor called you in?=>Have been không hợp với mệnh đề when ở quá khứ (called).;;How long you had been waiting when the doctor called you in?=>Câu hỏi phải đảo trợ động từ lên trước chủ ngữ: had you been, không phải you had been.;;How long had you waiting when the doctor called you in?=>Thiếu been; cấu trúc đầy đủ là had you been waiting.\nt|By the time I got home, it ___ (snow) for hours.|had been snowing|Quá trình kéo dài (for hours) trước mốc got home nên dùng had been snowing.\nt|I ___ (not / sleep) well, so I felt terrible at the interview.|hadn't been sleeping;had not been sleeping|Nguyên nhân kéo dài trước mốc quá khứ ở dạng phủ định là hadn't been sleeping.\nf|She was exhausted because she had been run since six o'clock.|run|running|Sau had been phải dùng V-ing nên run đổi thành running.\nf|The students had be revising all night, so they looked tired.|be|been|Cấu trúc đúng là had been + V-ing; be thiếu hình thức phân từ been.\no|They had been talking for an hour before the bus arrived.|Trật tự: chủ ngữ, had been + V-ing, for + khoảng thời gian, rồi before + mốc quá khứ đơn.","reporting-verbs":"c|The surgeon denied ___ the wrong form to the patient.|giving / to give / give / that give|0|“deny” đi với V-ing để phủ nhận một việc đã làm; dấu hiệu là hành động “giving the wrong form” đã xảy ra trong quá khứ.|to give=>“deny” không đi với to V; nó đi với V-ing khi nói về việc đã xảy ra như ở câu này.;;give=>Sau “deny” cần dạng V-ing hoặc mệnh đề that, không dùng động từ nguyên mẫu trần.;;that give=>“that” phải có một mệnh đề đầy đủ có chủ ngữ, còn “give” chỉ là động từ đơn lẻ.\nc|The tenant refused ___ the rent until the heating was repaired.|paying / to pay / to paying / that pay|1|“refuse + to V” diễn tả sự từ chối làm điều gì; trong câu, người thuê nhà từ chối trả tiền thuê nên cần “to pay”.|paying=>“refuse” thuộc nhóm đi với to V, nên V-ing ở đây làm sai cấu trúc của động từ.;;to paying=>Sau “to” trong cấu trúc này phải là động từ nguyên mẫu, không phải dạng V-ing.;;that pay=>“refuse that” không tự nhiên khi có cùng chủ ngữ; câu cần một động từ nguyên mẫu có to.\nc|The coach advised the players ___ too much before the final.|not eating / don't eat / not to eat / to not eating|2|“advise + O + (not) to V”; tân ngữ “the players” đã có sẵn nên chỗ trống phải là “not to eat”.|not eating=>“advise” cần tân ngữ rồi đến to V; dạng V-ing phủ định không đi với “the players” ở đây.;;don't eat=>Câu tường thuật không giữ nguyên dạng mệnh lệnh phủ định “don't”; phải dùng “not to V”.;;to not eating=>Sau “to” phải là động từ nguyên mẫu, và “eating” làm cấu trúc bị sai hoàn toàn.\nc|Her colleagues congratulated her ___ the research grant.|for winning / of winning / to win / on winning|3|Mẫu cố định là “congratulate O on + V-ing”; sau “her” cần giới từ “on” chứ không phải for hay of.|for winning=>“congratulate” đi với giới từ “on”, không dùng “for” để chúc mừng ai về điều gì.;;of winning=>“of” dùng với accuse, không dùng với congratulate; câu này cần giới từ khác.;;to win=>Sau “congratulate O” cần giới từ cộng V-ing, không dùng trực tiếp to V.\nc|The lecturer ___ us that the seminar had been moved to Friday.|told / said / explained / suggested|0|Có tân ngữ người nghe “us” ngay sau chỗ trống nên phải dùng “tell”: “told us that…”.|said=>“said” không đứng trực tiếp trước tân ngữ “us”; nó phải là “said to us”.;;explained=>“explained us” sai vì explain cần “to us”, không nhận tân ngữ người trực tiếp.;;suggested=>“suggested us that” sai ngữ pháp và nghĩa gợi ý không hợp với việc báo thay đổi lịch.\nc|The neighbours blamed the builders ___ the cracks in the wall.|of / for / on / with|1|“blame O for + lý do” là mẫu cố định; “the builders” là O và “the cracks” là điều bị đổ lỗi.|of=>“blame O of” không tồn tại; “of” dùng với accuse, còn blame đi với “for”.;;on=>“blame … on” cần đảo thành “blame the cracks on the builders”, không đúng với thứ tự trong câu này.;;with=>“with” không đi với blame và không diễn tả nguyên nhân bị đổ lỗi.\nc|The consultant ___ that we should postpone the launch until spring.|persuaded / warned / recommended / promised|2|“recommend that + S + (should) V” dùng để đề xuất; nghĩa “nên hoãn” khớp với recommend.|persuaded=>“persuade” cần tân ngữ người, mà sau nó lại không có người nào nên câu bị thiếu.;;warned=>“warn” cần tân ngữ người và không đi với “should postpone” theo cách này.;;promised=>“promise that we should” không hợp nghĩa; lời hứa không dùng “should” để đưa ra lời khuyên.\nc|She apologised ___ the delay in sending the test results.|us for / to us of / us of / to us for|3|Mẫu cố định là “apologise to + người + for + lý do”; câu có cả người nhận và lý do là sự chậm trễ.|us for=>“apologise” cần “to” trước người; không dùng trực tiếp tân ngữ “us”.;;to us of=>Lý do xin lỗi đi với “for”, không đi với “of”.;;us of=>Thiếu “to” trước người và dùng sai giới từ “of” thay vì “for”.\nc|The police officer warned the crowd ___ the barrier.|not to cross / don't cross / not crossing / to not cross|0|“warn + O + not to V” là mẫu chuẩn; “the crowd” là tân ngữ nên chỗ trống là “not to cross”.|don't cross=>Câu tường thuật không dùng mệnh lệnh trực tiếp “don't cross” sau tân ngữ người.;;not crossing=>“warn O” đi với to V, không đi với dạng V-ing phủ định.;;to not cross=>Dạng “to not cross” hiếm và kém chuẩn; cấu trúc chuẩn đặt “not” trước “to”.\nc|The clinic offered ___ a free check-up to everyone over sixty.|giving / to give / us giving / that give|1|“offer + to V” diễn tả lời đề nghị làm giúp; chủ ngữ “the clinic” tự đề nghị nên dùng “to give”.|giving=>“offer” đi với to V, không dùng V-ing để nêu ý định đề nghị.;;us giving=>Không thể chen tân ngữ rồi V-ing sau “offer”; cấu trúc không tồn tại.;;that give=>“offer that” cần một mệnh đề đầy đủ có chủ ngữ riêng, câu này không có.\nc|Her tutor reminded her ___ the form before the deadline.|submitting / that submit / to submit / of submit|2|“remind + O + to V” để nhắc người khác làm gì; “her” là tân ngữ nên chỗ trống là “to submit”.|submitting=>“remind O” đi với to V để nhắc việc cần làm, không đi với V-ing.;;that submit=>Sau “that” cần mệnh đề có chủ ngữ và động từ chia, “submit” đứng một mình là sai.;;of submit=>Sau giới từ “of” phải là danh từ hoặc V-ing, không thể là động từ nguyên mẫu.\nc|They accused the minister ___ public money on private trips.|for spending / to spend / with spending / of spending|3|“accuse O of + V-ing”; tân ngữ “the minister” rồi đến giới từ “of” và hành vi bị buộc tội.|for spending=>“accuse” không đi với “for”; giới từ cố định của nó là “of”.;;to spend=>“accuse O to V” không tồn tại trong tiếng Anh chuẩn.;;with spending=>“with” không dùng sau accuse để nêu hành vi bị buộc tội.\nx|Chọn câu đúng (suggest)|The dentist suggested me to use a softer toothbrush. / The dentist suggested that I should use a softer toothbrush. / The dentist suggested to use a softer toothbrush. / The dentist suggested me using a softer toothbrush.|1|Suggest đi với V-ing hoặc that-clause; chỉ câu dùng “that I should use” tuân theo quy tắc đó.|The dentist suggested me to use a softer toothbrush.=>“suggest” không nhận cấu trúc “O + to V”, nên “me to use” làm câu sai.;;The dentist suggested to use a softer toothbrush.=>“suggest” không đi với to V; cần V-ing hoặc mệnh đề that.;;The dentist suggested me using a softer toothbrush.=>Không thể đặt tân ngữ “me” trực tiếp sau suggest rồi thêm V-ing.\nx|Chọn câu đúng (say/tell)|She said the receptionist that she had a ten o'clock appointment. / She told that she had a ten o'clock appointment. / She told the receptionist that she had a ten o'clock appointment. / She explained the receptionist that she had a ten o'clock appointment.|2|“tell” bắt buộc có người nghe theo sau; chỉ câu có “told the receptionist that” đáp ứng điều đó.|She said the receptionist that she had a ten o'clock appointment.=>“said” không đứng trực tiếp trước tân ngữ “the receptionist”.;;She told that she had a ten o'clock appointment.=>“tell” thiếu tân ngữ người nghe nên câu không hoàn chỉnh.;;She explained the receptionist that she had a ten o'clock appointment.=>“explain” cần “to the receptionist”, không nhận tân ngữ người trực tiếp.\nx|Chọn câu đúng (admit)|The students admitted to copy parts of the essay from the internet. / The students admitted that copying parts of the essay from the internet. / The students admitted copy parts of the essay from the internet. / The students admitted copying parts of the essay from the internet.|3|“admit + V-ing” dùng cho hành động đã làm; chỉ câu với “admitted copying” đúng cấu trúc.|The students admitted to copy parts of the essay from the internet.=>“admit” đi với V-ing, nên “to copy” làm sai cấu trúc.;;The students admitted that copying parts of the essay from the internet.=>“that” cần mệnh đề đầy đủ, nhưng “copying parts…” không có chủ ngữ.;;The students admitted copy parts of the essay from the internet.=>Sau admit cần V-ing; động từ nguyên mẫu trần không dùng được.\nx|Chọn câu đúng (persuade)|The nurse persuaded him to stop smoking before the operation. / The nurse persuaded him stopping smoking before the operation. / The nurse persuaded to stop smoking before the operation. / The nurse persuaded that he stop to smoke before the operation.|0|“persuade + O + to V”; chỉ câu có “him to stop” hợp mẫu cấu trúc này.|The nurse persuaded him stopping smoking before the operation.=>“persuade O” đi với to V, không đi với V-ing.;;The nurse persuaded to stop smoking before the operation.=>Thiếu tân ngữ người sau persuade nên câu thiếu thành phần.;;The nurse persuaded that he stop to smoke before the operation.=>Cụm “stop to smoke” đổi nghĩa thành dừng lại để hút thuốc, và cấu trúc cả câu không tự nhiên.\nt|The manager promised ___ (increase) the staff budget next year.|to increase|“promise” đi với to V để nêu lời hứa, nên điền “to increase”.\nt|The driver denied ___ (use) his phone at the time of the accident.|using|“deny” đi với V-ing để phủ nhận việc đã làm, nên điền “using”.\nt|She warned us ___ (not / touch) the equipment without gloves.|not to touch|Sau “warn + O” dùng “not to V” để tường thuật lời cảnh báo phủ định.\nt|They accused the clerk of ___ (lose) the patient files.|losing|Sau giới từ “of” trong mẫu “accuse O of” phải dùng V-ing, nên điền “losing”.\nf|The headteacher apologised us for the confusion over the timetable.|us|to us|“apologise” cần “to + người” rồi mới tới “for”, không có tân ngữ trực tiếp.\nf|My supervisor suggested to rewrite the introduction before submitting.|to|rewriting|“suggest” không đi với to V; dùng “suggested rewriting” hoặc “suggested that I rewrite”.\no|The lab technician reminded us to label every sample.|Mẫu “remind + O + to V”: động từ, tân ngữ chỉ người, rồi to V.\no|She congratulated him on passing the entrance exam.|Mẫu “congratulate + O + on + V-ing”: tân ngữ trước, giới từ on, rồi V-ing."};
  const THEORY = {"adjective-gradability":{"summary":"Tính từ gradable có thể mạnh hay yếu tuỳ mức độ nên đi với “very”, còn tính từ ungradable đã mang nghĩa tuyệt đối nên đi với “absolutely”, và nhiều tính từ đứng trước danh từ phải theo một thứ tự cố định.","formulas":[{"label":"Gradable + từ nhấn mạnh","pattern":"very / extremely / fairly / rather + gradable adjective","ex":"The ward was extremely quiet."},{"label":"Ungradable + từ nhấn mạnh","pattern":"absolutely / completely / totally + ungradable adjective","ex":"The instructions were absolutely impossible to follow."},{"label":"Từ dùng được với cả hai","pattern":"really / pretty + gradable or ungradable adjective","ex":"The exam was really hard, and the last question was really impossible."},{"label":"Thứ tự tính từ","pattern":"opinion + size + age + shape + colour + origin + material + purpose + noun","ex":"a beautiful small old round white Italian marble dining table"},{"label":"Tính từ -ing / -ed","pattern":"-ing: gây ra cảm giác; -ed: người cảm thấy","ex":"The results were surprising, so we were all surprised."}],"uses":[{"title":"Gradable: có mức độ","detail":"Tính từ như cold, tired, good, hard có thể mạnh hay yếu, nên dùng với very, extremely, fairly, rather.","ex":"She was fairly tired, but he was extremely tired.","exvi":"Cô ấy khá mệt, còn anh ấy cực kỳ mệt."},{"title":"Ungradable: nghĩa tuyệt đối","detail":"Tính từ như freezing, exhausted, perfect, impossible đã mạnh sẵn, nên dùng absolutely, completely, totally.","ex":"The view from the summit was absolutely breathtaking.","exvi":"Quang cảnh từ đỉnh núi thật sự ngoạn mục."},{"title":"Quite có hai nghĩa","detail":"Trong Anh-Anh, “quite” thường nghĩa là khá, nhưng với tính từ ungradable nó nghĩa là hoàn toàn.","ex":"The film was quite good, but the ending was quite perfect.","exvi":"Bộ phim khá hay, nhưng cái kết thì hoàn hảo."},{"title":"Thứ tự nhiều tính từ","detail":"Ý kiến đứng trước, rồi đến sự thật khách quan theo thứ tự kích cỡ, tuổi, hình dạng, màu, xuất xứ, chất liệu, mục đích.","ex":"He wore a lovely long grey woollen coat.","exvi":"Anh ấy mặc một chiếc áo khoác len dài màu xám rất đẹp."},{"title":"Boring hay bored","detail":"Tính từ đuôi -ing tả người hoặc vật gây ra cảm giác, đuôi -ed tả người cảm thấy.","ex":"The lesson was tiring, and the students were tired.","exvi":"Bài học rất mệt, và học sinh thì mệt."}],"signals":["very","extremely","fairly","rather","pretty","quite","really","absolutely","completely","totally"],"cautions":["Không dùng “very” với tính từ ungradable: nói “absolutely exhausted”, không nói “very exhausted” (nhưng “very tired” thì đúng).","“Really” và “pretty” dùng được với cả hai loại, ví dụ “really cold” và “really freezing”.","Hai tính từ chỉ ý kiến hoặc cùng loại thường nối bằng “and” hoặc dấu phẩy, còn các loại khác thì không cần: “a big red car”.","Tính từ -ed tả cảm giác của người: “I am bored”, không phải “I am boring” (nghĩa là mình là người nhàm chán)."]},"adverbial-clauses":{"summary":"Mệnh đề trạng ngữ nâng cao giúp bạn nêu mục đích, kết quả, lý do và nhượng bộ một cách chính xác, trang trọng và linh hoạt về vị trí trong câu.","formulas":[{"label":"Mục đích (mệnh đề)","pattern":"so that / in order that + S + can/could/will/would + V","ex":"We keep records so that errors can be traced."},{"label":"Mục đích (rút gọn, tránh)","pattern":"so as (not) to / in order (not) to + V; lest + S + (should) + V; with a view to + V-ing","ex":"He checked the dose twice lest he should make a mistake."},{"label":"Kết quả","pattern":"so + adj/adv + that; such + (a/an) + adj + N + that; to such an extent that","ex":"The queue was so long that many patients gave up."},{"label":"Lý do đã biết","pattern":"seeing that / given that / in view of the fact that / inasmuch as + S + V","ex":"Seeing that the lab is closed, we will resume on Monday."},{"label":"Nhượng bộ và tương phản","pattern":"whereas / while / albeit / much as + clause; however + adj + S + V","ex":"However hard she tried, the sample kept failing."},{"label":"Nhượng bộ vô điều kiện","pattern":"whatever / whoever / whichever / no matter how + clause","ex":"Whoever wins the grant must publish the data."}],"uses":[{"title":"Mục đích trang trọng","detail":"“So that” cần chủ ngữ riêng và động từ khuyết thiếu; “so as to” dùng khi hai mệnh đề cùng chủ ngữ.","ex":"Staff wear badges so that visitors can identify them.","exvi":"Nhân viên đeo thẻ để khách có thể nhận ra họ."},{"title":"Mục đích phủ định","detail":"“Lest” mang nghĩa “vì sợ rằng”, rất trang trọng, theo sau là should hoặc dạng nguyên mẫu.","ex":"She whispered lest the baby wake.","exvi":"Cô ấy thì thầm để em bé khỏi thức giấc."},{"title":"Mức độ dẫn đến kết quả","detail":"Dùng “so/such … that” để chỉ mức độ mạnh đến mức gây ra một kết quả cụ thể.","ex":"It was such a complex case that three specialists were consulted.","exvi":"Ca bệnh phức tạp đến mức phải hỏi ý kiến ba chuyên gia."},{"title":"Nêu lý do mà người nghe đã biết","detail":"“Given that”, “seeing that” giới thiệu lý do là thông tin hiển nhiên hoặc đã được chấp nhận.","ex":"Given that costs have doubled, the plan is no longer viable.","exvi":"Vì chi phí đã tăng gấp đôi, kế hoạch không còn khả thi."},{"title":"Tương phản và nhượng bộ","detail":"“Whereas/while” đối lập hai sự việc; “albeit” và “much as” nhượng bộ nhưng giữ quan điểm chính.","ex":"The treatment is effective, albeit expensive.","exvi":"Phương pháp điều trị hiệu quả, dù đắt đỏ."},{"title":"Nhượng bộ không điều kiện","detail":"“Whatever”, “however + adj”, “no matter how” nói rằng kết quả không đổi dù điều kiện thế nào.","ex":"However busy you are, you must wash your hands.","exvi":"Dù bận đến đâu, bạn cũng phải rửa tay."}],"signals":["so that","in order that","so as to","lest","such … that","given that","seeing that","whereas","albeit","much as"],"cautions":["Không dùng “so that” + V nguyên mẫu: nói “so that she can see”, không nói “so that to see”.","“Albeit” đi với tính từ, cụm từ hoặc trạng từ, không đi với mệnh đề đầy đủ: “albeit slowly”.","Mệnh đề đứng đầu câu cần dấu phẩy; mệnh đề đứng sau thường không cần, trừ “whereas/while” chỉ tương phản.","Không dùng “because” cùng “so/therefore” trong một câu; “as/since/given that” cũng không đi với “but”."]},"articles-advanced":{"summary":"Mạo từ cho biết bạn nói về một cá thể cụ thể hay về cả một loại, và nhiều cụm cố định phải học thuộc.","formulas":[{"label":"Nghĩa chung bằng the + số ít","pattern":"The + singular noun + is/are …","ex":"The giraffe is the tallest animal on land."},{"label":"Nghĩa chung bằng số nhiều/không đếm được","pattern":"Ø + plural / uncountable noun + verb","ex":"Antibiotics do not work against viruses."},{"label":"Nghĩa chung bằng a/an","pattern":"A/An + singular noun + is … (định nghĩa, mô tả điển hình)","ex":"A nurse needs patience and stamina."},{"label":"The + tính từ","pattern":"the + adjective (+ plural verb)","ex":"The unemployed are entitled to training."},{"label":"Địa danh","pattern":"the + river / mountain range / sea / republic / kingdom / plural country","ex":"The Rhine rises in the Alps."},{"label":"Zero article cố định","pattern":"Ø: meals, illnesses, transport (by + N), institutions (in/at + N)","ex":"After lunch she went to bed with flu."}],"uses":[{"title":"Nói về cả một loài","detail":"The + danh từ số ít hoặc danh từ số nhiều không mạo từ đều chỉ cả loài; the + số ít trang trọng hơn.","ex":"The whale is a mammal. / Whales are mammals.","exvi":"Cá voi là động vật có vú."},{"title":"The + tính từ","detail":"Biến tính từ thành nhóm người, luôn dùng động từ số nhiều.","ex":"The rich are not always the happiest.","exvi":"Người giàu không phải lúc nào cũng hạnh phúc nhất."},{"title":"Danh từ trừu tượng, bữa ăn, bệnh","detail":"Không dùng mạo từ khi nói chung, trừ khi có giới hạn cụ thể.","ex":"Justice matters, but the justice of this ruling is disputed.","exvi":"Công lý quan trọng, nhưng tính công bằng của phán quyết này còn bị tranh cãi."},{"title":"Nơi chốn và phương tiện","detail":"Dùng zero khi nói về chức năng chính; dùng the khi nói về toà nhà hay vật cụ thể.","ex":"He is at school, but his mother went to the school to complain.","exvi":"Cậu ấy đang đi học, nhưng mẹ cậu đã đến trường để phàn nàn."},{"title":"Tên địa lý","detail":"Sông, dãy núi, đại dương, nước có Republic/Kingdom hoặc dạng số nhiều dùng the; đỉnh núi và đa số nước thì không.","ex":"The Netherlands borders Germany, and Everest is in the Himalayas.","exvi":"Hà Lan giáp Đức, còn Everest nằm trong dãy Himalaya."},{"title":"Lần nhắc đầu, lần hai, duy nhất, so sánh nhất","detail":"A/an lần đầu, the khi đã xác định, vật duy nhất hoặc sau so sánh nhất.","ex":"I saw a doctor; the doctor said the sun was the cause.","exvi":"Tôi đi khám; bác sĩ nói mặt trời là nguyên nhân."}],"signals":["generally","in general","species","the elderly","the poor","by bus","in hospital","at university","the Alps","the Nile"],"cautions":["Nghĩa chung dùng “the” + số nhiều thường sai: “The tigers are…” chỉ một nhóm cụ thể.","“The + tính từ” không thêm -s: “the elderly”, không phải “the elderlies”.","Nơi chốn: “in hospital” (là bệnh nhân) khác “in the hospital” (ở trong toà nhà).","Một số bệnh có the hoặc a: “the flu”, “a cold”, “a headache”, nhưng “measles”, “diabetes”."]},"comparison-advanced":{"summary":"Ngoài dạng so sánh cơ bản, tiếng Anh còn có các cấu trúc để diễn tả thay đổi song song, thay đổi dần, mức chênh lệch và bội số.","formulas":[{"label":"Thay đổi song song","pattern":"The + comparative + S + V, the + comparative + S + V","ex":"The longer the queue was, the angrier the customers became."},{"label":"Thay đổi dần dần","pattern":"comparative + and + comparative","ex":"Living costs are getting higher and higher."},{"label":"Mức chênh lệch","pattern":"much / far / a great deal / considerably / slightly + comparative","ex":"The second test was slightly easier than the first."},{"label":"Bội số","pattern":"twice / three times / half as + adj + as; half as many + noun + as","ex":"The clinic sees twice as many patients as it did last year."},{"label":"So sánh nhất nhấn mạnh","pattern":"by far / easily / much the + superlative","ex":"She is easily the most experienced nurse on the team."},{"label":"Phủ định nhấn mạnh","pattern":"not nearly as + adj + as; the + comparative of the two; less / fewer","ex":"This route is not nearly as busy as the main road."}],"uses":[{"title":"Hai thay đổi đi cùng nhau","detail":"Cấu trúc “the … the …” cho thấy khi một yếu tố tăng thì yếu tố kia cũng thay đổi theo.","ex":"The harder she studied, the more confident she felt.","exvi":"Cô ấy học càng chăm thì càng tự tin."},{"title":"Thay đổi liên tục","detail":"Lặp lại so sánh hơn với “and” để nói một việc tăng hoặc giảm dần dần.","ex":"The patient was getting weaker and weaker.","exvi":"Bệnh nhân ngày càng yếu đi."},{"title":"Mức chênh lệch lớn hoặc nhỏ","detail":"Dùng much, far, a great deal cho chênh lệch lớn; slightly, a little cho chênh lệch nhỏ.","ex":"Prices are far higher in the city centre.","exvi":"Giá ở trung tâm thành phố cao hơn nhiều."},{"title":"So sánh bội số","detail":"Dùng twice/three times as … as hoặc half as … as để nói tỉ lệ so với vật khác.","ex":"Her salary is three times as high as mine.","exvi":"Lương của cô ấy gấp ba lần lương tôi."},{"title":"Nhấn mạnh so sánh nhất","detail":"By far hoặc easily đứng trước so sánh nhất để nói vượt trội rõ rệt.","ex":"This is by far the best study method I have tried.","exvi":"Đây là phương pháp học tốt nhất mà tôi từng thử, vượt xa các cách khác."}],"signals":["the more … the more","more and more","much","far","slightly","considerably","twice as … as","by far","not nearly as","fewer"],"cautions":["Không dùng “very” trước so sánh hơn: nói “much better”, không nói “very better”.","Hai vế của “the … the …” đều cần “the + so sánh hơn”; không thêm “than” vào cấu trúc này.","“Fewer” dùng với danh từ đếm được số nhiều (fewer errors), “less” dùng với danh từ không đếm được (less time).","Với hai đối tượng, dùng “the + so sánh hơn”: “the taller of the two”, không dùng so sánh nhất."]},"discourse-markers":{"summary":"Discourse markers là từ hoặc cụm từ báo hiệu cách các ý liên kết với nhau (thứ tự, thêm, đối lập, giải thích, kết luận) hoặc thái độ của người nói, và mỗi marker có văn phong và vị trí riêng.","formulas":[{"label":"Sắp xếp ý (signposting)","pattern":"To begin with / Firstly / Secondly / Finally, + clause","ex":"Firstly, the course is too expensive for most students."},{"label":"Thêm ý","pattern":"Moreover / Besides / What is more / On top of that, + clause","ex":"The clinic is close to the station. On top of that, it opens at weekends."},{"label":"Đối lập","pattern":"Clause. + On the other hand / Nevertheless / Even so / That said, + clause","ex":"The job pays well. That said, the hours are very long."},{"label":"Giải thích lại","pattern":"Clause, + in other words / that is to say, + clause","ex":"The ward is understaffed; in other words, nurses are overworked."},{"label":"Kết luận","pattern":"All in all / To sum up / On balance, + clause","ex":"On balance, the benefits outweigh the costs."},{"label":"Marker khi nói (stance)","pattern":"Actually / As a matter of fact / Mind you / To be fair / Frankly / By the way / Anyway, + clause","ex":"To be fair, she had only a week to prepare."}],"uses":[{"title":"Dẫn dắt và sắp xếp bài nói, bài viết","detail":"Dùng to begin with, firstly, finally để người nghe biết đang ở phần nào của lập luận.","ex":"To begin with, let me explain how the survey was designed.","exvi":"Trước hết, để tôi giải thích khảo sát được thiết kế thế nào."},{"title":"Thêm ý hoặc nêu ý đối lập","detail":"Dùng moreover, besides để thêm bằng chứng, và nevertheless, even so, that said để chuyển sang ý ngược lại.","ex":"The treatment is effective. Even so, it is not suitable for everyone.","exvi":"Phương pháp điều trị này hiệu quả. Dù vậy, nó không phù hợp với mọi người."},{"title":"Giải thích lại và kết luận","detail":"Dùng in other words để nói rõ hơn, và all in all, on balance để chốt lại sau khi cân nhắc.","ex":"All in all, the project was a modest success.","exvi":"Nhìn chung, dự án là một thành công khiêm tốn."},{"title":"Thể hiện thái độ khi nói","detail":"Actually, frankly, to be fair, mind you cho biết người nói sửa lại, thẳng thắn hay nhượng bộ.","ex":"Frankly, I think the deadline is unrealistic.","exvi":"Nói thẳng ra, tôi nghĩ hạn chót này không thực tế."},{"title":"Chọn đúng văn phong","detail":"Moreover, nevertheless hợp văn viết; on top of that, mind you, anyway hợp lời nói thân mật.","ex":"Anyway, shall we move on to the next item?","exvi":"Thôi được, ta chuyển sang mục tiếp theo nhé?"}],"signals":["to begin with","moreover","on top of that","on the other hand","nevertheless","that said","in other words","all in all","on balance","mind you"],"cautions":["Marker không phải liên từ: “However” và “Moreover” không nối hai mệnh đề bằng dấu phẩy; dùng dấu chấm hoặc chấm phẩy trước marker, dấu phẩy sau marker.","Đừng dùng marker thêm “but/and”: nói “However, ...” chứ không nói “But however, ...”.","Marker dùng trong nói thân mật (“on top of that”, “mind you”) thường thiếu trang trọng trong bài luận học thuật.","Không dùng quá nhiều marker một lúc; chỉ dùng khi ý thật sự cần được báo hiệu."]},"ellipsis-substitution":{"summary":"Ellipsis là bỏ bớt từ đã rõ nghĩa, còn substitution là thay phần lặp bằng một từ ngắn như one, so, do.","formulas":[{"label":"Thay danh từ đếm được","pattern":"adj + one(s) / the one(s) + phrase","ex":"I prefer the grey jacket to the black one."},{"label":"Thay cụm động từ","pattern":"do / does / did (+ so / it / that)","ex":"She works harder than I do."},{"label":"Thay mệnh đề bằng so/not","pattern":"think / hope / suppose / expect / be afraid + so / not","ex":"Is the clinic open? I'm afraid not."},{"label":"Lược chủ ngữ sau and/or/but","pattern":"S + V1 and/but (S) + V2","ex":"He opened the file and read the report."},{"label":"Lược sau to / trợ động từ","pattern":"would love to / be able to / have (+ nothing)","ex":"Would you like to join us? I'd love to."}],"uses":[{"title":"Tránh lặp danh từ","detail":"Dùng “one/ones” thay danh từ đếm được đã nhắc; không dùng cho danh từ không đếm được.","ex":"This chair is broken; take the one by the window.","exvi":"Cái ghế này hỏng; hãy lấy cái cạnh cửa sổ."},{"title":"Thay cả hành động","detail":"“do so” (trang trọng) hoặc do/does/did thay cho cụm động từ vừa nói.","ex":"Staff may leave early, but few of them do so.","exvi":"Nhân viên có thể về sớm, nhưng ít người làm vậy."},{"title":"Trả lời với so/not","detail":"Sau think, hope, suppose, believe dùng “so” hoặc “not” thay cho cả mệnh đề that.","ex":"Has the shipment arrived? I don't think so.","exvi":"Lô hàng đã đến chưa? Tôi nghĩ là chưa."},{"title":"Lược trong câu ghép","detail":"Khi hai động từ cùng chủ ngữ, chủ ngữ thứ hai và trợ động từ trùng thường được bỏ.","ex":"The team has designed and (has) tested the device.","exvi":"Nhóm đã thiết kế và thử nghiệm thiết bị."},{"title":"Rút gọn khi đáp lời","detail":"Trong hội thoại và chỉ dẫn, bỏ chủ ngữ hoặc trợ động từ khi ngữ cảnh đã rõ.","ex":"Coming to the seminar? Sorry, can't.","exvi":"Bạn đến buổi hội thảo chứ? Tiếc là không thể."}],"signals":["one / ones","do so","I think so","I hope not","I'd love to","the same","and / or / but","as well as"],"cautions":["Không dùng “one” thay danh từ không đếm được: “I like black coffee, not white.” chứ không “white one”.","Chỉ lược khi không gây mơ hồ; nếu có hai chủ thể khác nhau thì phải giữ chủ ngữ.","“I hope so/not”, “I'm afraid so/not” là cụm cố định; với “think” phủ định dùng “I don't think so”.","Văn viết trang trọng ưa “do so”; văn nói thân mật hay dùng “do it/that”."]},"hedging-modality":{"summary":"Hedging là cách dùng động từ, trạng từ và cụm từ để làm nhẹ mức độ chắc chắn của câu, giúp lời nói lịch sự và kết luận khoa học thận trọng hơn.","formulas":[{"label":"Động từ rào + to V","pattern":"S + seem/appear/tend/be likely/be liable + to V","ex":"The symptoms tend to get worse at night."},{"label":"It + would seem/appear + that","pattern":"It + would seem / appear / seems + that + clause","ex":"It would seem that demand is falling."},{"label":"Trợ động từ rào","pattern":"S + may well / might well / could possibly + V","ex":"The trial may well show a modest benefit."},{"label":"Trạng từ và cụm giới hạn","pattern":"mainly / largely / to some extent / by and large / in most cases + clause","ex":"By and large, the new method has been effective."},{"label":"Động từ báo cáo thận trọng","pattern":"Evidence + suggests / indicates / implies + that + clause","ex":"The evidence suggests that sleep affects memory."},{"label":"Làm mềm trong lời nói","pattern":"I wonder if / I was thinking / sort of / a bit + ...","ex":"I was wondering if we could move the meeting."}],"uses":[{"title":"Kết luận học thuật thận trọng","detail":"Dùng suggest, indicate hoặc seem khi dữ liệu chưa đủ để khẳng định chắc chắn.","ex":"The findings indicate a possible link between diet and mood.","exvi":"Các phát hiện cho thấy có thể có mối liên hệ giữa chế độ ăn và tâm trạng."},{"title":"Nói về xu hướng, không phải quy luật","detail":"Dùng tend to, be likely to hoặc in most cases để tránh nói rằng điều gì luôn đúng.","ex":"Antibiotics tend to be less effective against viruses.","exvi":"Kháng sinh thường kém hiệu quả hơn với virus."},{"title":"Giới hạn phạm vi khẳng định","detail":"Dùng mainly, to some extent hoặc by and large để cho biết câu chỉ đúng một phần.","ex":"To some extent, stress explains the difference.","exvi":"Ở một mức độ nào đó, căng thẳng giải thích được sự khác biệt."},{"title":"Nêu khả năng có cơ sở","detail":"Dùng may well hoặc could possibly để nói điều gì khá có thể xảy ra nhưng chưa chắc.","ex":"The side effects may well disappear within a week.","exvi":"Tác dụng phụ rất có thể sẽ biến mất trong vòng một tuần."},{"title":"Đề nghị và góp ý tế nhị","detail":"Dùng I wonder if, I was thinking hoặc a bit để lời yêu cầu bớt thẳng thừng.","ex":"I wonder if you might have time to review this.","exvi":"Tôi tự hỏi liệu bạn có thể có thời gian xem lại phần này không."}],"signals":["seem","appear","tend to","be likely to","it would seem that","may well","to some extent","by and large","in most cases","suggest"],"cautions":["Đừng viết “be tend”; “tend” là động từ thường: “people tend to…”.","Không dùng “prove” khi dữ liệu chưa chắc; chọn “suggest” hoặc “indicate”, và đừng rào quá nhiều trong cùng một câu.","“It seems that…” đi với mệnh đề; “seem to V” đi với chủ ngữ thật; không viết “It seems to that”.","Đây khác với suy luận “must/can't” (đã có điểm riêng); ở đây trọng tâm là làm nhẹ và giới hạn mức độ chắc chắn."]},"nominalisation":{"summary":"Danh từ hoá là biến động từ, tính từ hoặc cả mệnh đề thành danh từ hay cụm danh từ để câu viết gọn, khách quan và trang trọng hơn.","formulas":[{"label":"Động từ → danh từ","pattern":"decide → decision; arrive → arrival; develop → development","ex":"The development of the vaccine took ten years."},{"label":"Tính từ → danh từ","pattern":"different → difference; important → importance; able → ability","ex":"There is a clear difference between the two groups."},{"label":"Mệnh đề → cụm danh từ","pattern":"Because + S + V → Because of / due to + the + noun + of/in","ex":"The rise in prices forced many families to cut spending."},{"label":"Mẫu danh từ hay gặp","pattern":"the + noun + of; a growing number of; a lack of; an increase in","ex":"A growing number of patients now use online booking."},{"label":"Danh từ làm chủ ngữ","pattern":"The + noun + of + N + V (thay cho S + V + because ...)","ex":"The availability of cheap data has changed how people study."}],"uses":[{"title":"Nén mệnh đề thành cụm danh từ","detail":"Thay một mệnh đề phụ bằng cụm danh từ để câu ngắn và trang trọng hơn.","ex":"Because costs rose sharply, the project stopped. → The sharp rise in costs stopped the project.","exvi":"Chi phí tăng mạnh nên dự án dừng lại."},{"title":"Giữ giọng khách quan","detail":"Danh từ hoá bỏ chủ thể hành động nên văn bản nghe khách quan, phù hợp báo cáo.","ex":"The analysis of the samples confirmed the diagnosis.","exvi":"Việc phân tích mẫu đã xác nhận chẩn đoán."},{"title":"Dùng danh từ làm chủ ngữ","detail":"Cụm danh từ đứng đầu câu giúp nêu chủ đề rõ ràng rồi mới thêm thông tin.","ex":"Failure to follow the instructions may cause side effects.","exvi":"Không làm theo hướng dẫn có thể gây tác dụng phụ."},{"title":"Nói về xu hướng và số liệu","detail":"Dùng increase/rise/fall/decline kèm giới từ in hoặc of để mô tả thay đổi.","ex":"There has been a steady decline in the birth rate.","exvi":"Tỷ lệ sinh giảm đều."},{"title":"Khi không nên danh từ hoá","detail":"Nếu câu trở nên nặng nề, mơ hồ hoặc quá nhiều “of”, nên giữ động từ cho rõ.","ex":"We decided to wait. (not: Our decision was to carry out a postponement.)","exvi":"Chúng tôi quyết định chờ."}],"signals":["the + noun + of","a growing number of","a lack of","an increase in","a decline in","as a result of","due to","the introduction of"],"cautions":["Không nên danh từ hoá mọi câu: văn nói và văn kể chuyện thường dùng động từ, như “We decided to wait”.","Chú ý giới từ đi sau danh từ: “an increase in prices”, “the cause of the problem”, “a lack of time”, “a need for change”.","Khi danh từ hoá, nhớ đổi liên từ thành giới từ: “because it rained” → “because of the rain”.","Tránh chuỗi “of” quá dài như “the analysis of the evaluation of the impact of ...” vì người đọc dễ lạc."]},"past-perfect-continuous":{"summary":"Past perfect continuous (had been + V-ing) nhấn mạnh quá trình kéo dài hoặc nguyên nhân xảy ra trước một mốc trong quá khứ, và cùng quá khứ đơn, quá khứ tiếp diễn, quá khứ hoàn thành tạo thành bộ thì kể chuyện.","formulas":[{"label":"Khẳng định","pattern":"S + had been + V-ing","ex":"The nurses had been working since dawn."},{"label":"Phủ định","pattern":"S + hadn't been + V-ing","ex":"He hadn't been sleeping well before the exam."},{"label":"Nghi vấn","pattern":"Had + S + been + V-ing …?","ex":"Had you been taking the medicine regularly?"},{"label":"Hỏi thời lượng","pattern":"How long + had + S + been + V-ing …?","ex":"How long had she been teaching when she retired?"},{"label":"Khoảng thời gian / mốc","pattern":"had been + V-ing + for + khoảng / since + mốc","ex":"We had been waiting for an hour when the bus came."}],"uses":[{"title":"Quá trình kéo dài trước một mốc","detail":"Nhấn mạnh hành động đã diễn ra liên tục đến một thời điểm trong quá khứ.","ex":"By noon, the team had been testing the vaccine for six hours.","exvi":"Đến trưa, nhóm đã thử nghiệm vắc-xin được sáu tiếng."},{"title":"Nguyên nhân của tình huống quá khứ","detail":"Giải thích vì sao một kết quả nhìn thấy được lúc đó lại xảy ra.","ex":"The floor was wet because it had been raining.","exvi":"Sàn ướt vì trời đã mưa."},{"title":"Hành động tiếp diễn bị cắt ngang","detail":"Quá trình đang diễn ra thì một sự kiện quá khứ đơn xen vào.","ex":"I had been reading for an hour when the phone rang.","exvi":"Tôi đang đọc được một tiếng thì điện thoại reo."},{"title":"Tiếp diễn hay hoàn thành?","detail":"Tiếp diễn nhấn quá trình; hoàn thành đơn nhấn kết quả hoặc số lượng.","ex":"She had been writing emails all morning, and she had written forty by lunch.","exvi":"Cô ấy viết email cả buổi sáng, và đến trưa đã viết xong bốn mươi cái."},{"title":"Phối hợp các thì khi kể chuyện","detail":"Quá khứ đơn kể chuỗi sự kiện chính, quá khứ tiếp diễn dựng bối cảnh, quá khứ hoàn thành hoặc had been + V-ing lùi về trước.","ex":"It was snowing when I arrived; the guests had been waiting for ages.","exvi":"Lúc tôi đến thì tuyết đang rơi; khách đã đợi từ lâu."}],"signals":["for","since","how long","all day","all morning","by the time","when","before","until","recently"],"cautions":["Động từ trạng thái (know, own, believe, understand) không dùng tiếp diễn: “had known”, không phải “had been knowing”.","Cần có mốc quá khứ rõ ràng; nếu mốc là hiện tại thì dùng “have been + V-ing”, không phải “had been”.","Không dùng had been + V-ing cho chuỗi sự kiện nối tiếp nhau; dùng quá khứ đơn: “He stood up and left”.","Nhấn kết quả hoặc số lượng (how many, how much) thì dùng quá khứ hoàn thành đơn: “had written ten pages”."]},"reporting-verbs":{"summary":"Mỗi động từ tường thuật đòi hỏi một khuôn cấu trúc riêng, nên cần học động từ cùng với mẫu câu đi kèm thay vì chỉ thêm “that” như với “say”.","formulas":[{"label":"Động từ + V-ing","pattern":"S + admit/deny/suggest/recommend/mention + V-ing","ex":"He denied copying the data."},{"label":"Động từ + mệnh đề that","pattern":"S + suggest/recommend/mention/explain + (that) + S + V","ex":"The doctor recommended that she (should) see a specialist."},{"label":"Động từ + to V","pattern":"S + promise/offer/refuse/threaten/agree + to V","ex":"The clinic refused to release the results."},{"label":"Động từ + tân ngữ + to V","pattern":"S + advise/warn/invite/remind/persuade/tell/ask + O + (not) to V","ex":"She reminded us to bring our ID cards."},{"label":"Động từ + tân ngữ + giới từ + V-ing","pattern":"S + accuse O of / blame O for / congratulate O on + V-ing","ex":"They congratulated her on passing the exam."},{"label":"say, tell, ask, explain","pattern":"say (to O) that / tell O that / explain (to O) that / ask O to V","ex":"She explained to the students that the deadline had changed."}],"uses":[{"title":"Thừa nhận hoặc phủ nhận","detail":"Dùng admit, deny, mention, suggest với V-ing để nói về hành động đã xảy ra.","ex":"The patient admitted skipping his medication.","exvi":"Bệnh nhân thừa nhận đã bỏ liều thuốc."},{"title":"Cam kết hoặc từ chối","detail":"Dùng promise, offer, refuse, threaten, agree với to V để nói về ý định hoặc quyết định.","ex":"They offered to give us a lift to the station.","exvi":"Họ đề nghị chở chúng tôi ra ga."},{"title":"Khuyên, cảnh báo, nhắc nhở","detail":"Dùng advise, warn, remind, invite, persuade với tân ngữ và to V để tác động đến người khác.","ex":"The police warned residents not to leave their doors open.","exvi":"Cảnh sát cảnh báo người dân đừng để cửa mở."},{"title":"Buộc tội, đổ lỗi, chúc mừng","detail":"Dùng accuse, blame, congratulate, apologise với giới từ cố định rồi đến V-ing.","ex":"The committee accused the author of using other researchers' results.","exvi":"Hội đồng buộc tội tác giả đã dùng kết quả của người khác."},{"title":"Chọn say, tell hay ask","detail":"Tell cần người nghe làm tân ngữ, còn say thì không; ask dùng cho câu hỏi hoặc yêu cầu.","ex":"The lecturer told us that the exam would be online.","exvi":"Giảng viên nói với chúng tôi rằng bài thi sẽ làm trực tuyến."}],"signals":["admit","deny","suggest","recommend","promise","refuse","advise","warn","accuse","apologise"],"cautions":["“suggest” và “recommend” không dùng “O + to V”: nói “suggested taking” hoặc “suggested that I take”, không nói “suggested me to take”.","“deny/admit” đi với V-ing: nói “denied taking”, không nói “denied to take”.","“say” không có tân ngữ người trực tiếp: nói “told me” hoặc “said to me”, không nói “said me”.","Giới từ đi cố định: accuse O of, blame O for, congratulate O on, apologise to O for. Lùi thì cơ bản xem bài câu tường thuật."]}};
  const GX_ADD = {"adjective-gradability":{"mistakes":[{"wrong":"The water was very freezing.","right":"The water was absolutely freezing.","bad":"very","fix":"absolutely","why":"“Freezing” đã là cực lạnh nên không đi với “very”. Hãy nhớ: “very cold” nhưng “absolutely freezing”."},{"wrong":"I felt very boring during the lecture.","right":"I felt very bored during the lecture.","bad":"boring","fix":"bored","why":"Người cảm thấy chán dùng “bored”. “Boring” nghĩa là bản thân người đó gây chán cho người khác."},{"wrong":"The film was really bored, so we left.","right":"The film was really boring, so we left.","bad":"bored","fix":"boring","why":"Bộ phim là thứ gây chán nên dùng “boring”. Tiếng Việt chỉ nói “chán” nên dễ lẫn hai dạng."},{"wrong":"She bought a black big handbag.","right":"She bought a big black handbag.","bad":"black big","fix":"big black","why":"Kích cỡ đứng trước màu sắc. Tiếng Việt đặt màu sau danh từ nên người học hay đảo thứ tự."},{"wrong":"He is absolutely tired after the trip.","right":"He is very tired after the trip.","bad":"absolutely","fix":"very","why":"“Tired” là tính từ gradable nên đi với “very”. Muốn dùng “absolutely” thì đổi thành “exhausted”."},{"wrong":"The test was very impossible for beginners.","right":"The test was completely impossible for beginners.","bad":"very","fix":"completely","why":"“Impossible” không có mức độ nên không dùng “very”. Dùng “completely” hoặc “absolutely”."},{"wrong":"It was a French lovely restaurant.","right":"It was a lovely French restaurant.","bad":"French lovely","fix":"lovely French","why":"Ý kiến (lovely) đứng trước xuất xứ (French). Tính từ chỉ quan điểm luôn đứng đầu chuỗi."},{"wrong":"The news was shocked.","right":"The news was shocking.","bad":"shocked","fix":"shocking","why":"Tin tức gây ra cú sốc nên dùng “shocking”; người nghe tin mới là “shocked”."}],"contrast":{"title":"very hay absolutely?","a":"very + tính từ gradable","b":"absolutely + tính từ ungradable","rows":[["Loại tính từ","Gradable có nhiều mức độ: very cold, very tired","Ungradable đã ở mức cực đại: absolutely freezing, absolutely exhausted"],["Từ nhấn mạnh đi kèm","very, extremely, fairly, rather","absolutely, completely, totally"],["Ví dụ sai thường gặp","“absolutely cold”, “absolutely tired” là sai","“very freezing”, “very exhausted” là sai"],["Từ dùng cho cả hai","really, pretty: really cold","really, pretty: really freezing"]],"ex":[["The room was very cold.","The room was absolutely freezing."],["She was very tired.","She was absolutely exhausted."]],"tip":"Hỏi mình: tính từ này có “hơi” hay “rất” được không? Có thì dùng very, không thì dùng absolutely.","quiz":[{"q":"The soup was ___ hot, so I waited a minute before eating.","opts":["absolutely","very","completely","totally"],"a":1,"why":"“Hot” là tính từ gradable nên đi với “very”; ba từ còn lại dành cho tính từ ungradable.","wrong":{"absolutely":"“Absolutely” không đi với “hot” vì “hot” có nhiều mức độ.","completely":"“Completely” chỉ hợp với tính từ ungradable, còn “hot” là gradable.","totally":"“Totally” là từ nhấn mạnh cho tính từ ungradable nên không đứng trước “hot”."}},{"q":"The desert at noon was ___ boiling.","opts":["very","fairly","absolutely","rather"],"a":2,"why":"“Boiling” là tính từ ungradable (cực nóng) nên đi với “absolutely”, không đi với “very”.","wrong":{"very":"“Very” không dùng với “boiling” vì từ này đã mang nghĩa cực nóng.","fairly":"“Fairly” chỉ mức vừa phải, mâu thuẫn với nghĩa cực nóng của “boiling”.","rather":"“Rather” là từ chỉ mức khá cho tính từ gradable, không hợp với “boiling”."}},{"q":"The task was ___ impossible for one person to finish alone.","opts":["very","fairly","rather","completely"],"a":3,"why":"“Impossible” là ungradable nên đi với “completely”; cả “very”, “fairly”, “rather” đều dành cho gradable.","wrong":{"very":"“Very” không đi với “impossible” vì việc không thể thì không có mức độ.","fairly":"“Fairly” chỉ mức vừa phải nên không hợp với “impossible”.","rather":"“Rather” dùng với tính từ gradable, không đứng trước “impossible”."}},{"q":"He is ___ tired after the exams, but he will recover soon.","opts":["very","absolutely","completely","totally"],"a":0,"why":"“Tired” là gradable nên dùng “very”; vế sau cho thấy anh ấy chỉ mệt chứ chưa kiệt sức.","wrong":{"absolutely":"“Absolutely” không đi với “tired” và còn mâu thuẫn với ý sẽ hồi phục nhanh.","completely":"“Completely” mang nghĩa tuyệt đối nên không hợp với “tired”.","totally":"“Totally” chỉ đi với tính từ ungradable, không đứng trước “tired”."}},{"q":"We bought a ___ vase for the entrance hall.","opts":["beautiful old Chinese","old beautiful Chinese","Chinese old beautiful","beautiful Chinese old"],"a":0,"why":"Thứ tự đúng là ý kiến, tuổi, xuất xứ: beautiful – old – Chinese rồi đến danh từ.","wrong":{"old beautiful Chinese":"Ý kiến “beautiful” phải đứng trước tuổi “old”, không đảo lại.","Chinese old beautiful":"Xuất xứ “Chinese” phải đứng sát danh từ, còn ý kiến phải đứng đầu.","beautiful Chinese old":"Tuổi “old” phải đứng trước xuất xứ “Chinese”, nên “Chinese old” sai thứ tự."}},{"q":"Everyone was ___ when the exam results arrived early.","opts":["surprising","surprised","surprise","surprisingly"],"a":1,"why":"Người cảm thấy bất ngờ dùng tính từ -ed; chủ ngữ “everyone” là người chịu cảm giác.","wrong":{"surprising":"“Surprising” mô tả thứ gây bất ngờ, không dùng cho “everyone”.","surprise":"“Surprise” là danh từ hoặc động từ, không đứng sau “was” làm tính từ.","surprisingly":"“Surprisingly” là trạng từ, không làm vị ngữ sau “was” trong câu này."}},{"q":"Her essay was ___ brilliant; the examiners gave her full marks.","opts":["fairly","a bit","quite","rather"],"a":2,"why":"Với tính từ ungradable như “brilliant”, “quite” nghĩa là hoàn toàn; điểm tuyệt đối xác nhận mức độ cao nhất.","wrong":{"fairly":"“Fairly” nghĩa là khá và mâu thuẫn với việc được điểm tuyệt đối.","a bit":"“A bit” chỉ mức nhẹ nên không hợp với bài luận được điểm tuyệt đối.","rather":"“Rather” chỉ mức khá và không đi tự nhiên với “brilliant”."}},{"q":"She wore a ___ jacket to the interview.","opts":["wool long grey","long wool grey","grey long wool","long grey wool"],"a":3,"why":"Thứ tự đúng là kích cỡ, màu, chất liệu: long – grey – wool rồi đến danh từ.","wrong":{"wool long grey":"Kích cỡ “long” phải đứng đầu chuỗi, còn chất liệu “wool” phải đứng sát danh từ.","long wool grey":"Màu “grey” phải đứng trước chất liệu “wool”, nên “wool grey” sai thứ tự.","grey long wool":"Kích cỡ “long” phải đứng trước màu “grey”, không đứng sau."}}]}},"adverbial-clauses":{"mistakes":[{"wrong":"She left early so that to avoid the traffic.","right":"She left early so as to avoid the traffic.","bad":"that","fix":"as","why":"“So that” cần mệnh đề có chủ ngữ; với V nguyên mẫu dùng “so as to”. Người Việt hay ghép “để” thành “so that to”."},{"wrong":"It was so beautiful day that we stayed outside.","right":"It was such a beautiful day that we stayed outside.","bad":"so","fix":"such a","why":"Trước danh từ (kể cả có tính từ) dùng “such a/an”; “so” chỉ đứng trước tính từ hoặc trạng từ."},{"wrong":"Despite he was tired, he finished the report.","right":"Although he was tired, he finished the report.","bad":"Despite","fix":"Although","why":"“Despite” đi với danh từ hoặc V-ing, không đi với mệnh đề có chủ ngữ; trước mệnh đề dùng “although”."},{"wrong":"The test was such easy that everyone passed.","right":"The test was so easy that everyone passed.","bad":"such","fix":"so","why":"“Easy” là tính từ đứng một mình nên dùng “so”; “such” chỉ đi với danh từ."},{"wrong":"He wore gloves so that not to contaminate the sample.","right":"He wore gloves so as not to contaminate the sample.","bad":"that","fix":"as","why":"Mục đích phủ định cùng chủ ngữ dùng “so as not to + V”; “so that” phải kèm mệnh đề đầy đủ."},{"wrong":"Whoever the weather is, the clinic will open.","right":"Whatever the weather is, the clinic will open.","bad":"Whoever","fix":"Whatever","why":"“Whoever” chỉ người; với sự vật như “weather” phải dùng “whatever”."},{"wrong":"Whatever difficult the task is, she never gives up.","right":"However difficult the task is, she never gives up.","bad":"Whatever","fix":"However","why":"Trước tính từ phải dùng “however” (dù … đến đâu); “whatever” đi với danh từ hoặc động từ."},{"wrong":"Albeit the data are limited, they are useful.","right":"Although the data are limited, they are useful.","bad":"Albeit","fix":"Although","why":"“Albeit” chỉ đứng trước tính từ hoặc cụm từ, không dẫn mệnh đề đầy đủ có chủ ngữ và động từ."}],"contrast":{"title":"so … that hay so that?","a":"so/such … that (kết quả)","b":"so that (mục đích)","rows":[["Nghĩa","Kết quả: mức độ mạnh đến mức gây ra một việc (“so tired that I slept”).","Mục đích: làm việc A để việc B có thể xảy ra (“so that I could sleep”)."],["Từ đi kèm","So + adj/adv hoặc such + (a) + N, rồi that.","So that + S + can/could/will/would + V."],["Động từ khuyết thiếu","Thường là thì quá khứ đơn, không cần can/could.","Gần như luôn có can/could/will/would hoặc may/might."],["Rút gọn","Không rút gọn thành to + V.","Có thể rút thành so as to / in order to khi cùng chủ ngữ."]],"ex":[["The room was so noisy that nobody could concentrate.","We closed the windows so that nobody could be disturbed."],["She was such a careful nurse that errors were rare.","She worked carefully so that errors would be rare."]],"tip":"“So … that” có tính từ chen giữa là kết quả; “so that” dính liền và có can/could/would là mục đích.","quiz":[{"q":"The clinic extended its hours ___ more people could attend.","opts":["so that","so","such that","so as"],"a":0,"why":"Mục đích với chủ ngữ mới (more people) và “could” nên dùng “so that”.","wrong":{"so":"“So” một mình không nối mục đích; thiếu “that” nên câu không hoàn chỉnh.","such that":"“Such that” có nghĩa kết quả khác và không đi với “could attend” để nêu mục đích.","so as":"“So as” cần “to + V”, trong khi sau chỗ trống là mệnh đề có chủ ngữ “more people”."}},{"q":"The queue was ___ long that we gave up waiting.","opts":["such","so that","so","too"],"a":2,"why":"“Long” là tính từ và vế sau nêu kết quả (we gave up), nên dùng “so … that”.","wrong":{"such":"“Such” đi với danh từ, mà “long” là tính từ đứng một mình.","so that":"“So that” nêu mục đích và bị thừa “that” vì câu đã có “that” phía sau.","too":"“Too” cần “to + V”, không dùng với “that we gave up”."}},{"q":"She spoke quietly ___ to wake the baby.","opts":["so that not","lest","not so","so as not"],"a":3,"why":"Cùng chủ ngữ và có “to wake” nên dùng “so as not to”; chỗ trống là “so as not”.","wrong":{"so that not":"“So that not” sai vì “so that” cần mệnh đề đầy đủ, không đi với “not to + V”.","lest":"“Lest” đi với mệnh đề, không đứng trước “to wake”.","not so":"“Not so … to” không tạo thành cấu trúc mục đích phủ định."}},{"q":"It was ___ cold a morning that the pipes froze.","opts":["such","so","such a","very"],"a":1,"why":"Trước “cold a morning” (adj + a + N) cấu trúc đúng là “so cold a morning”; “so” đứng trước tính từ.","wrong":{"such":"“Such” phải đi với “a cold morning”, không đảo thứ tự tính từ ở đây.","such a":"“Such a” không thể đứng trước “cold a morning”, câu thành sai trật tự.","very":"“Very” không nêu kết quả và không dẫn tới mệnh đề “that the pipes froze”."}},{"q":"He repeated the number ___ the nurse should misread it.","opts":["so that","whereas","lest","although"],"a":2,"why":"Điều cần tránh (misread) kèm “should” nên dùng “lest”; “so that” sẽ ngược nghĩa.","wrong":{"so that":"“So that … should misread” sẽ nghĩa là anh ta muốn cô y tá đọc sai, ngược với ý câu.","whereas":"“Whereas” đối lập hai sự việc, không nêu mục đích.","although":"“Although” nhượng bộ, trong khi câu nói về mục đích tránh sai sót."}},{"q":"The proposal was accepted, ___ with some reluctance.","opts":["whereas","albeit","lest","seeing that"],"a":1,"why":"Chỉ có “albeit” đứng trước cụm “with some reluctance” mà không cần chủ ngữ và động từ.","wrong":{"whereas":"“Whereas” cần một mệnh đề đầy đủ phía sau.","lest":"“Lest” cần mệnh đề và mang nghĩa sợ rằng, không hợp ở đây.","seeing that":"“Seeing that” cần mệnh đề đầy đủ để nêu lý do, nhưng sau chỗ trống chỉ có một cụm giới từ."}},{"q":"___ the price, we will buy the new scanner.","opts":["However","Whoever","Lest","Whatever"],"a":3,"why":"“Price” là danh từ nên dùng “whatever” để nói điều gì xảy ra cũng không đổi quyết định.","wrong":{"However":"“However” phải đi với tính từ hoặc trạng từ, không đi với danh từ “price”.","Whoever":"“Whoever” chỉ người, không dùng cho giá cả.","Lest":"“Lest” nêu sự lo ngại và cần mệnh đề, không dùng trong câu nhượng bộ này."}},{"q":"___ tired you are, you must complete the checklist.","opts":["However","Whatever","Whoever","So that"],"a":0,"why":"Sau chỗ trống là “tired” thuộc dạng tính từ, nên cần “however tired you are”.","wrong":{"Whatever":"“Whatever” không đứng trực tiếp trước tính từ “tired”.","Whoever":"“Whoever” chỉ người và không hợp cấu trúc tính từ.","So that":"“So that” nêu mục đích, không mang ý nhượng bộ “dù mệt đến đâu”."}}]}},"articles-advanced":{"mistakes":[{"wrong":"The life is hard for many farmers.","right":"Life is hard for many farmers.","bad":"The life","fix":"Life","why":"Danh từ trừu tượng nói chung không dùng “the”. Tiếng Việt không có mạo từ nên dễ thêm “the” cho trang trọng."},{"wrong":"She goes to school by the bus.","right":"She goes to school by bus.","bad":"by the bus","fix":"by bus","why":"Sau “by” chỉ phương tiện nói chung thì bỏ mạo từ: “by bus”, “by train”, “by car”."},{"wrong":"The elderly needs more support.","right":"The elderly need more support.","bad":"needs","fix":"need","why":"“The elderly” chỉ nhóm người nên là số nhiều, động từ không có -s. Đừng nghĩ nó là danh từ số ít."},{"wrong":"Nile flows through Egypt and Sudan.","right":"The Nile flows through Egypt and Sudan.","bad":"Nile","fix":"The Nile","why":"Tên sông, biển, dãy núi luôn có “the”. Chỉ đỉnh núi đơn lẻ và đa số tên nước thì không."},{"wrong":"He is in the hospital with pneumonia.","right":"He is in hospital with pneumonia.","bad":"in the hospital","fix":"in hospital","why":"Khi là bệnh nhân điều trị, Anh-Anh dùng “in hospital” không mạo từ. “The hospital” chỉ toà nhà."},{"wrong":"I had a flu last week.","right":"I had the flu last week.","bad":"a","fix":"the","why":"Bệnh cúm dùng “the flu” hoặc “flu”, không dùng “a flu”. Nhưng “a cold”, “a headache” lại dùng a."},{"wrong":"The tigers are in danger of extinction.","right":"Tigers are in danger of extinction.","bad":"The tigers","fix":"Tigers","why":"Nói chung về cả loài với số nhiều thì không dùng mạo từ. “The tigers” chỉ một nhóm hổ cụ thể."},{"wrong":"We had the dinner at eight.","right":"We had dinner at eight.","bad":"the dinner","fix":"dinner","why":"Tên bữa ăn thường không có mạo từ: breakfast, lunch, dinner. Người Việt hay thêm “the” như trước “bữa”."}],"contrast":{"title":"the hay không mạo từ (Ø)?","a":"the","b":"không mạo từ (Ø)","rows":[["Nghĩa","Chỉ người, vật hay nhóm xác định: the doctor, the elderly","Nói chung hoặc chức năng: Doctors help, at university"],["Danh từ trừu tượng","Khi có giới hạn: the justice of the ruling","Khi nói chung: Justice matters"],["Nơi chốn","Toà nhà cụ thể: went to the school to complain","Chức năng chính: at school, in hospital"],["Địa danh","Sông, dãy núi, nước có Kingdom/Republic: the Nile, the Alps","Đỉnh núi, đa số nước: Everest, Canada"]],"ex":[["The hospital near my house has a new clinic.","My uncle is in hospital after an accident."],["The life of a nurse is demanding.","Life is unpredictable."]],"tip":"The khi xác định hoặc có giới hạn; zero khi nói chung hoặc cụm chức năng cố định.","quiz":[{"t":"c","q":"Teachers say that ___ is essential for a child's development.","opts":["play","the play","a play","plays"],"a":0,"why":"Danh từ trừu tượng, không đếm được, nghĩa chung dùng không mạo từ: play is essential.","wrong":{"the play":"“the play” chỉ vở kịch hoặc một hoạt động cụ thể, không phải việc vui chơi nói chung.","a play":"“a play” là một vở kịch, sai nghĩa với chuyện phát triển của trẻ.","plays":"“plays” là các vở kịch; với nghĩa vui chơi nói chung không dùng số nhiều."}},{"t":"c","q":"The report describes ___ play that the children performed on Friday.","opts":["a","the","no article","some"],"a":1,"why":"Mệnh đề quan hệ “that the children performed on Friday” làm vở kịch xác định, nên dùng the.","wrong":{"a":"“a” chỉ vở kịch chưa xác định, nhưng mệnh đề “that the children performed” xác định nó.","no article":"Danh từ số ít đếm được “play” không thể đứng trần trong nghĩa này.","some":"“some” không đi với danh từ số ít đếm được."}},{"t":"c","q":"Next year I want to study ___ at a university in Germany.","opts":["the medicine","a medicine","medicine","medicines"],"a":2,"why":"Môn học dùng không mạo từ khi nói chung: study medicine. Các đáp án kia đổi nghĩa thành thuốc.","wrong":{"the medicine":"“the medicine” là thuốc cụ thể, không phải ngành y.","a medicine":"“a medicine” là một loại thuốc, không phải môn học.","medicines":"“medicines” là các loại thuốc, không phải ngành học."}},{"t":"c","q":"The nurse gave me ___ medicine that the doctor had prescribed.","opts":["a","no article","any","the"],"a":3,"why":"Mệnh đề “that the doctor had prescribed” xác định loại thuốc nên cần the, dù medicine là danh từ không đếm được.","wrong":{"a":"“a” không hợp vì loại thuốc đã được bác sĩ kê, tức là xác định.","no article":"Danh từ không đếm được có mệnh đề xác định phía sau cần the.","any":"“any” dùng trong câu phủ định hoặc nghi vấn, không dùng khẳng định ở đây."}},{"t":"c","q":"My cousin is at ___ university in Leeds, and she loves her course.","opts":["no article","the","a","an"],"a":0,"why":"Việc là sinh viên dùng “at university” không mạo từ (Anh-Anh). Vế “loves her course” xác nhận đang học.","wrong":{"the":"“the university” chỉ toà nhà cụ thể, nhưng câu này nói về việc đang học.","a":"“a university” hiểu là một trường bất kỳ, không hợp với việc đang theo học.","an":"“an” sai vì “university” bắt đầu bằng âm /j/, và nghĩa cũng không hợp."}},{"t":"c","q":"We drove to ___ university to collect the certificate.","opts":["no article","the","a","an"],"a":1,"why":"Khi đến một toà nhà để làm việc cụ thể (lấy giấy chứng nhận) thì dùng the university.","wrong":{"no article":"Câu nói đến toà nhà cụ thể để lấy giấy chứng nhận, nên thiếu the là sai.","a":"“a university” không rõ ràng vì ai cũng biết trường nào đó.","an":"“an” sai âm đầu và không hợp nghĩa."}},{"t":"c","q":"___ is the second-largest country in the world by area.","opts":["The Canada","A Canada","Canada","Canadas"],"a":2,"why":"Đa số tên nước không dùng mạo từ: Canada, France; chỉ có the United States, the Netherlands…","wrong":{"The Canada":"Canada không có Republic hay Kingdom nên không dùng the.","A Canada":"Tên nước riêng không dùng a.","Canadas":"Tên nước không thêm -s ở đây."}},{"t":"c","q":"It was ___ longest journey of my life.","opts":["a","no article","an","the"],"a":3,"why":"So sánh nhất luôn đi với the: the longest journey. “Of my life” xác nhận nghĩa duy nhất.","wrong":{"a":"“a” không dùng trước so sánh nhất “longest”.","no article":"So sánh nhất cần the, không thể bỏ.","an":"“an” sai ngữ pháp trước tính từ so sánh nhất “longest”."}}]}},"comparison-advanced":{"mistakes":[{"wrong":"The more I read, I learn more.","right":"The more I read, the more I learn.","bad":"I learn more","fix":"the more I learn","why":"Vế sau của “the … the …” cũng phải bắt đầu bằng “the + so sánh hơn”; người Việt hay quên mở vế sau bằng “the”."},{"wrong":"This book is very better than that one.","right":"This book is much better than that one.","bad":"very","fix":"much","why":"Không dùng “very” trước so sánh hơn; tiếng Việt “rất tốt hơn” dễ khiến ta dịch sát. Hãy dùng much, far hoặc a lot."},{"wrong":"The film was more more boring than I expected.","right":"The film was much more boring than I expected.","bad":"more more","fix":"much more","why":"Không lặp “more” để nhấn mạnh; muốn nhấn mạnh thì thêm much hoặc far trước “more boring”."},{"wrong":"Prices are getting highest and highest.","right":"Prices are getting higher and higher.","bad":"highest","fix":"higher","why":"Thay đổi dần dần dùng “so sánh hơn and so sánh hơn”, không dùng dạng so sánh nhất."},{"wrong":"She is the taller of the three sisters.","right":"She is the tallest of the three sisters.","bad":"taller","fix":"tallest","why":"Từ ba đối tượng trở lên mới dùng so sánh nhất; “the taller” chỉ dùng khi so sánh hai người."},{"wrong":"We have less patients than last year.","right":"We have fewer patients than last year.","bad":"less","fix":"fewer","why":"“Patients” là danh từ đếm được số nhiều nên dùng “fewer”; tiếng Việt chỉ có “ít hơn” nên dễ nhầm."},{"wrong":"My salary is twice more than hers.","right":"My salary is twice as much as hers.","bad":"more than","fix":"as much as","why":"Bội số dùng “twice as much/many as”, không dùng “twice more than” như cách dịch “gấp đôi”."},{"wrong":"This road is not nearly so busy than the main one.","right":"This road is not nearly as busy as the main one.","bad":"than","fix":"as","why":"Sau “not nearly as/so + adj” phải dùng “as”, không dùng “than”; “than” chỉ đi với so sánh hơn."}],"contrast":{"title":"less hay fewer?","a":"less","b":"fewer","rows":[["Danh từ đi kèm","Danh từ không đếm được: less time, less money, less traffic","Danh từ đếm được số nhiều: fewer people, fewer errors"],["Dạng so sánh của","little: little – less – least","few: few – fewer – fewest"],["Với than","less + N + than: less sugar than before","fewer + N + than: fewer accidents than before"],["Lưu ý","Dùng được với số lượng đo: less than 5 kg, less than two hours","Dùng với số đếm: fewer than ten students"]],"ex":[["We spend less time on paperwork now.","We see fewer patients on Mondays now."],["There is less noise in the new office.","There are fewer desks in the new office."]],"tip":"Đếm được thì “fewer”, không đếm được thì “less”.","quiz":[{"q":"We have ___ time than we thought, so we must hurry.","opts":["fewer","less","least","a few"],"a":1,"why":"“Time” là danh từ không đếm được nên dùng “less”; “than we thought” cho thấy cần so sánh hơn.","wrong":{"fewer":"“fewer” chỉ dùng với danh từ đếm được số nhiều, mà time là không đếm được.","least":"“least” là so sánh nhất, không đi với “than we thought”.","a few":"“a few” không phải dạng so sánh và không đi với “than”."}},{"q":"There were ___ errors in the second report than in the first.","opts":["less","fewer","little","the least"],"a":1,"why":"“Errors” là danh từ đếm được số nhiều nên dùng “fewer”; “than in the first” là dấu hiệu so sánh hơn.","wrong":{"less":"“less” dùng với danh từ không đếm được nên không hợp với errors.","little":"“little” không phải so sánh hơn và không đi với “than”.","the least":"“the least” là so sánh nhất, không đi với “than in the first”."}},{"q":"The ___ people drink, the more they sleep badly at night.","opts":["more","most","much","many"],"a":0,"why":"Cấu trúc “the more …, the more …” cần so sánh hơn ở vế đầu; “more” bổ nghĩa cho động từ drink.","wrong":{"most":"“most” là dạng so sánh nhất, không mở được vế đầu của “the … the …”.","much":"“much” không phải so sánh hơn nên không đi với “the” trong cấu trúc này.","many":"“many” không phải dạng so sánh hơn nên không dùng trong cấu trúc này."}},{"q":"Mai has ___ as many books as her brother, who owns almost a hundred.","opts":["twice","two","second","double of"],"a":0,"why":"Bội số dùng “twice as many … as” với danh từ đếm được; “as many books as” là dấu hiệu.","wrong":{"two":"“two as many” thiếu từ “times” nên không đúng cấu trúc bội số.","second":"“second as many” không phải cách nói của bội số.","double of":"“double of as many” sai vì double không đi với “of” trước “as many”."}},{"q":"Her English is getting ___ every month.","opts":["more good","better and better","best and best","the better"],"a":1,"why":"Thay đổi dần dần dùng “so sánh hơn and so sánh hơn”; better là dạng so sánh hơn của good.","wrong":{"more good":"good có dạng so sánh hơn bất quy tắc là better, không dùng “more good”.","best and best":"“best and best” dùng dạng so sánh nhất nên không diễn tả được sự tăng dần.","the better":"“the better” chỉ dùng cho hai đối tượng hoặc trong cấu trúc “the … the …”."}},{"q":"This is easily ___ hospital in the region, and it treats thousands of patients.","opts":["the largest","larger","the larger","more large"],"a":0,"why":"“Easily” đứng trước so sánh nhất để nhấn mạnh; “in the region” cho thấy nhiều đối tượng nên dùng the largest.","wrong":{"larger":"larger là so sánh hơn, không đi với “easily” để nhấn mạnh vị trí số một trong khu vực.","the larger":"“the larger” chỉ dùng khi so sánh hai đối tượng.","more large":"“more large” sai vì tính từ ngắn large dùng -r, không dùng more."}},{"q":"Her new flat is ___ than the old one; she can hardly believe the difference.","opts":["a bit bigger","slightly big","far bigger","much big"],"a":2,"why":"Câu nói “hardly believe the difference” cho thấy chênh lệch lớn nên dùng “far bigger”.","wrong":{"a bit bigger":"“a bit bigger” chỉ chênh lệch nhỏ, không khớp với việc cô ấy khó tin vì khác biệt.","slightly big":"“slightly big” thiếu dạng so sánh hơn nên không đi với “than”.","much big":"“much big” thiếu dạng so sánh hơn nên không đi với “than”."}},{"q":"The ___ the weather became, the fewer people came to the clinic.","opts":["worse","worst","badder","more bad"],"a":0,"why":"Vế đầu cần so sánh hơn của bad; worse là dạng bất quy tắc, cùng đối xứng với “the fewer”.","wrong":{"worst":"“worst” là so sánh nhất nên không dùng trong cấu trúc hai vế này.","badder":"“badder” không tồn tại; bad có dạng so sánh hơn là worse.","more bad":"“more bad” sai vì bad có dạng so sánh hơn bất quy tắc là worse."}}]}},"discourse-markers":{"mistakes":[{"wrong":"The rent is high. Moreover, the flat is very spacious.","right":"The rent is high. However, the flat is very spacious.","bad":"Moreover","fix":"However","why":"“Moreover” chỉ thêm ý cùng hướng. Hai ý này trái chiều (giá cao, nhà rộng) nên cần “however” hoặc “on the other hand”."},{"wrong":"He didn't fail. In the contrary, he got the top mark.","right":"He didn't fail. On the contrary, he got the top mark.","bad":"In","fix":"On","why":"Cụm cố định là “on the contrary”. Người Việt hay dịch “ngược lại” thành “in the contrary”, nhưng giới từ đúng là “on”."},{"wrong":"At last, I think online learning has more benefits.","right":"In conclusion, I think online learning has more benefits.","bad":"At last","fix":"In conclusion","why":"“At last” nghĩa là cuối cùng sau một thời gian chờ đợi, không dùng để mở đoạn kết. Muốn kết luận hãy dùng “in conclusion” hoặc “to sum up”."},{"wrong":"In addition of that, the course is free.","right":"In addition to that, the course is free.","bad":"of","fix":"to","why":"Sau “in addition” dùng giới từ “to”, không dùng “of”. Mẹo nhớ: addition TO, giống “thêm vào”."},{"wrong":"Firstly of all, we need more data.","right":"First of all, we need more data.","bad":"Firstly","fix":"First","why":"Cụm cố định là “first of all”, không có “firstly of all”. “Firstly” đứng riêng thì đúng, nhưng không ghép với “of all”."},{"wrong":"On the other side, the job is poorly paid.","right":"On the other hand, the job is poorly paid.","bad":"side","fix":"hand","why":"Marker đối lập cố định là “on the other hand”. Dịch từng chữ “mặt khác” thành “side” là lỗi thường gặp."},{"wrong":"I like tea, but however I prefer coffee.","right":"I like tea, but I prefer coffee.","bad":"but however","fix":"but","why":"“But” và “however” đều báo hiệu đối lập, nên dùng cả hai là thừa. Chọn một: “but” hoặc “However,” ở đầu câu mới."},{"wrong":"I was tired. Even, I went to the party.","right":"I was tired. Even so, I went to the party.","bad":"","fix":"so","why":"Marker đúng là “even so” (dù vậy). Thiếu “so” thì câu không có nghĩa; “even” một mình mang nghĩa khác."}],"contrast":{"title":"However hay Moreover?","a":"However / On the other hand (đối lập)","b":"Moreover / What is more (thêm ý)","rows":[["Chức năng","Nêu ý trái chiều hoặc nhượng bộ với ý trước: “The plan is cheap. However, it is slow.”","Thêm một ý cùng hướng, thường mạnh hơn ý trước: “The plan is cheap. Moreover, it is fast.”"],["Văn phong","“However” trang trọng; “on the other hand” dùng được cả nói lẫn viết.","“Moreover” rất trang trọng, hợp văn viết; “what is more” và “on top of that” thân mật hơn."],["Dấu câu","Dấu chấm hoặc chấm phẩy trước, dấu phẩy sau: “...; however, ...”.","Cách dấu câu giống hệt: “...; moreover, ...” hoặc “. Moreover, ...”."],["Dấu hiệu nhận biết","Hai ý ngược nhau (cheap/expensive, good/bad), hoặc có sự nhượng bộ.","Hai ý cùng chiều, cùng tích cực hoặc cùng tiêu cực, ý sau bổ sung cho ý trước."]],"ex":[["The hotel is cheap. However, it is a long way from the centre.","The hotel is cheap. Moreover, it is right next to the beach."],["The job is demanding. On the other hand, it is well paid.","The job is demanding. What is more, it offers little training."]],"tip":"Hỏi xem ý sau “cùng chiều” hay “ngược chiều” với ý trước: cùng chiều dùng moreover, ngược chiều dùng however.","quiz":[{"q":"The apartment is convenient. ___, it is far too expensive for me.","opts":["Moreover","What is more","However","In other words"],"a":2,"why":"“However” nêu ý đối lập; “convenient” là ưu điểm còn “too expensive” là nhược điểm.","wrong":{"Moreover":"“Moreover” thêm ý cùng hướng, trong khi “too expensive” là nhược điểm trái với “convenient”.","What is more":"“What is more” cũng là marker thêm ý cùng chiều nên không hợp với ý đối lập.","In other words":"“In other words” nói lại cùng một ý, mà giá cao không phải là cách nói khác của sự tiện lợi."}},{"q":"The new app saves time. ___, it reduces errors.","opts":["Moreover","However","On the other hand","Even so"],"a":0,"why":"“Moreover” thêm một lợi ích cùng hướng; cả “saves time” và “reduces errors” đều là ưu điểm.","wrong":{"However":"“However” báo hiệu đối lập, nhưng giảm lỗi cũng là ưu điểm nên không có sự tương phản.","On the other hand":"“On the other hand” nêu mặt đối lập, trong khi ở đây là thêm một lợi ích nữa.","Even so":"“Even so” nghĩa là dù vậy, nên không phù hợp khi hai ý cùng chiều."}},{"q":"Our results are limited. ___, they point to a clear trend.","opts":["Moreover","Nevertheless","Besides","What is more"],"a":1,"why":"“Nevertheless” nhượng bộ sau một hạn chế; “limited” đối lập với “point to a clear trend”.","wrong":{"Moreover":"“Moreover” thêm ý cùng hướng, nhưng “limited” và “clear trend” có sắc thái đối lập.","Besides":"“Besides” cũng là marker thêm ý cùng chiều, không nhượng bộ như câu này cần.","What is more":"“What is more” nhấn mạnh thêm ý mạnh hơn, không diễn tả sự nhượng bộ giữa hai ý trái chiều."}},{"q":"Chọn câu có dấu câu đúng?","opts":["The test was easy, however, many students failed.","The test was easy however; many students failed.","The test was easy, but however, many students failed.","The test was easy; however, many students failed."],"a":3,"why":"Marker nối hai câu cần dấu chấm hoặc chấm phẩy ở trước và dấu phẩy ở sau.","wrong":{"The test was easy, however, many students failed.":"Hai mệnh đề độc lập bị nối bằng dấu phẩy nên bị lỗi comma splice; cần dấu chấm hoặc chấm phẩy.","The test was easy however; many students failed.":"Dấu chấm phẩy đặt sau “however” khiến marker dính vào ý trước thay vì dẫn vào ý sau.","The test was easy, but however, many students failed.":"“But” và “however” cùng đối lập nên thừa, và vẫn bị comma splice."}},{"q":"Sorry to interrupt. ___, have you seen my keys?","opts":["In conclusion","Nevertheless","By the way","To sum up"],"a":2,"why":"“By the way” báo hiệu chuyển sang chuyện phụ; “Sorry to interrupt” cho thấy câu hỏi không thuộc mạch chính.","wrong":{"In conclusion":"“In conclusion” dùng ở phần kết, không phải để chen vào một câu hỏi lạc đề.","Nevertheless":"“Nevertheless” nêu ý đối lập, trong khi câu hỏi về chìa khoá không liên quan đến ý trước.","To sum up":"“To sum up” tóm tắt ý đã nói, không dùng để chuyển sang chuyện mới."}},{"q":"He said he was a bit under the weather. ___, he was ill.","opts":["In other words","On the contrary","Nevertheless","Mind you"],"a":0,"why":"“In other words” diễn đạt lại cho rõ nghĩa; “under the weather” và “ill” có nghĩa giống nhau.","wrong":{"On the contrary":"“On the contrary” phủ nhận ý trước, nhưng ở đây vế sau chỉ nói rõ hơn “under the weather”.","Nevertheless":"“Nevertheless” nêu sự đối lập, trong khi hai vế cùng chỉ một sự thật.","Mind you":"“Mind you” là lời nhượng bộ thân mật, không dùng để giải thích lại một cách nói giảm."}},{"q":"A: The film was a bit slow. B: ___, I was gripped from start to finish.","opts":["Moreover","Finally","To sum up","Actually"],"a":3,"why":"“Actually” dùng để nhẹ nhàng đính chính hoặc phản đối; B không đồng ý với nhận xét “a bit slow”.","wrong":{"Moreover":"“Moreover” thêm ý cùng hướng, nhưng B đang không đồng ý với A.","Finally":"“Finally” là ý cuối trong một chuỗi, không dùng để phản đối ý kiến của người khác.","To sum up":"“To sum up” dùng để tóm tắt một đoạn dài, không phải để đáp lại một câu nhận xét ngắn."}},{"q":"There are risks and benefits. ___, I think the scheme should go ahead.","opts":["Firstly","All in all","By the way","Besides"],"a":1,"why":"“All in all” chốt kết luận tổng thể; manh mối là “risks and benefits” đã được cân nhắc.","wrong":{"Firstly":"“Firstly” mở đầu chuỗi ý, trong khi câu này là kết luận sau khi đã nêu cả hai phía.","By the way":"“By the way” chuyển sang chuyện phụ, không phải câu chốt lập luận.","Besides":"“Besides” thêm một ý mới, nhưng câu sau là phán đoán tổng hợp từ rủi ro và lợi ích."}}]}},"ellipsis-substitution":{"mistakes":[{"wrong":"I prefer the red shirt to the blue.","right":"I prefer the red shirt to the blue one.","bad":"blue","fix":"blue one","why":"Tính từ đứng một mình không thay được danh từ đếm được; cần “one”. Tiếng Việt có thể bỏ danh từ, tiếng Anh thì không."},{"wrong":"Will it snow tonight? I hope so not.","right":"Will it snow tonight? I hope not.","bad":"so not","fix":"not","why":"Muốn trả lời phủ định sau hope chỉ dùng “not”; không ghép “so” với “not”. Nhớ: “I hope so” hoặc “I hope not”."},{"wrong":"She said she'd call, but she didn't to.","right":"She said she'd call, but she didn't.","bad":"didn't to","fix":"didn't","why":"Sau trợ động từ “didn't” không dùng “to”. Chỉ giữ “to” khi lược sau want, love, have (to V)."},{"wrong":"Do you want to come? Yes, I'd love go.","right":"Do you want to come? Yes, I'd love to.","bad":"go","fix":"to","why":"Khi lược động từ sau “would love” phải giữ “to”. Người Việt hay bỏ luôn “to” vì tiếng Việt không có từ này."},{"wrong":"She likes tea more than I like.","right":"She likes tea more than I do.","bad":"like","fix":"do","why":"Động từ lặp lại được thay bằng trợ từ “do”, không lặp “like” khi thiếu tân ngữ. Mẫu: “than I do”."},{"wrong":"Is the clinic open today? I think no.","right":"Is the clinic open today? I don't think so.","bad":"no","fix":"so","why":"Sau think không dùng “no”; câu trả lời phủ định tự nhiên là “I don't think so”. “I think not” chỉ dùng trang trọng."},{"wrong":"I like black coffee, but she prefers white one.","right":"I like black coffee, but she prefers white.","bad":"white one","fix":"white","why":"Danh từ không đếm được như coffee không đi với “one”. Người Việt hay thêm “cái” nên dịch sang “one” cho mọi danh từ."},{"wrong":"I didn't want to go, but I had.","right":"I didn't want to go, but I had to.","bad":"","fix":"to","why":"Sau “had” mang nghĩa bắt buộc phải giữ “to” dù lược động từ chính. Bỏ “to” làm câu thiếu nghĩa bắt buộc."}],"contrast":{"title":"one hay it?","a":"one(s)","b":"it / them","rows":[["Đối tượng được nhắc","Một vật cùng loại nhưng khác, chưa xác định: “I need a pen. Do you have one?”","Chính vật vừa nhắc: “I lost my pen. Have you seen it?”"],["Số lượng","Số ít “one”, số nhiều “ones”: “the red ones”","Số ít “it”, số nhiều “them”: “I like them”"],["Đi với tính từ","Có thể đi sau tính từ hoặc the: “a bigger one”, “the old ones”","Không đi sau tính từ: không nói “a bigger it”"],["Danh từ không đếm được","Không dùng; lặp danh từ hoặc bỏ: “I prefer black coffee, not white.”","Dùng được khi chỉ chính vật đó: “This milk is old; throw it away.”"]],"ex":[["I need a charger. Do you have one?","I need my charger. Do you have it?"],["The older tablets work; the newer ones crash.","The new tablets arrived, and I tested them."]],"tip":"Nhắc lại chính vật đó thì dùng it/them; chỉ cùng loại nhưng khác vật thì dùng one/ones.","quiz":[{"q":"My pen is missing. Have you seen ___?","opts":["one","ones","its","it"],"a":3,"why":"Câu nói về chính cây bút của tôi nên dùng “it”, không phải một cây bút khác.","wrong":{"one":"“one” chỉ một cây bút khác, nhưng ở đây đang tìm đúng cây bút của mình.","ones":"“ones” là số nhiều, không khớp với “My pen”.","its":"“its” là tính từ sở hữu nên không đứng làm tân ngữ."}},{"q":"I don't have a charger. Can I borrow ___?","opts":["it","one","ones","them"],"a":1,"why":"Người nói chưa có cái nào và mượn một cái bất kỳ, nên dùng “one”.","wrong":{"it":"“it” sẽ chỉ chiếc sạc cụ thể đã nhắc, nhưng người nói không có chiếc nào.","ones":"“ones” là số nhiều, trong khi “a charger” là số ít.","them":"“them” là số nhiều, không khớp với “a charger”."}},{"q":"The report is on my desk. Please bring ___ to the meeting.","opts":["one","ones","it","some"],"a":2,"why":"Bản báo cáo cụ thể đã được nhắc nên thay bằng “it”.","wrong":{"one":"“one” chỉ một bản báo cáo khác, trong khi người nói muốn đúng bản trên bàn.","ones":"“ones” là số nhiều, không khớp với “The report”.","some":"“some” dùng với danh từ không đếm được hoặc số nhiều, và không chỉ đúng bản báo cáo ấy."}},{"q":"I like the blue shirts, but not the green ___.","opts":["ones","one","it","them"],"a":0,"why":"Danh từ bị lược là “shirts” số nhiều nên cần “ones” sau “the green”.","wrong":{"one":"“one” là số ít, không khớp với “shirts” số nhiều.","it":"“it” không đứng sau “the green” để thay danh từ.","them":"“them” là đại từ tân ngữ nên không đứng sau “the green” như một cụm danh từ."}},{"q":"Will you be at the lecture? I hope ___.","opts":["it so","to so","so","that"],"a":2,"why":"“I hope so” là cụm cố định thay cho mệnh đề “I'll be at the lecture”.","wrong":{"it so":"“it so” thêm “it” thừa, làm cụm cố định bị sai.","to so":"“to so” ghép hai từ không đi cùng nhau.","that":"“that” cần một mệnh đề phía sau mới tạo câu đầy đủ."}},{"q":"He said he would help, and he ___.","opts":["made","did","was","does"],"a":1,"why":"Trợ từ “did” thay cho “helped” đã nhắc, cùng thì quá khứ như “said”.","wrong":{"made":"“made” không thay được động từ “help” và nghĩa không khớp.","was":"“was” cần tính từ hoặc V-ing, không thay được động từ thường.","does":"“does” là hiện tại, không khớp với “said … would” ở quá khứ."}},{"q":"I haven't read it yet, but I'd like ___.","opts":["it","so","that","to"],"a":3,"why":"Sau “would like” có thể lược động từ và giữ “to” thay cho “to read it”.","wrong":{"it":"“I'd like it” nghĩa là thích nó, không phải muốn đọc.","so":"“so” chỉ đi với think, hope, suppose, không đi với “would like”.","that":"“that” cần được hiểu như tân ngữ, không thay cho cụm “to read it”."}},{"q":"Is the café open? I don't think ___.","opts":["so","not","it","that"],"a":0,"why":"Phủ nhận ý kiến bằng “I don't think so”; “so” thay cho mệnh đề “it is open”.","wrong":{"not":"“not” sau “don't think” tạo phủ định kép nên sai.","it":"“it” không thay thế được cả mệnh đề sau think.","that":"“that” cần một mệnh đề đầy đủ phía sau nó."}}]}},"hedging-modality":{"mistakes":[{"wrong":"The report is seem to be accurate.","right":"The report seems to be accurate.","bad":"is seem","fix":"seems","why":"“Seem” là động từ thường, tự chia theo chủ ngữ, không ghép với “be”. Người Việt hay thêm “is” vì quen “thì/là”."},{"wrong":"Children are liable get bored quickly.","right":"Children are liable to get bored quickly.","bad":"","fix":"to","why":"“Be liable” đi với “to V”. Thiếu “to” là lỗi hay gặp vì tiếng Việt không có từ nối tương đương."},{"wrong":"It is probably that the fee will rise.","right":"It is probable that the fee will rise.","bad":"probably","fix":"probable","why":"Sau “it is” cần tính từ “probable” (hoặc “likely”), không dùng trạng từ “probably”. Trạng từ đứng trước động từ: “the fee will probably rise”."},{"wrong":"This may possible be the cause.","right":"This may possibly be the cause.","bad":"possible","fix":"possibly","why":"Trạng từ “possibly” bổ nghĩa cho động từ nên phải có đuôi -ly. Người học hay dùng tính từ vì tiếng Việt chỉ có một từ “có thể”."},{"wrong":"In the most cases, pain disappears quickly.","right":"In most cases, pain disappears quickly.","bad":"the most","fix":"most","why":"Cụm rào đón cố định là “in most cases” và không có “the”. “The most” chỉ dùng với nghĩa so sánh nhất."},{"wrong":"I wonder if could you check my essay.","right":"I wonder if you could check my essay.","bad":"could you","fix":"you could","why":"Sau “I wonder if” là câu hỏi gián tiếp nên trật tự là chủ ngữ + động từ, không đảo như câu hỏi thẳng."},{"wrong":"The data are suggested that sleep matters.","right":"The data suggest that sleep matters.","bad":"are suggested","fix":"suggest","why":"“Suggest” ở đây là động từ chủ động với chủ ngữ là dữ liệu. Không dùng bị động “are suggested that”."},{"wrong":"To some extents, stress affects results.","right":"To some extent, stress affects results.","bad":"extents","fix":"extent","why":"Trong cụm cố định “to some extent”, danh từ “extent” luôn ở số ít, dù ý nghĩa là nhiều mức độ."}],"contrast":{"title":"suggest hay prove?","a":"suggest / indicate / imply (thận trọng)","b":"prove / show / confirm (chắc chắn)","rows":[["Mức độ chắc chắn","Chỉ gợi ý, bằng chứng chưa đủ: “The data suggest…”","Khẳng định mạnh, bằng chứng đầy đủ: “The data prove…”"],["Khi nào dùng","Nghiên cứu nhỏ, kết quả sơ bộ, báo cáo lâm sàng","Chứng minh toán học, kết quả đã được kiểm chứng rộng"],["Đi kèm","Thường đi với “may, might, seem, tend”","Ít đi với từ rào đón, thường có “clearly, conclusively”"],["Rủi ro","An toàn, khó bị phản bác","Dễ bị coi là nói quá nếu thiếu bằng chứng"]],"ex":[["The results suggest that sleep may improve memory.","The results prove that sleep improves memory."],["The survey indicates a link between diet and mood.","The survey proves that diet causes mood changes."]],"tip":"Chưa chắc thì “suggest”; đã chứng minh hoàn toàn mới “prove”. Trong y khoa, hãy chọn “suggest” trước.","quiz":[{"q":"The sample was small, so the data can only ___ a trend.","opts":["prove","suggest","guarantee","settle"],"a":1,"why":"Mẫu nhỏ chỉ đủ để gợi ý, nên dùng “suggest”. “Can only” nhấn mạnh giới hạn của bằng chứng.","wrong":{"prove":"“Prove” là khẳng định chắc chắn, không hợp với “small sample” và “can only”.","guarantee":"“Guarantee” là bảo đảm tuyệt đối, không dùng với dữ liệu mẫu nhỏ.","settle":"“Settle a trend” không tự nhiên; “settle” dùng với tranh luận hoặc câu hỏi, không dùng với xu hướng."}},{"q":"In mathematics, a theorem must be ___ by logical steps, not merely suggested by examples.","opts":["proved","indicated","hinted","implied"],"a":0,"why":"Ở đây cần mức khẳng định cao nhất nên chọn “proved”. Vế “not merely suggested” báo hiệu sự đối lập.","wrong":{"indicated":"“Indicated” là chỉ ra một dấu hiệu, trong khi toán học yêu cầu chứng minh chặt chẽ.","hinted":"“Hinted” chỉ là gợi ý nhẹ, đúng điều câu muốn loại bỏ.","implied":"“Implied” là hàm ý, không phải chứng minh bằng các bước logic."}},{"q":"A cautious clinical report would say: 'The drug ___ to lower blood pressure in older patients.'","opts":["is certain","surely","seems","always"],"a":2,"why":"“Seem to V” cho phép nói giảm mà vẫn đúng ngữ pháp. Các lựa chọn khác hoặc khẳng định tuyệt đối hoặc sai cấu trúc.","wrong":{"is certain":"“Is certain to” cần chủ ngữ là người hoặc sự việc có thể bảo đảm, và nó không hề rào đón.","surely":"“Surely” là trạng từ, không thể đứng ngay trước “to lower” như một động từ.","always":"“Always” là trạng từ tuyệt đối, đi ngược mục đích nói thận trọng."}},{"q":"Which verb is the most cautious in: 'The figures ___ that costs have fallen'?","opts":["prove","show","confirm","imply"],"a":3,"why":"“Imply” chỉ ngụ ý, yếu nhất trong bốn động từ. Vì vậy nó là lựa chọn rào đón nhất cho câu này.","wrong":{"prove":"“Prove” là mức khẳng định mạnh nhất, nên không phải lựa chọn thận trọng.","show":"“Show” cho rằng bằng chứng rõ ràng, mạnh hơn nhiều so với “imply”.","confirm":"“Confirm” xác nhận điều đã nghi ngờ nên mạnh hơn “imply”."}},{"q":"It ___ that the clinic is understaffed, though nobody has confirmed it.","opts":["would seem","would seems","would seem to","would be seem"],"a":0,"why":"“It would seem that…” là cách nói giảm với chủ ngữ giả “it”. Vế “nobody has confirmed it” củng cố ý chưa chắc.","wrong":{"would seems":"Sau would phải là động từ nguyên mẫu, không thêm -s vào “seems”.","would seem to":"Sau “seem to” phải có động từ, nhưng ở đây tiếp theo là mệnh đề “that…”.","would be seem":"“Be seem” không tồn tại; “seem” không đi với be."}},{"q":"Patients ___ to feel tired after the first week.","opts":["are tend","tends","tend","tending"],"a":2,"why":"“Tend to V” nói về xu hướng và chia theo chủ ngữ. “Patients” số nhiều nên giữ “tend”.","wrong":{"are tend":"“Tend” không đi sau “are”, vì nó là động từ thường.","tends":"Chủ ngữ “patients” số nhiều nên không thêm -s.","tending":"Dạng V-ing đứng một mình không làm động từ chính trong câu hiện tại này."}},{"q":"I was just ___ whether we could swap shifts on Friday.","opts":["wonder","wondered","to wonder","wondering"],"a":3,"why":"“I was (just) wondering whether…” là cách hỏi mềm, lịch sự. Quá khứ tiếp diễn làm lời đề nghị bớt thẳng.","wrong":{"wonder":"Sau “was” cần V-ing, không dùng nguyên mẫu “wonder”.","wondered":"“Was wondered” là bị động và không phù hợp với ý định hỏi.","to wonder":"“Was to wonder” không phải dạng tiếp diễn và đổi nghĩa thành kế hoạch."}},{"q":"___, the plan has worked, although a few schools still struggle.","opts":["By large and","By and large","At large","In large"],"a":1,"why":"“By and large” nghĩa là nhìn chung, rào đón bằng cách nói đúng với phần lớn trường hợp. Vế sau “a few schools” là ngoại lệ.","wrong":{"By large and":"Trật tự từ trong cụm cố định bị sai; phải là “by and large”.","At large":"“At large” nghĩa là đang bỏ trốn hoặc nói chung, không phải “nói chung là” ở nghĩa này.","In large":"“In large” cần danh từ như “in large part”, không đứng một mình."}}]}},"nominalisation":{"mistakes":[{"wrong":"The increase of prices worried shoppers.","right":"The increase in prices worried shoppers.","bad":"of","fix":"in","why":"Với sự tăng giảm của giá, số liệu, tỷ lệ, dùng “increase in”. Tiếng Việt nói “sự tăng của” nên dễ dịch thành “of”."},{"wrong":"The decide was announced yesterday.","right":"The decision was announced yesterday.","bad":"decide","fix":"decision","why":"Sau “the” cần danh từ, không dùng động từ nguyên mẫu. Danh từ của “decide” là “decision”."},{"wrong":"Because of the prices rose, sales fell.","right":"Because of the rise in prices, sales fell.","bad":"rose","fix":"rise","why":"“Because of” là giới từ nên đi với cụm danh từ, không đi với mệnh đề “prices rose”. Dùng “because” nếu muốn giữ mệnh đề."},{"wrong":"There was a lack for evidence.","right":"There was a lack of evidence.","bad":"for","fix":"of","why":"Danh từ “lack” đi với giới từ “of”, không phải “for”. Tiếng Việt “thiếu cho” không tồn tại, nhưng “need for” khiến người học nhầm."},{"wrong":"The difference between the two groups is importance.","right":"The difference between the two groups is important.","bad":"importance","fix":"important","why":"Sau “is” cần tính từ khi mô tả. Đừng đặt danh từ “importance” vào chỗ của tính từ."},{"wrong":"A growing amount of students use online libraries.","right":"A growing number of students use online libraries.","bad":"amount","fix":"number","why":"“Students” đếm được nên dùng “number”. “Amount” chỉ dùng với danh từ không đếm được."},{"wrong":"Failing of the test upset her.","right":"Failure of the test upset her.","bad":"Failing","fix":"Failure","why":"Muốn danh từ chỉ việc thất bại, dùng “failure”. “Failing” là dạng -ing và không đi với “of” như danh từ."},{"wrong":"The development in the vaccine took years.","right":"The development of the vaccine took years.","bad":"in","fix":"of","why":"“The development of + đối tượng” chỉ việc phát triển cái gì. “In” dùng cho thay đổi số liệu, không dùng ở đây."}],"contrast":{"title":"Mệnh đề hay cụm danh từ?","a":"Mệnh đề (động từ)","b":"Cụm danh từ (danh từ hoá)","rows":[["Văn phong","Tự nhiên, thân mật, hợp văn nói và kể chuyện: “Prices rose, so people spent less.”","Trang trọng, súc tích, hợp văn viết học thuật: “The rise in prices reduced spending.”"],["Cấu trúc","Chủ ngữ + động từ, nối bằng because, so, when, after.","Danh từ + giới từ (of, in, for, to), nối bằng because of, due to, as a result of."],["Người làm hành động","Nói rõ ai làm: “The council decided to close it.”","Có thể lược bỏ người làm: “The decision to close it was criticised.”"],["Rủi ro","Dễ lặp nhiều “and/so/because” khi câu dài.","Dễ quá nặng và mơ hồ nếu chồng nhiều “of”."]],"ex":[["Because the company expanded quickly, it hired more staff.","The rapid expansion of the company led to more hiring."],["We decided to wait for the results.","Our decision to wait for the results was sensible."]],"tip":"Viết nói thì dùng động từ, viết báo cáo thì nén thành danh từ, nhưng đừng để câu nặng quá mức.","quiz":[{"q":"Because the government raised taxes, ___ .","opts":["spending fell sharply","the sharp fall of spending","a sharp fall in spending being","falling sharply spending"],"a":0,"why":"Sau “Because + mệnh đề” cần một mệnh đề chính có chủ ngữ và động từ chia, nên chọn “spending fell sharply”.","wrong":{"the sharp fall of spending":"Cụm danh từ không có động từ nên không tạo thành mệnh đề chính sau “Because + mệnh đề”.","a sharp fall in spending being":"Dạng -ing “being” làm câu dở dang, không có động từ chính hoàn chỉnh.","falling sharply spending":"Trật tự từ sai và thiếu động từ chia, nên không phải mệnh đề chính."}},{"q":"In a formal report, the best version of “Many people lost their jobs, so poverty increased” is: ___ .","opts":["The lose of jobs led to an increase in poverty.","The loss of jobs led to an increase in poverty.","The loss of jobs led to increase of poverty.","Losing of jobs led to an increase in poverty."],"a":1,"why":"Báo cáo trang trọng ưa cụm danh từ “the loss of jobs” và “an increase in poverty”; các lựa chọn khác sai dạng từ hoặc giới từ.","wrong":{"The lose of jobs led to an increase in poverty.":"“Lose” là động từ; sau “The” cần danh từ “loss”.","The loss of jobs led to increase of poverty.":"Thiếu mạo từ “an” và dùng sai giới từ “of”; mẫu đúng là “an increase in”.","Losing of jobs led to an increase in poverty.":"“Losing of” không tự nhiên; danh từ đúng là “loss” và nên có “the”."}},{"q":"In casual speech, which is the most natural? “___ the exam, I felt relieved.”","opts":["Following the completion of","On the completion of finishing","After I finished","Upon the finish of"],"a":2,"why":"Lời nói tự nhiên dùng mệnh đề “After I finished”; các cụm danh từ kia nặng và không tự nhiên với “the exam” trong câu này.","wrong":{"Following the completion of":"Quá trang trọng cho lời nói thân mật, nhưng thiếu cả cấu trúc đúng trong câu này.","On the completion of finishing":"Lặp nghĩa “completion” và “finishing”, không tự nhiên.","Upon the finish of":"“The finish of” không dùng cho kỳ thi; sai cả kết hợp từ lẫn văn phong."}},{"q":"___ the exam was delayed, several students became anxious.","opts":["Because of","Due to","As a result of","Because"],"a":3,"why":"Có mệnh đề “the exam was delayed” nên cần liên từ “because”; các cụm còn lại là giới từ và chỉ đi với danh từ.","wrong":{"Because of":"“Because of” là giới từ nên không đi với mệnh đề “the exam was delayed”.","Due to":"“Due to” cần cụm danh từ, không đi với mệnh đề có động từ chia.","As a result of":"Cũng là cụm giới từ, cần danh từ phía sau chứ không phải mệnh đề."}},{"q":"There has been a steady increase ___ the number of online learners.","opts":["in","of","for","on"],"a":0,"why":"Mẫu cố định là “an increase in the number of”; giới từ khác không tự nhiên.","wrong":{"of":"Với sự tăng của số lượng, giới từ chuẩn là “in”, không dùng “of” trong ngữ cảnh này.","for":"“Increase for” không phải mẫu chuẩn để chỉ đại lượng tăng.","on":"“Increase on” không dùng cho số lượng người học; giới từ chuẩn là “in”."}},{"q":"The ___ of the committee to postpone the meeting surprised everyone.","opts":["decide","decision","decisive","deciding"],"a":1,"why":"Sau “The” cần danh từ chủ ngữ; “decision” là danh từ của “decide”, và “decision to postpone” là mẫu quen thuộc.","wrong":{"decide":"Là động từ, không đứng sau “The” làm danh từ chủ ngữ.","decisive":"Là tính từ, không thể là danh từ chủ ngữ ở đây.","deciding":"Là dạng -ing, không đi với “The ... of the committee to” như danh từ."}},{"q":"Which sentence avoids over-nominalising?","opts":["We chose to cancel the trip because it was raining.","Our choice was the cancellation of the trip due to the occurrence of rain.","The cancellation of the trip was our choice owing to the occurrence of rain.","The raining caused the choice of cancelling of the trip."],"a":0,"why":"Mệnh đề đơn giản “We chose to cancel ... because it was raining” rõ ràng nhất; các phương án kia chất đống danh từ.","wrong":{"Our choice was the cancellation of the trip due to the occurrence of rain.":"Chuỗi danh từ hoá quá nặng, câu khó đọc dù đúng ngữ pháp, nên không hợp mục tiêu rõ ràng.","The cancellation of the trip was our choice owing to the occurrence of rain.":"Vẫn dùng nhiều danh từ nặng nề, khó đọc hơn mệnh đề đơn giản.","The raining caused the choice of cancelling of the trip.":"Dạng danh từ sai và lặp “of”, câu vừa nặng vừa sai."}},{"q":"A growing ___ of patients prefer online appointments.","opts":["amount","quantity","deal","number"],"a":3,"why":"“A growing number of + danh từ đếm được số nhiều” là mẫu chuẩn; “patients” đếm được nên cần “number”.","wrong":{"amount":"“Amount” chỉ đi với danh từ không đếm được, mà “patients” đếm được.","quantity":"“Quantity” không đi với “a growing ... of patients”.","deal":"“Deal” cần “great deal of” và đi với danh từ không đếm được."}}]}},"past-perfect-continuous":{"mistakes":[{"wrong":"She was tired because she has been studying all day.","right":"She was tired because she had been studying all day.","bad":"has","fix":"had","why":"Câu kể ở quá khứ nên nguyên nhân phải lùi về “had been”. Đừng dùng “has been” chỉ vì tiếng Việt không chia thì."},{"wrong":"I had been knowing him for ten years.","right":"I had known him for ten years.","bad":"been knowing","fix":"known","why":"“know” là động từ trạng thái, không dùng tiếp diễn. Dùng “had known”, dù có “for ten years”."},{"wrong":"They had been building the bridge since three years.","right":"They had been building the bridge for three years.","bad":"since","fix":"for","why":"“for” đi với khoảng thời gian (three years), “since” đi với mốc. Tiếng Việt đều nói “từ”, nên dễ lẫn."},{"wrong":"He had been working here for 2015 when I joined.","right":"He had been working here since 2015 when I joined.","bad":"for","fix":"since","why":"“2015” là một mốc thời gian nên cần “since”, không phải “for”."},{"wrong":"How long you had been waiting before he came?","right":"How long had you been waiting before he came?","bad":"you had","fix":"had you","why":"Câu hỏi phải đảo trợ động từ “had” lên trước chủ ngữ. Tiếng Việt không đảo nên dễ giữ nguyên trật tự."},{"wrong":"She had been write the report for hours.","right":"She had been writing the report for hours.","bad":"write","fix":"writing","why":"Sau “had been” luôn là V-ing, không dùng động từ nguyên mẫu."},{"wrong":"I had been reading three chapters before dinner.","right":"I had read three chapters before dinner.","bad":"been reading","fix":"read","why":"Có số lượng (three chapters) nhấn kết quả hoàn tất, nên dùng quá khứ hoàn thành đơn, không dùng tiếp diễn."},{"wrong":"She had working there for years when the firm closed.","right":"She had been working there for years when the firm closed.","bad":"","fix":"been","why":"Quá khứ hoàn thành tiếp diễn cần đủ “had been + V-ing”. Thiếu “been” là lỗi hay gặp khi nói nhanh."}],"contrast":{"title":"had been + V-ing hay had + V-ed?","a":"had been + V-ing","b":"had + V-ed","rows":[["Trọng tâm","Quá trình kéo dài hoặc nguyên nhân: had been working for hours","Kết quả hoặc việc đã hoàn tất: had finished the report"],["Số lượng","Không đi với số lần hay số lượng cụ thể","Đi với số lượng: had written ten pages, had seen it twice"],["Hành động chưa xong","Có thể chưa kết thúc tại mốc: had been waiting when he came","Thường đã xong trước mốc quá khứ: had waited, then left"],["Động từ trạng thái","Không dùng với know, own, believe, understand","Dùng được: had known, had owned, had believed"]],"ex":[["She had been painting the fence all morning, so her arms ached.","She had painted the fence by noon, so she went home."],["They had been revising for hours when the lights went out.","They had revised four units before the lights went out."]],"tip":"Thấy quá trình, thời lượng, nguyên nhân thì chọn had been V-ing; thấy kết quả, số lượng, động từ trạng thái thì chọn had V-ed.","quiz":[{"q":"By lunchtime she ___ twelve patients, and she was still not finished.","opts":["had been seeing","had seen","was seen","has seen"],"a":1,"why":"Có số lượng twelve patients trước mốc quá khứ nên dùng quá khứ hoàn thành đơn had seen.","wrong":{"had been seeing":"Số lượng twelve patients nhấn kết quả đã hoàn tất, nên không dùng dạng tiếp diễn.","was seen":"Dạng bị động sai nghĩa vì chủ ngữ she là bác sĩ khám bệnh nhân.","has seen":"Mốc by lunchtime là quá khứ nên hiện tại hoàn thành lệch thì."}},{"q":"Her hands were black with oil: she ___ the engine all morning.","opts":["had been repairing","had repaired","repaired","has repaired"],"a":0,"why":"All morning nhấn quá trình kéo dài, và dầu trên tay là kết quả nhìn thấy, nên dùng had been repairing.","wrong":{"had repaired":"Had repaired nhấn việc đã xong, trong khi all morning cho thấy quá trình kéo dài gây ra dầu trên tay.","repaired":"Quá khứ đơn không nối quá trình trước đó với kết quả nhìn thấy lúc đó.","has repaired":"Hiện tại hoàn thành lệch thì với câu mô tả ở quá khứ (were black)."}},{"q":"The band ___ the same song three times before the audience left.","opts":["had been playing","was playing","had played","has played"],"a":2,"why":"Số lần three times đi với quá khứ hoàn thành đơn had played để nói về sự kiện đếm được trước mốc.","wrong":{"had been playing":"Có số lần three times nên nhấn kết quả đếm được, không dùng tiếp diễn.","was playing":"Quá khứ tiếp diễn không cho thấy bài hát đã được chơi đủ ba lần trước khi khán giả rời đi.","has played":"Mốc before the audience left ở quá khứ nên hiện tại hoàn thành không hợp."}},{"q":"They ___ for two hours when the fire alarm went off.","opts":["negotiated","were negotiating","have been negotiating","had been negotiating"],"a":3,"why":"For two hours và hành động bị cắt ngang cho thấy quá trình kéo dài trước mốc: had been negotiating.","wrong":{"negotiated":"Quá khứ đơn không diễn tả quá trình hai giờ đang kéo dài khi chuông báo cháy xen vào.","were negotiating":"Quá khứ tiếp diễn không đi tự nhiên với for two hours để tính thời lượng đến mốc.","have been negotiating":"Chuông báo cháy ở quá khứ nên hiện tại hoàn thành tiếp diễn không hợp."}},{"q":"While the rescue team ___ the slope, a second avalanche fell.","opts":["crosses","was crossing","has crossed","had been crossing"],"a":1,"why":"While + hành động nền bị sự kiện quá khứ đơn cắt ngang dùng quá khứ tiếp diễn was crossing.","wrong":{"crosses":"Thì hiện tại không hợp với câu kể ở quá khứ (fell).","has crossed":"Hiện tại hoàn thành lệch thì và không diễn tả bối cảnh đang diễn ra.","had been crossing":"While nêu bối cảnh song song, không lùi về trước mốc nên quá khứ tiếp diễn mới đúng."}},{"q":"He ___ the answer all along, but he said nothing.","opts":["had been knowing","was knowing","had known","has known"],"a":2,"why":"Know là động từ trạng thái, và all along kéo dài trước mốc said nothing, nên dùng had known.","wrong":{"had been knowing":"Know là động từ trạng thái nên không chia dạng tiếp diễn.","was knowing":"Động từ trạng thái không dùng tiếp diễn, dù ở quá khứ.","has known":"Hiện tại hoàn thành lệch thì với said ở quá khứ."}},{"q":"She had been studying nursing ___ 2019 when the course changed.","opts":["since","for","from since","during"],"a":0,"why":"Since đi với mốc thời gian (2019), còn for dùng với khoảng thời gian như five years.","wrong":{"for":"For cần khoảng thời gian, trong khi 2019 là một mốc thời gian cụ thể.","from since":"Không tồn tại cụm from since trong tiếng Anh chuẩn.","during":"During đi với danh từ chỉ giai đoạn và không đi với mốc năm như 2019."}},{"q":"___ in the lab long before the power cut happened?","opts":["Have you been working","Were you been working","You had been working","Had you been working"],"a":3,"why":"Hỏi thời lượng trước mốc quá khứ dùng Had + S + been + V-ing và đảo had lên đầu.","wrong":{"Have you been working":"Mốc the power cut happened ở quá khứ nên không dùng have you been.","Were you been working":"Were không kết hợp với been; sai cấu trúc trợ động từ.","You had been working":"Câu hỏi cần đảo trợ động từ lên đầu, không giữ trật tự câu khẳng định."}}]}},"reporting-verbs":{"mistakes":[{"wrong":"She suggested me to see a dentist.","right":"She suggested that I see a dentist.","bad":"me to","fix":"that I","why":"“suggest” không nhận “O + to V”. Tiếng Việt “gợi ý cho tôi đi” dễ khiến ta dịch sát; hãy dùng “that I see” hoặc “seeing”."},{"wrong":"He said me that he was tired.","right":"He told me that he was tired.","bad":"said","fix":"told","why":"“say” không đứng trực tiếp trước người nghe. Có người nghe làm tân ngữ thì dùng “tell”, hoặc nói “said to me”."},{"wrong":"They denied to take the money.","right":"They denied taking the money.","bad":"to take","fix":"taking","why":"“deny” đi với V-ing vì nói về việc đã làm. “to V” chỉ dùng với promise, refuse, offer… nói về ý định."},{"wrong":"The company refused paying the bill.","right":"The company refused to pay the bill.","bad":"paying","fix":"to pay","why":"“refuse” thuộc nhóm đi với “to V”, cùng nhóm promise, offer, threaten. Đừng dùng V-ing sau những động từ này."},{"wrong":"She apologised me for being late.","right":"She apologised to me for being late.","bad":"me","fix":"to me","why":"“xin lỗi tôi” trong tiếng Việt có tân ngữ trực tiếp, nhưng tiếng Anh cần “apologise to + người”."},{"wrong":"They blamed him of losing the keys.","right":"They blamed him for losing the keys.","bad":"of","fix":"for","why":"“blame O for” còn “accuse O of”. Hai động từ gần nghĩa nhưng giới từ khác nhau, dễ nhầm."},{"wrong":"The doctor advised to rest for a week.","right":"The doctor advised me to rest for a week.","bad":"","fix":"me","why":"“advise” cần tân ngữ chỉ người trước “to V”. Tiếng Việt có thể bỏ “tôi” nhưng tiếng Anh thì không."},{"wrong":"She warned me don't touch the machine.","right":"She warned me not to touch the machine.","bad":"don't","fix":"not to","why":"Câu tường thuật dùng “not to V” sau “warn + O”, không giữ nguyên dạng mệnh lệnh phủ định “don't”."}],"contrast":{"title":"say hay tell?","a":"say","b":"tell","rows":[["Người nghe","Không cần người nghe; muốn nêu thì dùng “say to + người”","Luôn cần người nghe ngay sau: tell me, tell the class"],["Theo sau","Lời nói hoặc mệnh đề: say “hello”, say (that) it is ready","Người + that/to V: tell her (that) it is ready, tell her to wait"],["Cụm cố định","say hello, say sorry, say a few words","tell the truth, tell a lie, tell a story, tell the time"],["Mệnh lệnh gián tiếp","Không dùng “say + O + to V”","Tell + O + (not) to V: told us not to enter"]],"ex":[["She said (that) the results were ready.","She told us (that) the results were ready."],["The nurse said to him that he could go home.","The nurse told him to go home."]],"tip":"Tell luôn có người nghe đi liền sau; say thì không, trừ khi thêm “to + người”.","quiz":[{"t":"c","q":"She ___ me that the clinic opens at eight.","opts":["said","told","spoke","explained"],"a":1,"why":"Sau chỗ trống có tân ngữ người “me”, nên phải dùng “tell”: “told me that…”.","wrong":{"said":"“said” không đứng trước tân ngữ “me”; phải là “said to me” hoặc dùng “told”.","spoke":"“spoke” không dùng để thuật lại một thông tin kèm mệnh đề that.","explained":"“explained me” sai vì explain cần “to me”, không nhận tân ngữ người trực tiếp."}},{"t":"c","q":"He ___ that he would be late, but he gave no reason.","opts":["said","told","spoke","asked"],"a":0,"why":"Không có người nghe sau động từ nên dùng “say that…”; “tell” cần tân ngữ chỉ người.","wrong":{"told":"“told that” thiếu tân ngữ người nghe; “tell” luôn cần “told us/her that”.","spoke":"“spoke that” không đúng; “speak” không đi với mệnh đề that.","asked":"“asked that” có nghĩa yêu cầu và không hợp với việc báo tin sẽ đến muộn."}},{"t":"c","q":"The guide ___ the group to keep together.","opts":["said","explained","told","suggested"],"a":2,"why":"Cấu trúc “O + to V” cần động từ như tell, ask, advise; vì vậy chỉ “told” phù hợp ở đây.","wrong":{"said":"“said the group to keep” sai, “say” không nhận cấu trúc O + to V.","explained":"“explained the group to keep” sai; explain không đi với O + to V.","suggested":"“suggested the group to keep” sai; suggest không dùng O + to V."}},{"t":"c","q":"My grandfather loves to ___ stories about his village.","opts":["say","talk","speak","tell"],"a":3,"why":"“tell a story” là cụm cố định, giống tell the truth, tell a lie, tell the time.","wrong":{"say":"“say stories” không tự nhiên; “say” đi với lời nói cụ thể như “say hello”.","talk":"“talk stories” không đúng; talk đi với about hoặc to, không nhận tân ngữ trực tiếp là truyện.","speak":"“speak stories” không phải cụm từ cố định trong tiếng Anh."}},{"t":"c","q":"The committee accused the trainee ___ the patient notes.","opts":["of forgetting","for forgetting","to forget","that forgetting"],"a":0,"why":"Cấu trúc cố định là “accuse O of + V-ing”, giống “accused him of stealing”.","wrong":{"for forgetting":"“accuse” không đi với “for”; giới từ cố định là “of”.","to forget":"“accuse O to V” không tồn tại; sau giới từ phải có V-ing.","that forgetting":"“that” cần một mệnh đề đầy đủ, mà “forgetting” chỉ là V-ing."}},{"t":"c","q":"He promised ___ the report by Monday.","opts":["finishing","to finish","me finishing","that finish"],"a":1,"why":"“promise + to V” là mẫu cố định cho lời hứa hoặc cam kết, như refuse, offer, threaten.","wrong":{"finishing":"“promise” không đi với V-ing mà đi với “to V” để nói về ý định.","me finishing":"“promise me finishing” sai; nếu có tân ngữ thì vẫn là “promised me to finish” và rất không tự nhiên.","that finish":"“that finish” thiếu chủ ngữ; muốn dùng that thì phải là “that he would finish”."}},{"t":"c","q":"They congratulated the team ___ the national award.","opts":["at winning","to win","of winning","on winning"],"a":3,"why":"Mẫu câu đúng là “congratulate O on + V-ing/danh từ”, giống “congratulate her on her exam results”.","wrong":{"at winning":"“at” không đi với congratulate; giới từ cố định là “on”.","to win":"“to win” không đúng, vì sau “congratulate O” cần giới từ + V-ing.","of winning":"“of” dùng với accuse, không dùng với congratulate."}},{"t":"c","q":"The lifeguard warned the children ___ in the deep end.","opts":["don't swim","to not swimming","not to swim","not swim"],"a":2,"why":"Sau “warn + O” ta dùng “(not) to V”; phủ định đặt “not” ngay trước “to”.","wrong":{"don't swim":"Câu tường thuật không giữ nguyên mệnh lệnh “don't swim” sau “warned the children”.","to not swimming":"“to not swimming” trộn lẫn to V và V-ing nên sai ngữ pháp.","not swim":"Thiếu “to”; sau “warn + O” phải có “(not) to V”."}}]}}};
  const ORDER = [["third-conditional","modals-past","past-perfect-continuous","reporting-verbs","relative-nondefining","passive-reporting","linking","comparison-advanced","indirect-questions","articles-advanced","adjective-gradability","causative","future-perfect","subjunctive-formal"],["mixed-conditionals","inversion","participle-clauses","cleft-sentences","adverbial-clauses","nominalisation","ellipsis-substitution","hedging-modality","discourse-markers"]];
  const UNITMAP = {"past-perfect-continuous":"b2-03","reporting-verbs":"b2-05","comparison-advanced":"b2-07","adjective-gradability":"b2-10","articles-advanced":"b2-12","nominalisation":"c1-03","discourse-markers":"c1-05","hedging-modality":"c1-07","adverbial-clauses":"c1-08","ellipsis-substitution":"c1-09"};
  NEW.forEach(g => GRAMMAR.push(g));
  Object.assign(GRAMMAR_BANK, BANK); Object.assign(GRAMMAR_THEORY, THEORY); Object.assign(GRAMMAR_GX, GX_ADD);
  const rank = Object.fromEntries(ORDER.flatMap(l => l.map((id, i) => [id, i])));
  const lv = { A1: 1, A2: 2, B1: 3, B2: 4, C1: 5 };
  GRAMMAR.sort((a, b) => (lv[a.lvl] - lv[b.lvl]) || ((rank[a.id] ?? 99) - (rank[b.id] ?? 99)));
  Object.entries(UNITMAP).forEach(([gid, uid]) => { const u = UNITS.find(x => x.id === uid); if (u && !u.grammar.includes(gid)) u.grammar.push(gid); });
})();
